var e=JSON.parse(`[{"id":"overview-start","questions":["这个作品怎么看","从哪里开始看","页面怎么看"],"keywords":["怎么看","开始","介绍","作品","页面"],"answer":"建议先按三章顺序慢慢看哦。第一章“徽韵千年”先看地图、时间和建筑分布，建立整体印象；第二章“构筑万象”再看屋顶、马头墙、粉墙和天井，把建筑构件拆开理解；第三章“匠艺流芳”最后看人物、典籍和三雕文化，把建筑背后的工艺故事补起来。这样读会比较顺～"},{"id":"overview-huizhou","questions":["什么是徽派建筑","徽派建筑有什么特点"],"keywords":["徽派建筑","徽州","特点","白墙黛瓦"],"answer":"徽派建筑是明清时期在徽州一带形成的民居与礼制建筑体系，常见白墙黛瓦、马头墙、天井院落、砖木石三雕装饰。它既是居住空间，也承载宗族伦理、商业文化与地方审美。"},{"id":"overview-three-modules","questions":["三个模块分别讲什么","三章内容"],"keywords":["三个模块","三章","徽韵千年","构筑万象","匠艺流芳"],"answer":"「徽韵千年」看分布与留存；「构筑万象」看构件如何组成空间气质；「匠艺流芳」看三雕工艺与传承网络。三者由宏观到细部，再到手艺与人。"},{"id":"m1-intro","questions":["模块一讲什么","徽韵千年是什么"],"keywords":["模块一","徽韵千年","分布","地图"],"answer":"模块一像一张徽州古建筑总览：地图看空间格局，环形图看类型比例，折线看历朝留存，右侧看具体建筑叙事，底部时间轴看代表作命运。"},{"id":"m1-map-read","questions":["地图怎么读","热力图什么意思","古建筑分布图","模块一怎么操作"],"keywords":["地图","分布","热力","点位","徽州"],"answer":"模块一可以先看中间地图。颜色深浅代表不同地区古建筑数量的强弱，你可以悬停或点击县区查看提示信息，右侧面板和左侧图表也会跟着变化。往下还能看“徽韵遗产志”时间轴，鼠标移到节点上可以查看具体事件；如果已经知道建筑名称，也可以直接用搜索栏查找(｡･ω･｡)"},{"id":"m1-category","questions":["建筑类型有哪些","环形图表示什么"],"keywords":["类型","环形","祠堂","民居","牌坊"],"answer":"环形图展示不同建筑类型占比。祠堂承担宗族礼制，民居承载日常生活，牌坊记录荣誉与伦理，桥梁、驿站等则串联聚落交通与公共生活。"},{"id":"m1-dynasty","questions":["历朝留存怎么看","折线图什么意思"],"keywords":["历朝","折线","留存","朝代"],"answer":"折线/面积图反映各时期古建筑留存数量的变化。起伏往往与战乱、商业繁荣、地方治理、修缮保护有关，不要只盯某一个峰值。"},{"id":"m1-info-panel","questions":["右侧信息面板怎么用","怎么查看建筑详情"],"keywords":["信息面板","叙事","点击","建筑详情"],"answer":"在地图中点击城市或建筑标记，右侧面板会显示名称、背景与叙事文字。它把抽象数据点还原成可记忆的具体地点与故事。"},{"id":"m1-river","questions":["底部时间轴是什么","时间河流什么意思"],"keywords":["时间轴","河流","编年","代表作"],"answer":"底部「时间河流」把重要建筑与事件按年代排列。不同颜色标记初建、建设、损毁、修复、保护等状态，帮助理解单栋建筑在历史中的命运。"},{"id":"m1-xidi","questions":["西递宏村在哪里看","世界遗产"],"keywords":["西递","宏村","世界遗产","黟县"],"answer":"西递、宏村等标志性聚落可在模块一地图与叙事中检索。它们代表了徽州聚落与水系、街巷、民居格局相结合的典型模式。"},{"id":"m2-intro","questions":["模块二讲什么","构筑万象是什么"],"keywords":["模块二","构筑万象","构件"],"answer":"模块二聚焦徽派建筑的构件语言：马头墙、粉墙、天井、屋顶。左侧扇形切换主题，右侧四块区域分别展示不同类型的图表，帮助比较与理解。"},{"id":"m2-fan","questions":["扇形怎么切换","怎么换构件","模块二怎么切换内容"],"keywords":["扇形","切换","构件","点击"],"answer":"模块二主要通过左侧扇形区切换构件专题。你可以在屋顶、马头墙、粉墙和天井之间切换，每个专题都会对应一组不同图表。屋顶重点看玫瑰图、雷达图和关系图；马头墙重点看热力图、关系图和子图切换；粉墙重点看砌墙方式、关系图、词云和防热贡献；天井重点看气泡图、平行坐标、关系图和热环境分析。"},{"id":"matouqiang-basic","questions":["马头墙是什么","为什么叫马头墙"],"keywords":["马头墙","山墙","封火墙"],"answer":"马头墙是徽派民居两侧升高的山墙形式，因轮廓起伏似马头而得名。它既是村落天际线的节奏，也是重要的防火隔断构件。"},{"id":"matouqiang-fire","questions":["马头墙防火吗","马头墙有什么作用"],"keywords":["防火","封火","作用","马头墙"],"answer":"防火是马头墙最现实的功能之一：高墙可阻挡火势横向蔓延。研究也表明垂脊高度等因素会影响防火效果，通常需要达到一定高度才更稳妥。"},{"id":"matouqiang-zuotou","questions":["马头墙座头有哪些类型","印斗式朝笏式"],"keywords":["座头","印斗","朝笏","吻兽","鹊尾"],"answer":"座头常见印斗式、朝笏式、坐吻式、鹊尾式等。印斗象征印信权柄，朝笏寄托入仕理想，吻兽取镇邪防火之意，鹊尾则寓吉祥喜讯。"},{"id":"matouqiang-height","questions":["马头墙越高越好吗","垂脊高度"],"keywords":["高度","垂脊","0.5米"],"answer":"在一定范围内，马头墙高度与防火性能呈正相关，约 0.5 米上下常被视为较优区间，但并非越高越好，还需兼顾结构、风貌与村落肌理。"},{"id":"fenqiang-basic","questions":["粉墙是什么","白墙怎么做的"],"keywords":["粉墙","白墙","抹灰"],"answer":"粉墙是徽派建筑大面积白色或浅灰墙面，多用石灰等材料分层抹制。它提供清净底色，也关系防潮、耐候与近观肌理。"},{"id":"fenqiang-layer","questions":["粉墙有几层","粉墙工艺"],"keywords":["分层","工艺","抹灰","粉墙"],"answer":"传统粉墙常分多层：底层找平、中层加固、面层收光。不同层次决定墙面的耐久与细腻程度，也是模块二粉墙图表常比较的内容。"},{"id":"tianjing-basic","questions":["天井是什么","天井有什么用"],"keywords":["天井","院落","采光"],"answer":"天井是内向院落中的露天或半露天空间，负责采光、通风与排水，把自然引入封闭宅院，形成「四水归堂」的组织方式。"},{"id":"tianjing-sishui","questions":["四水归堂是什么意思"],"keywords":["四水归堂","排水","聚财"],"answer":"「四水归堂」指屋面雨水汇入天井，再经暗沟排出。它既是排水技术，也寄托财不外流、归家团圆的文化意味。"},{"id":"tianjing-light","questions":["天井采光好吗","天井热环境"],"keywords":["采光","热环境","通风","天井"],"answer":"天井能在高墙围合中引入光线与空气，改善室内环境。模块二天井相关图表常从热工、日照或通风角度解释这种内向空间的优势与局限。"},{"id":"wuding-basic","questions":["徽派屋顶有什么特点","屋顶形式"],"keywords":["屋顶","屋脊","瓦作","黛瓦"],"answer":"徽派屋顶多为坡屋面，黛瓦与白墙形成强烈对比。屋脊、屋角、瓦作细部决定建筑在天空下的剪影与地域识别度。"},{"id":"wuding-slope","questions":["屋顶坡度重要吗"],"keywords":["坡度","排水","屋顶"],"answer":"坡度关系排水、积雪与室内净高。徽州多雨，合理坡度与瓦作质量共同保证屋面耐久，也是模块二屋顶图表常分析的因素。"},{"id":"m3-intro","questions":["模块三讲什么","匠艺流芳是什么","模块三怎么用"],"keywords":["模块三","匠艺流芳","三雕"],"answer":"模块三可以先看顶部卡片，在“营建先哲”和“珍籍撷英”之间切换；再看中间关系图，把人物、典籍和工艺传承连起来；最后看右侧知识面板，了解工艺流程、常用纹样、工具材料和历史背景。简单说，就是按“人和书—关系网—具体知识”的顺序看～"},{"id":"sandiao-overview","questions":["三雕是什么","木雕砖雕石雕区别"],"keywords":["三雕","木雕","砖雕","石雕"],"answer":"三雕是木雕、砖雕、石雕的合称。木雕温润细腻，多饰梁枋隔扇；砖雕层次丰富，多饰门楼门罩；石雕庄重耐久，多饰牌坊柱础栏板。"},{"id":"mudiao","questions":["木雕在哪里","木雕特点"],"keywords":["木雕","梁架","雀替","隔扇"],"answer":"木雕常见于梁架、雀替、隔扇等处，擅长多层透雕与叙事场景。它往往承担祠堂、厅堂中最醒目的装饰与教化表达。"},{"id":"shidiao","questions":["石雕在哪里","石雕特点"],"keywords":["石雕","牌坊","柱础","栏板"],"answer":"石雕多用于牌坊、柱础、抱鼓石、栏板等，质感厚重，常承载礼制与纪念功能。棠樾牌坊群是徽州石雕的代表性案例。"},{"id":"zhuandiao","questions":["砖雕在哪里","砖雕特点"],"keywords":["砖雕","门楼","门罩"],"answer":"砖雕集中在门楼、门罩等立面部位，以青砖为胎，多层透雕形成叙事画面。它既是门面，也是家族身份与愿望的展示。"},{"id":"m3-switch-craft","questions":["怎么切换木雕石雕砖雕","三雕怎么换"],"keywords":["切换","木雕","砖雕","石雕","箭头"],"answer":"模块三中间大图两侧有三角按钮，可循环切换三雕；左下关系图与右侧详情会随当前雕种更新。界面引导也会自动帮你切换。"},{"id":"m3-graph","questions":["关系图怎么看","传承网络"],"keywords":["关系图","传承","师承","网络"],"answer":"左下关系图连接传承人、作品与层级。实线多表示师承或归属，虚线可表示指导，点大小区分国家级、省级、市级等传承级别。"},{"id":"m3-cards","questions":["营建先哲是什么","上面卡片是谁"],"keywords":["营建先哲","珍籍撷英","卡片"],"answer":"上方卡片展示历史上与营造相关的学者、官员与文献记录者，如李诫、计成、地方志纂修者等，说明徽派建筑不仅是工匠传统，也有知识体系支撑。"},{"id":"mudiao-process","questions":["木雕工序有哪些"],"keywords":["木雕","工序","打坯","精雕"],"answer":"木雕一般经历选料干燥、放样起稿、打坯定形、分层精雕、打磨上油等步骤。每一步都影响最终纹样的稳定与层次。"},{"id":"shidiao-process","questions":["石雕工序有哪些"],"keywords":["石雕","工序","打荒"],"answer":"石雕常见流程包括选料、切割整形、墨线起稿、打荒定形、细部精雕、打磨收光。石作更强调结构厚度与户外耐候。"},{"id":"zhuandiao-process","questions":["砖雕工序有哪些"],"keywords":["砖雕","工序","制坯"],"answer":"砖雕需先制坯烧砖、验砖窨水，再经放样、打坯分层、出细精雕，最后拼装挂镶。砖材易崩，刀路要轻稳。"},{"id":"heritage-national","questions":["国家级传承人","非遗传承人"],"keywords":["国家级","传承人","非遗"],"answer":"模块三关系图中较大节点常对应国家级代表性传承人。他们往往在技艺体系化、作品示范与带徒传承方面具有标杆意义。"},{"id":"heritage-provincial","questions":["省级传承人"],"keywords":["省级","传承人"],"answer":"省级传承人是地方技艺梯队的重要力量，往往深耕某一雕种或地域流派，与具体建筑案例、工作室名称相关联。"},{"id":"chengzhitang","questions":["承志堂是什么"],"keywords":["承志堂","宏村","木雕"],"answer":"承志堂是宏村著名民居，以精美木雕著称，常被作为徽州民居装饰艺术的代表案例，在模块三木雕关系中会出现。"},{"id":"tangyue","questions":["棠樾牌坊群"],"keywords":["棠樾","牌坊","石雕"],"answer":"棠樾牌坊群是徽州石雕与礼制空间的经典案例，七座牌坊序列化呈现家族伦理与功名传统，是读徽州石雕的重要入口。"},{"id":"xuguo-fang","questions":["许国石坊","八脚牌楼"],"keywords":["许国石坊","八脚","牌楼"],"answer":"许国石坊（八脚牌楼）位于歙县，是明代纪念性石坊的代表，结构复杂、雕刻精美，体现石雕与礼制叙事的最高水平之一。"},{"id":"horseshoe-fire","questions":["封火山墙"],"keywords":["封火山墙","防火"],"answer":"封火山墙即马头墙一类升高山墙的做法，核心目的是防止火灾在木构聚落间蔓延，同时塑造村落天际线。"},{"id":"courtyard-order","questions":["徽州民居布局"],"keywords":["布局","院落","中轴"],"answer":"徽州民居常以内向天井为核心，房间围合院落，形成层层递进的空间序列。高墙对外封闭，对内开放，兼顾安全与家族生活。"},{"id":"ancestral-hall","questions":["祠堂是什么"],"keywords":["祠堂","宗族","礼制"],"answer":"祠堂是宗族祭祀与议事的礼制建筑，常位于村落要位，装饰规格较高，木雕、石雕、砖雕往往最集中，体现家族地位与伦理秩序。"},{"id":"paifang","questions":["牌坊是什么"],"keywords":["牌坊","纪念","功名"],"answer":"牌坊是立于街巷或宅前的纪念性构筑，表彰功名、贞烈、善行等。徽州牌坊以石雕见长，是外部空间里最具识别度的礼制符号之一。"},{"id":"huizhou-merchant","questions":["徽商和建筑的关系"],"keywords":["徽商","经济","宅第"],"answer":"明清徽商兴盛，为家乡营建祠堂、宅第、书院提供了财力。建筑既是居住空间，也是展示家族成就与儒家理想的载体。"},{"id":"confucian","questions":["儒家文化和徽派建筑"],"keywords":["儒家","伦理","教化"],"answer":"儒家伦理深刻影响徽州建筑：祠堂强调忠孝节义，三雕题材常见历史典故与吉祥寓意，空间秩序体现长幼尊卑与家族认同。"},{"id":"geomancy","questions":["风水和徽州聚落"],"keywords":["风水","聚落","山水"],"answer":"徽州聚落多依山傍水，注重朝向、水口、街巷与山势关系。宏村牛形水系等案例体现了营建与自然环境协同的传统智慧。"},{"id":"material-wood","questions":["徽派建筑用什么木材"],"keywords":["木材","松","杉","木作"],"answer":"徽派木作常用当地适宜树种，强调含水率控制与阴干，避免后期开裂。木构榫卯与雕刻共同构成室内骨架与装饰。"},{"id":"material-brick","questions":["青砖怎么来"],"keywords":["青砖","制坯","烧制"],"answer":"砖雕用砖多由黄黏土制坯、控温烧成，要求质地细密、敲击有声。砖质决定后续雕刻是否易崩裂、层次是否干净。"},{"id":"material-stone","questions":["徽州用什么石头"],"keywords":["青石","茶园石","石材"],"answer":"石雕常用黟县青、茶园石等，要求纹理顺直、少暗裂，兼顾可雕性与户外耐候。"},{"id":"pattern-dragon","questions":["龙凤纹寓意"],"keywords":["龙凤","纹样","吉祥"],"answer":"龙凤纹象征尊贵祥瑞，常见于梁架节点或中心构图，多与云纹、卷草组合，形成主次分明的装饰层级。"},{"id":"pattern-bat","questions":["蝙蝠纹什么意思"],"keywords":["蝙蝠","福","谐音"],"answer":"「蝠」谐「福」，蝙蝠纹寓纳福之意，常与寿字、如意、莲花组合，表达福寿双全等祝愿。"},{"id":"pattern-hui","questions":["回纹是什么"],"keywords":["回纹","边框","连绵"],"answer":"回纹线条规整连绵，常作边框组织纹，稳住画面外缘节奏，防止主纹样发散。"},{"id":"pattern-scroll","questions":["卷草纹"],"keywords":["卷草","过渡","植物"],"answer":"卷草纹柔性流动，适合连接人物与器物、边饰与主体，让装饰画面更连贯自然。"},{"id":"tool-chisel","questions":["雕刻用什么工具"],"keywords":["凿","锤","刻刀","工具"],"answer":"三雕常用平凿、圆凿、斜口凿、小锤、磨料等，木作与石作、砖作在力度与刀路上各有讲究，模块三详情区有分雕种介绍。"},{"id":"yingzao-fashi","questions":["营造法式和徽州"],"keywords":["营造法式","李诫","材份"],"answer":"北宋《营造法式》系统官式营造体系，提出材份制等规范，对后世包括徽州祠堂木构在内的官式与地方做法均有深远影响。"},{"id":"yuan-ye","questions":["园冶和徽州"],"keywords":["园冶","计成","园林"],"answer":"明代计成《园冶》阐述园林营造与借景理水，其空间观念与徽州聚落、庭院组织有相通之处，影响乡土景观理解。"},{"id":"luban-jing","questions":["鲁班经匠家镜"],"keywords":["鲁班经","午荣","尺度"],"answer":"《鲁班经匠家镜》记录马头墙尺寸、天井比例、粉墙抹灰、瓦作规制等民间营造经验，是明清徽州匠作的重要参考。"},{"id":"local-gazetteer","questions":["徽州府志有什么用"],"keywords":["府志","方志","记载"],"answer":"历代《徽州府志》《歙县志》等方志系统记载民居、祠堂、牌坊规制与地域差异，是理解徽州建筑官方与民间规范的重要文献。"},{"id":"protection","questions":["古建筑怎么保护"],"keywords":["保护","修缮","非遗"],"answer":"保护需兼顾原形制、材料与工艺，避免不当翻新。当代还通过非遗传承人制度、数字化展示等方式延续技艺与公众认知。"},{"id":"digital-project","questions":["这个网站是做什么的"],"keywords":["可视化","数字","展示"],"answer":"本作品是徽派建筑数字展卷，用地图、统计图、构件专题与三雕交互，把文献与田野知识转化为可浏览、可提问的在线体验。"},{"id":"chart-wordcloud","questions":["词云图怎么看"],"keywords":["词云","关键词"],"answer":"词云把文本中的高频词放大显示。字号越大，说明在描述某一构件或主题时该词出现越频繁，可快速抓住讨论焦点。"},{"id":"chart-heatmap","questions":["热力图是什么"],"keywords":["热力图","矩阵"],"answer":"热力图用颜色深浅表示数值高低，适合比较多个类别在两个维度上的强度，例如不同形式、不同区域之间的关联强弱。"},{"id":"chart-sankey","questions":["桑基图是什么"],"keywords":["桑基","流向"],"answer":"桑基图展示流量或关系如何在不同类别间分配，带宽越宽表示数量或关联越强，适合看材料、类型、来源去向等结构。"},{"id":"chart-radar","questions":["雷达图怎么看"],"keywords":["雷达","多维"],"answer":"雷达图把多个指标画在放射轴上，适合比较一个对象在若干维度上的强弱，一眼看出偏科与优势。"},{"id":"chart-network","questions":["关系网络图"],"keywords":["网络图","节点","连线"],"answer":"节点代表人、作品或类别，连线代表师承、合作、归属等关系。节点大小、颜色常编码级别或类型，需结合图例阅读。"},{"id":"assistant-guide","questions":["界面引导怎么用","机器人怎么用","界面引导在哪里","展卷导览在哪"],"keywords":["引导","机器人","助手","小徽"],"answer":"点击页面右下角的小徽助手，选择“展卷导览”，就可以按步骤高亮当前页面的重点内容。你也可以不跟着步骤走，直接问小徽某张图怎么看、某个按钮怎么切换，或者这一页应该从哪里开始读。"},{"id":"m2-wd-read","questions":["屋顶专题怎么看","屋顶图怎么读"],"keywords":["屋顶","玫瑰图","雷达图","架屋"],"answer":"屋顶专题可以先看玫瑰图，了解不同屋顶类型的占比；再看雷达图，对比不同架屋形式在关键参数上的差异；最后看关系图，把屋顶和材料、构造、空间、审美等关键词联系起来。这样就能从“屋顶长什么样”进一步看到“它为什么这样建”啦～"},{"id":"m2-mtq-read","questions":["马头墙专题怎么看","马头墙图怎么读"],"keywords":["马头墙","热力图","关系图","子图"],"answer":"马头墙专题建议先看热力图或矩阵图，用颜色深浅判断不同类型和指标的差异；再看关系图，理解马头墙与防火、装饰、空间秩序等内容之间的联系；最后可以切换子图，对比不同表达方式下的结论是否一致。"},{"id":"m2-fq-read","questions":["粉墙专题怎么看","粉墙图怎么读"],"keywords":["粉墙","砌墙","词云","防热"],"answer":"粉墙专题可以先看主图，了解不同砌墙方式和热工性能之间的关系；再看关系图，理解粉墙在构造、功能和审美上的关联；然后看词云图，快速抓住高频关键词；最后看防热贡献图，把粉墙在保温、防热和环境适应方面的作用落下来。"},{"id":"m2-tj-read","questions":["天井专题怎么看","天井图怎么读"],"keywords":["天井","气泡图","平行坐标","热环境"],"answer":"天井专题可以先看气泡图，通过气泡大小、颜色和位置比较不同样本特征；再切换到平行坐标图，观察采光、通风、热环境等性能指标；之后看关系图，理解天井在空间组织中的作用；最后看热环境分析图，理解它怎样影响徽派建筑内部的光、风和温度。"},{"id":"assistant-start","questions":["不知道从哪里开始看","从哪里开始","怎么开始看"],"keywords":["开始","不知道","入口","引导"],"answer":"那就先让小徽带你走一遍吧(๑´ㅂ\`๑)它会先帮你找到页面最重要的入口，再带你看主图、切换区、关系图和详情面板。等你熟悉以后，就可以自己随便点点看，像逛一张会动的徽州建筑展卷一样～"},{"id":"assistant-drag","questions":["机器人能拖动吗"],"keywords":["拖动","隐藏","贴边"],"answer":"可以拖动机器人到屏幕任意位置。拖到上下左右边缘会半隐藏，只露出一小条，再点一下可恢复；拖动时请勿与点击菜单混淆。"},{"id":"huizhou-counties","questions":["徽州包括哪些地方"],"keywords":["徽州","歙县","休宁","黟县","婺源"],"answer":"历史上徽州辖歙县、休宁、祁门、黟县、绩溪、婺源等县。本作品地图与数据主要覆盖这一文化地理范围内的古建筑遗存。"},{"id":"whitewall-blacktile","questions":["白墙黛瓦"],"keywords":["白墙","黛瓦","黑白"],"answer":"白墙来自粉墙做法，黛瓦指深灰色小青瓦屋面。强烈对比是徽派建筑最直观的视觉符号，也契合文人审美中的素净与含蓄。"},{"id":"horse-head-types","questions":["马头墙有哪些形式"],"keywords":["一字","元宝","马头墙形式"],"answer":"村落中常见不同跌落形式与座头组合，形成一字形、元宝形等轮廓变化。比较这些形式有助于理解防火需求与装饰等级。"},{"id":"door-arch","questions":["门楼砖雕"],"keywords":["门楼","门罩","砖雕叙事"],"answer":"门楼砖雕常以段落式叙事组织：上部主题、中部故事、边饰过渡，把家族伦理与吉祥寓意编码进立面。"},{"id":"dou-gong","questions":["斗拱在徽派建筑里"],"keywords":["斗拱","木构"],"answer":"斗拱在徽州祠堂等重要木构中仍可见，承担受力与装饰双重角色，常与木雕、彩绘等结合，体现木作技艺层次。"},{"id":"window","questions":["徽州窗户有什么讲究"],"keywords":["窗","漏窗","采光"],"answer":"高墙小窗体现对外封闭、对内通透的策略。漏窗、隔扇等既有采光通风，也承载图案寓意与私密性控制。"},{"id":"water-system","questions":["宏村水系"],"keywords":["宏村","水系","牛形"],"answer":"宏村以牛形水系著称，月沼、南湖等水体与民居、街巷相互嵌套，是徽州聚落营建与自然环境协同的典范。"},{"id":"repair-principle","questions":["古民居修缮原则"],"keywords":["修缮","原真性"],"answer":"修缮应尽可能采用原工艺、原材料，保留历史层次，避免用现代材料粗暴替换导致风貌失真。模块一时间轴中的「修复」「保护」事件也反映这一历程。"},{"id":"fire-in-village","questions":["村落防火"],"keywords":["村落","防火","间距"],"answer":"徽州木构聚落防火依赖马头墙、巷道间距、水系与社区组织等多重手段，不单是某一栋建筑的问题。"},{"id":"symbolism-fu","questions":["吉祥图案有哪些"],"keywords":["吉祥","寓意","福禄寿"],"answer":"徽州装饰常见福禄寿、麒麟、龙凤、蝙蝠、莲花等母题，通过谐音与象征表达家族愿望，是读三雕纹样的重要钥匙。"},{"id":"story-carving","questions":["雕刻为什么讲故事"],"keywords":["故事","戏文","典故"],"answer":"人物故事、历史典故雕刻承担教化功能，让建筑立面成为「看得见的伦理课本」，尤其常见于祠堂与门楼。"},{"id":"season-maintenance","questions":["粉墙如何保养"],"keywords":["保养","粉墙","防潮"],"answer":"粉墙需防潮、防裂、定期修补。传统做法强调分层抹灰与适宜气候下施工，这也是粉墙能够长期保持白墙观感的原因。"},{"id":"tile-work","questions":["瓦作是什么"],"keywords":["瓦作","屋面","小青瓦"],"answer":"瓦作负责铺瓦、屋脊、滴水等屋面细节。小青瓦与马头墙、屋檐曲线共同构成徽派建筑上部轮廓。"},{"id":"carpenter","questions":["徽州木匠"],"keywords":["木匠","木作","匠师"],"answer":"徽州木作匠师掌握放样、榫卯、雕刻与安装，祠堂、民居的梁架与装修都依赖这一体系，模块三可见具体传承人网络。"},{"id":"stone-carver","questions":["石匠做什么"],"keywords":["石匠","石作"],"answer":"石匠负责牌坊、柱础、栏板、门楼石件等，工序从打荒到精雕，强调厚重与耐候，作品常位于建筑外部显眼位置。"},{"id":"brick-carver","questions":["砖雕师傅"],"keywords":["砖雕","砖匠"],"answer":"砖雕匠需在青砖上控制深浅层次与透空，作品多用于门楼，对胎料、刀路与拼装对缝要求极高。"},{"id":"comparison-jiangnan","questions":["徽派和江南民居区别"],"keywords":["江南","比较","区别"],"answer":"二者都重视白墙与小青瓦，但徽派更突出马头墙、天井与高墙封闭特征，装饰上三雕叙事更浓，聚落与宗族礼制关系也更紧密。"},{"id":"comparison-fujian","questions":["和福建土楼有什么不同"],"keywords":["土楼","福建","比较"],"answer":"福建土楼强调环形防御与集体聚居，徽派民居以天井院落、马头墙防火、三雕装饰见长，空间形态与社会结构背景不同。"},{"id":"unesco","questions":["有哪些世界遗产"],"keywords":["世界遗产","UNESCO"],"answer":"西递、宏村等徽州古村落被列入世界文化遗产，是理解徽派聚落价值的重要窗口，可在模块一与相关叙事中进一步探索。"},{"id":"data-source","questions":["数据从哪里来"],"keywords":["数据","来源","文献"],"answer":"模块一数据来自地方遗存统计、方志与项目整理；模块二、三结合设计文档、田野与公开文献。地图底图注明审图号，请以页面标注为准。"},{"id":"map-compliance","questions":["地图审图号"],"keywords":["审图号","地图","合规"],"answer":"模块一地图使用带审图号的标准底图，页面底部有来源与审图信息说明，展示时请注意 cartographic 合规要求。"},{"id":"iframe-why","questions":["为什么有些图在框架里"],"keywords":["iframe","嵌入"],"answer":"模块二、三的复杂图表以独立页面开发，通过 iframe 嵌入主应用，保证稳定交付；智能助手通过跨框架通信实现自动切换与高亮。"},{"id":"m2-panel-a","questions":["模块二左上图是什么"],"keywords":["左上图","panel","模块二"],"answer":"模块二左上是当前构件（如马头墙、天井等）的主图区，常是热力、玫瑰、平行坐标等最核心的一张，建议先看懂图例再读数值。"},{"id":"m2-panel-b","questions":["模块二右上图"],"keywords":["右上图","关系图"],"answer":"右上图多展示类型关系、结构比较或关联网络，帮助把左上图的信息放到更大分类体系里理解。"},{"id":"m2-panel-c","questions":["模块二词云在哪"],"keywords":["词云","左下"],"answer":"词云通常在左下区域，反映文献与描述中的高频词汇，是理解「人们如何谈论这一构件」的快捷入口。"},{"id":"m2-panel-d","questions":["模块二右下图"],"keywords":["右下","总结"],"answer":"右下图多为总结型、对比型或指标型图表，适合在浏览完其他区域后用来确认结论与重点。"},{"id":"m3-detail-tabs","questions":["右侧标签怎么切换","工序纹样工具"],"keywords":["标签","工序","纹样","工具"],"answer":"模块三右侧有「工序」「纹样」「工具」「寓意」「历史」等标签，点击可查看当前雕种的不同知识维度，配合中间大图一起阅读效果更好。"},{"id":"m3-level-filter","questions":["全谱国省是什么意思"],"keywords":["全谱","国省","筛选"],"answer":"关系图上方按钮可筛选传承人层级：「全谱」显示全部，「国+省」「国+省+市」逐步聚焦更高层级节点，便于看清核心传承脉络。"},{"id":"hongcun","questions":["宏村有什么建筑看点"],"keywords":["宏村","南湖","月沼"],"answer":"宏村以牛形水系、南湖、月沼及精美宅第著称，承志堂等民居木雕极具代表性，是模块一、三都可能提到的关键案例。"},{"id":"xidi-village","questions":["西递有什么特点"],"keywords":["西递","街巷"],"answer":"西递保存了大量明清古民居与街巷格局，牌坊、祠堂、民居层次丰富，适合观察徽州聚落肌理与礼制空间。"},{"id":"shexian","questions":["歙县为什么重要"],"keywords":["歙县","徽州府"],"answer":"歙县为历史上徽州府治所在，牌坊、祠堂、民居遗存密集，是理解徽州政治、经济与文化核心的重要区域。"},{"id":"wuyuan","questions":["婺源建筑"],"keywords":["婺源","徽州文化"],"answer":"婺源属徽州文化圈，村落、祠堂与三雕传统与皖南其他县一脉相承，在聚落与水口营造上也有独特案例。"},{"id":"courtyard-size","questions":["天井大小有讲究吗"],"keywords":["天井","尺度","比例"],"answer":"天井尺度关系采光、通风与排水效率，传统营造强调与宅院进深、屋面坡度相匹配，过深或过浅都会影响使用效果。"},{"id":"screen-wall","questions":["照壁是什么"],"keywords":["照壁","影壁"],"answer":"照壁（影壁）常设于入口，阻挡直视院落并具象征意义。徽州民居、祠堂入口处常见，与门楼砖雕共同构成礼仪序列。"},{"id":"flagship-river","questions":["时间轴上有哪些建筑"],"keywords":["代表作","时间轴","事件"],"answer":"底部时间轴汇集徽州代表性建筑与关键事件，悬停可查看年份、动作类型与地点，是模块一从历史维度收束阅读的入口。"},{"id":"huizhou-name","questions":["徽州为什么叫徽州"],"keywords":["徽州","名称"],"answer":"「徽州」得名与历史上的行政区划、山川形胜有关，明清时期这一带形成稳定的文化地理认同，徽派建筑正是其物质文化的重要载体。"},{"id":"yin-yang-roof","questions":["屋顶阴阳面"],"keywords":["阴阳","屋面"],"answer":"坡屋顶有阴阳两面，影响排水与日晒。徽州多雨，瓦作与坡度配合，使屋面耐久并塑造黛瓦反光质感。"},{"id":"snow-load","questions":["马头墙和雪"],"keywords":["雪","荷载"],"answer":"马头墙高耸，设计需兼顾防风、防火与结构稳定，并非单纯越高越好，要与木构架、屋面相协调。"},{"id":"ventilation","questions":["高墙怎么通风"],"keywords":["通风","高墙"],"answer":"高墙外闭内开，通过天井、窗扇与巷道风道组织气流，是在安全与舒适之间取得的平衡。"},{"id":"wood-insect","questions":["木构防虫"],"keywords":["防虫","木构"],"answer":"传统木作强调选料、干燥与漆油养护，减少虫蛀与开裂，这也是木雕能长期保存的前提。"},{"id":"stone-weathering","questions":["石雕风化"],"keywords":["风化","石雕"],"answer":"户外石雕会经历风化，传统做法保留适度工具纹与磨面过渡，兼顾手工质感与耐久。"},{"id":"brick-color","questions":["青砖颜色"],"keywords":["青砖","色泽"],"answer":"青砖并非纯黑，而是深灰偏青，与白墙对比柔和，随时间产生温润包浆感。"},{"id":"carving-depth","questions":["透雕和浅浮雕"],"keywords":["透雕","浮雕"],"answer":"透雕镂空最多、立体感最强；浅浮雕适合大面积墙面。三雕根据位置与功能选择技法。"},{"id":"master-apprentice","questions":["怎么拜师传承"],"keywords":["拜师","师承"],"answer":"传统匠作多靠家族、乡邻与作坊师承，今日通过国家与省级非遗传承人制度延续。"},{"id":"women-craft","questions":["女性和营造"],"keywords":["女性","营造"],"answer":"历史上营造以男性匠师为主，但家族生活空间、织绣等与建筑文化密切相关，研究需注意整体社会生活史。"},{"id":"music-in-festival","questions":["建筑与民俗"],"keywords":["民俗","节庆"],"answer":"祠堂、戏台等空间常承载节庆礼仪，建筑是民俗活动的舞台，不仅是静态外观。"},{"id":"education-huizhou","questions":["徽州教育"],"keywords":["书院","科举"],"answer":"徽州重教育，书院、家塾与科举成功又反哺家乡营建，形成「贾而好儒」的社会风气。"},{"id":"bridge-heritage","questions":["徽州古桥"],"keywords":["古桥","桥梁"],"answer":"古桥连接聚落与水路交通，是模块一建筑类型之一，体现技术与景观的结合。"},{"id":"well-water","questions":["水井和水口"],"keywords":["水井","水口"],"answer":"水口、井泉关系聚落用水与风水观念，是理解徽州聚落整体格局的要素。"},{"id":"fire-bucket","questions":["古代防火设施"],"keywords":["消防","防火"],"answer":"除马头墙外，村落还有水池、防火墙、巡查等传统防火手段，共同构成聚落安全网。"},{"id":"plaster-pigment","questions":["白墙会褪色吗"],"keywords":["褪色","粉墙"],"answer":"粉墙会随日照雨水轻微变化，需定期维护；传统分层做法延缓开裂与剥落。"},{"id":"roof-ridge","questions":["屋脊装饰"],"keywords":["屋脊","吻兽"],"answer":"屋脊吻兽等装饰有等级与寓意差异，在祠堂、民居上规格不同。"},{"id":"column-base","questions":["柱础是什么"],"keywords":["柱础","石雕"],"answer":"柱础承托木柱、防潮并装饰，石雕柱础常雕莲花、回纹等，是石作与木作的交接节点。"},{"id":"beam-carving","questions":["梁架雕刻"],"keywords":["梁架","雕"],"answer":"祠堂梁架雕刻规格高，题材多含教化故事，是木雕艺术的高峰区域。"},{"id":"screen-door","questions":["隔扇是什么"],"keywords":["隔扇","门窗"],"answer":"隔扇划分室内空间，雕刻精美，兼具通风采光与装饰功能。"},{"id":"study-room","questions":["书房空间"],"keywords":["书房","文人"],"answer":"徽州民居常设书房，反映重文传统，与庭院、天井采光紧密结合。"},{"id":"kitchen-fire","questions":["厨房和火塘"],"keywords":["厨房","火塘"],"answer":"厨房是日常火源所在，与天井通风、马头墙防火形成住宅内部火险管理的一环。"},{"id":"storage-grain","questions":["粮仓在哪里"],"keywords":["粮仓","储藏"],"answer":"高墙宅院内设储藏空间，适应山地农业与商业周转需求。"},{"id":"contractor","questions":["谁负责盖房子"],"keywords":["工匠","包工"],"answer":"传统营造由木、石、砖作匠师协作，业主（常是宗族或商人）定规制与规模。"},{"id":"cost-building","questions":["盖祠堂贵吗"],"keywords":["造价","祠堂"],"answer":"祠堂、牌坊等礼制建筑耗资巨大，反映家族实力与对公共荣誉的投资。"},{"id":"symbol-crane","questions":["仙鹤寓意"],"keywords":["仙鹤","寓意"],"answer":"仙鹤象征长寿，常与其他吉祥纹样组合出现在三雕题材中。"},{"id":"symbol-fish","questions":["鱼纹寓意"],"keywords":["鱼","余"],"answer":"鱼谐「余」，寓年年有余，是民间装饰常见母题。"},{"id":"symbol-lotus","questions":["莲花纹"],"keywords":["莲花","清廉"],"answer":"莲花象征清净吉祥，石作柱础、砖雕边饰中都很常见。"},{"id":"question-fallback-1","questions":["宏派建筑"],"keywords":["宏派"],"answer":"你或许想问的是「徽派建筑」——徽州一带形成的白墙黛瓦、马头墙、天井与三雕体系。"},{"id":"question-fallback-2","questions":["三雕工艺"],"keywords":["工艺"],"answer":"三雕指木雕、砖雕、石雕，分别在木构、门楼、石作部位发挥，模块三有分步讲解。"},{"id":"prep-sys-SYSQ001","questions":["这个系统主要包含了徽州建筑的哪些核心模块？每个模块分别侧重什么内容？","这个系统分为几个主要部分？每个部分的研究重点是什么？","我想了解这个系统的整体架构，它涵盖了徽州建筑的哪些方面？","能不能给我介绍一下这个平台的三大模块分别是什么？各自的侧重点是什么？","从系统目录来看，我能从这个平台上获取到关于徽州建筑的哪些维度的知识？"],"keywords":["系统","全览","系统总览与体系架构","模块","架构","屋顶","天井","粉墙","马头墙","三雕"],"answer":"这个系统围绕徽州建筑的核心要素，搭建了一个三模块的完整知识架构。\\n\\n模块一：建筑分布与建筑简介——这一部分主要负责对徽州地区宏观建筑文物名录资源和分布情况进行整体介绍，帮助用户建立整体认知框架。\\n\\n模块二：四大核心构件专题——这是系统的核心分析板块，细分了四个重要构件进行深度剖析：\\n- 屋顶：侧重类型识别和举架、举折的构造做法解析。\\n- 天井：利用气泡图评估不同尺寸天井的室内舒适度，利用折线图展示天井对室内气候的调节作用。\\n- 粉墙：分析不同材料（如石灰、糯米灰浆等）和不同做工对墙面质感和功能的影响。\\n- 马头墙：重点关注其防火性能的物理原理和构造优势。\\n\\n模块三：著作、科学家与三雕传承——追溯徽州建筑的营造知识体系和传承脉络，包括《营造法式》、《工程做法则例》等古代著作，以及徽州三雕（砖雕、木雕、石雕）的技艺传承关系与典型做法。"},{"id":"prep-sys-SYSQ002","questions":["我想了解徽州建筑在宏观尺度上的分布规律，系统里有相关的介绍吗？","模块一里有没有关于徽州村落或建筑群分布特征的汇总？","我想看看徽州建筑的整体地理分布和聚落形态，系统能否提供？","有没有关于徽州建筑选址和村落格局的宏观介绍？","系统是否能帮我了解徽州建筑和它所处自然环境之间的整体关系？"],"keywords":["系统","全览","建筑分布与环境关系","模块"],"answer":"是的，这一信息主要集中在模块一：建筑分布与建筑简介中。该模块以宏观视角系统性地展示了徽州建筑文物名录的地理分布、村落形态特征以及建筑群的典型布局模式（如枕山、环水、面屏的选址理念）。您可以借助这一模块快速了解徽州建筑在不同区域（如歙县、黟县、休宁等）的分布密度、聚落类型（如街巷式、围合式），以及它们与周边自然山水环境的整体适应关系，建立起理解后续构件细节的宏观语境。"},{"id":"prep-sys-SYSQ003","questions":["徽州建筑在选址上有哪些核心讲究？和系统里的哪些构件有直接关系？","系统有没有解释徽州建筑为什么要“依山傍水”进行修建？","建筑的选址理念和系统分析的哪些构件关联最深？","我想知道天井、马头墙这些构件是如何体现“风水”选址理念的？","这个系统能帮我理解“天人合一”的理念是如何通过建筑选址和构件设计落实的？"],"keywords":["系统","全览","建筑选址与环境逻辑","模块","屋顶","天井","马头墙"],"answer":"系统对选址理念的深度解析贯穿在多个模块中，尤其突出在模块一和模块二（天井与马头墙）。\\n\\n模块一会阐述徽州建筑“枕山、环水、面屏”的宏观选址原则，并指出其与通风、防潮、防御等功能需求的直接关联。\\n\\n在模块二中，具体构件是选址理念的具象体现：\\n- 天井（模块二）：作为“四水归堂”的物理核心，天井的尺寸、坡度和排水布局，直接体现了对“聚财”和“保风水”的追求。系统对其舒适度和气候调节作用的量化分析（如气泡图、折线图）正是从环境物理学角度印证了这些选址智慧的合理性与科学性。\\n- 马头墙（模块二）：高耸突出的墙体不仅是防火灾隔离带，在形态上也构成了村落天际线的重要部分，其“防火墙”的选址布局策略也需配合整村防火间距的考量。\\n\\n此外，“天人合一”这一核心理念，在模块二的“天井·关键词词云图”和“屋顶·关键词词云图”中均有突出展示，它解释了为何建筑布局要顺应自然地形（如坡屋顶坡度选择顺应山势）。"},{"id":"prep-sys-SYSQ004","questions":["系统能否帮我系统理解徽州建筑的整体营造体系？从地基到屋顶，构件之间是如何关联的？","我想了解徽州建筑“由下至上”的完整建造流程，系统有相关梳理吗？","系统里能不能看到屋顶、天井、粉墙、马头墙这些构件之间是怎么配合工作的？","我想知道一个完整的徽州宅院，它的结构逻辑是什么样的？","系统有没有从整体角度解析传统建筑是如何一步步建造起来的？"],"keywords":["系统","全览","营造体系与构造逻辑","模块","架构","屋顶","天井","粉墙","马头墙","三雕"],"answer":"是的，系统的三模块架构设计就是为了帮助您建立起从“宏观分布”到“核心构件解析”，再到“营造知识传承”的完整认知链路。\\n\\n第一步：选址与基础（模块一）——了解建筑群在村落中的分布规律，初步把握建筑坐落的整体环境和空间关系。\\n\\n第二步：核心构件拆解（模块二）——这是系统最详尽的部分：\\n- 屋顶：作为“建筑之冠”，决定了建筑的形制和等级，其中举架举折做法决定了坡面的曲线美感与排水效率；\\n- 天井：作为“建筑之肺”，负责采光、通风和雨水收集，与外围粉墙相配合，形成微气候循环；\\n- 粉墙：作为“建筑之肤”，包裹了建筑的围护结构，同时受不同材料做工影响；\\n- 马头墙：作为“建筑之盾”，在屋脊和山墙处突起，起到阻断火势蔓延的防火作用。\\n\\n第三步：知识传承与技艺渊源（模块三）——追溯到《营造法式》、《工程做法则例》等古代营造典籍，以及徽州三雕（砖雕、木雕、石雕）的传承脉络，解释这些构件从图纸到现实，再由工匠师徒代代相传的完整链条。"},{"id":"prep-sys-SYSQ005","questions":["徽州建筑的屋顶有很多不同的类型，它们在形制和做法上有何区别？系统里能找到这些信息吗？","我想知道硬山顶、悬山顶、歇山顶在徽州建筑中分别用于什么场合？","系统能否帮我区分不同屋顶的形制等级和构造做法？","屋顶上的“举折”和“举架”具体指的是什么？系统里有解释吗？","我看到徽州建筑屋顶曲线优美，这和什么技术做法有关？"],"keywords":["系统","全览","屋顶设计与营造","模块","屋顶","马头墙"],"answer":"当然可以。这些信息主要收录在模块二的“屋顶”部分中。\\n\\n关于屋顶类型：系统通过“屋顶·类型占比玫瑰图”提供了直观的统计分布。您可以看到：\\n- 硬山顶（含马头墙）占比最大（约28.6%），是徽州地区最常用的屋顶形式，因其山墙可与马头墙结合形成防火隔离。\\n- 悬山顶（约21.8%）次之，多用于等级稍高的民居或附属建筑。\\n- 歇山顶（约17.2%）等更高等级屋顶也有涉及。\\n不同类型的屋顶对应不同等级和空间需求，系统在“屋顶·形成逻辑关系图”中，从自然环境、生活需求、建筑技术、地域文化四个维度为您解析了为何徽州建筑偏向选择硬山顶和悬山顶。\\n\\n关于“举折”与“举架”：这是塑造屋顶坡面曲线的关键构造技术，在模块二右下角的“屋顶·举架关键参数雷达图”中有清晰展示：\\n- 举架：指房屋的步架与举高之间的比例关系，决定了屋顶各段的陡缓程度。\\n- 举折：指利用不同步架的举高差异，在屋面自然形成一条向下弯曲的弧线（凹曲面）的做法。通过这一技术，徽州屋顶不仅能快速排水，还能在视觉上营造出轻盈、舒展的效果，完美体现了“反宇向阳”的古建筑美学。"},{"id":"prep-sys-SYSQ006","questions":["天井的大小对室内的舒适度有什么影响？系统里有相关的科学数据或图表吗？","我想知道天井尺寸是如何影响居住感受的？","系统有没有用数据图表展示不同尺寸天井的通风和温湿度变化？","天井的“和风区占比”是什么意思？和舒适度有什么关系？","如果我想优化天井设计以达到更好的热环境效果，系统能给我什么参考？"],"keywords":["系统","全览","天井的物理性能与环境调节","模块","天井"],"answer":"是的，这部分内容系统在模块二的“天井”部分中提供了非常详细的数据图表支持。\\n\\n关于天井尺寸与舒适度的关系：请查阅左上角的“天井·性能评估气泡图”。\\n- 横轴代表“天井尺寸”（数值通常在10到22之间），纵轴代表“和风区占比”（舒适通风面积占天井总面积的比例）。\\n- 通过气泡的分布位置，您可以直观看到趋势：通常尺寸越大（横轴向右），和风区占比越高（纵轴向上），对应较大的天井往往能提供更优的自然通风效果和更舒适的室内风环境（如编号WJ36的大型天井，和风区占比高达70%以上）。\\n\\n关于天井对室内环境的实际调节效果：请查阅右下角的“天井·冬季热环境影响分析”折线图。\\n- 该图展示了从“入口 → 庭院 → 天井 → 门厅 → 厅房”这一空间递进序列中，温度和湿度的变化规律。\\n- 温度：天井处的平均温度（约12-13℃）显著高于入口（约4-5℃），但低于最终的厅房（约15℃），证明天井是连接室内外并缓冲冷空气的关键过渡空间。\\n- 湿度和风速：天井处的湿度（约80%-82%）和风速（约0.25-0.30 m/s）也处于一个相对均衡的中间值，避免了室外湿冷空气直接涌入室内，起到了“气候过滤器”的作用。"},{"id":"prep-sys-SYSQ007","questions":["徽州建筑标志性的“粉墙”，它的材料和做工有什么特别之处？系统能查到具体做法的差异吗？","徽州粉墙为什么能保存得那么久？用了什么特殊的材料？","系统里有没有对比不同粉墙工艺（如石灰、糯米灰浆）效果的内容？","我想了解粉墙的施工工序，以及不同做法对墙体寿命的影响。","粉墙的“白”和普通的白墙有什么本质区别？系统有解释吗？"],"keywords":["系统","全览","粉墙的材料与工艺","模块","粉墙"],"answer":"是的，关于“粉墙”的详细材料和工艺差异分析，属于模块二的“粉墙”部分的核心内容。\\n\\n关于材料差异：系统会对比分析徽州传统粉墙常用的不同结合材料：\\n- 石灰：是基础材料，提供基本的白度和粘合度。\\n- 糯米灰浆：将煮熟并捣烂的糯米浆掺入石灰膏中，具有极佳的抗拉强度和防水防渗能力，这也是许多徽州古墙历经数百年仍不剥落的关键原因之一。系统可能会展示糯米灰浆和普通石灰浆在微观结构或耐久性测试上的对比分析。\\n\\n关于做工影响：系统会解析分层抹灰的工艺层次：底糙层（找平）、中间层（巩固）、罩面层（装饰），以及“打底灰”、“纸筋灰”等不同层级所用的材料配比差别。墙面的光洁度（是“光面”还是“糙面”）和灰层的厚度，会直接影响墙体的抗风化能力和对气候湿度的调节作用。\\n\\n总结：通过“粉墙”部分，您将了解到，看似简单的“白墙”，其实隐藏着复杂的材料科学和精湛的工匠经验，是徽州建筑耐久性与美观性并重的重要基石。"},{"id":"prep-sys-SYSQ008","questions":["马头墙的防火原理是什么？系统里有没有提供这方面的详细资料？","马头墙为什么能阻止火势蔓延？它的构造原理是什么？","系统有没有分析马头墙的防火性能和设计要点？","我想知道为什么徽州建筑要建这么高的墙头，它和防火有什么关系？","马头墙的高出屋面部分在防火中起到了什么作用？"],"keywords":["系统","全览","马头墙的防火原理与技术","模块","天井","粉墙","马头墙"],"answer":"是的，这部分的核心数据和分析可以在模块二的“马头墙”部分中找到。\\n\\n防火原理：马头墙的本质是一种封火墙（防火隔离墙）。其关键原理是：\\n1. 高度阻隔：马头墙高于屋面（通常超出屋面0.5-1.5米甚至更高），可以阻断火焰从相邻建筑通过屋檐或木结构蔓延过来的路径。当一栋建筑起火时，高耸的马头墙就像一道坚实的屏障。\\n2. 材料特性：与木质的梁柱和屋架不同，马头墙通常用砖石砌筑，表面再涂以石灰粉刷（粉墙），本身就是难燃或不燃材料，不会像木材那样作为燃料。\\n3. 结构构造：马头墙的厚度和砌筑方式（通常为实心或一顺一丁的丁砌结构），使其具备足够的结构强度和热稳定性，不易因热辐射而倒塌。\\n\\n系统内的具体分析方式：在“马头墙”板块中，您会看到相关的性能示意图或逻辑分析图。它会将马头墙的“高度参数”、“墙体厚度”、“材料特性”以及“与相邻建筑的距离”等参数，与其“阻止火势跨墙蔓延的有效率”进行关联展示（类似于天井气泡图）。这个板块还会将马头墙的防火性能与徽州建筑高密度的村落环境结合分析，解释其作为“建筑之盾”在保护徽州古村落整体安全中的核心价值。"},{"id":"prep-sys-SYSQ009","questions":["系统里除了马头墙，还有其他构件涉及到防火功能吗？有没有对建筑防火体系的综合评价？","徽州建筑的防火措施是不是就靠马头墙？还有没有其他手段？","我想了解整个建筑的防火体系是如何通过不同构件协同工作的。","系统有没有分析粉墙、屋顶和天井在防火中的辅助作用？","能不能帮我系统梳理徽州建筑的“防灾”或“防火”设计智慧？"],"keywords":["系统","全览","构件综合防火评价","模块","屋顶","天井","粉墙","马头墙"],"answer":"是的，马头墙只是徽州建筑综合防火体系中的一个突出环节，系统通过模块二的分析，揭示了多个构件在防火中的协同作用：\\n\\n1. 马头墙（核心防火构件）：作为主要的防火墙，通过高突的砖石墙身阻断火势沿屋檐横向蔓延。\\n\\n2. 天井（辅助消防与隔离）：天井空间在火灾中扮演了“天然火场缓冲区”的角色。天井中的蓄水池（或水缸、水井） 提供了近距离、不可替代的消防水源（参见“天井”部分的“蓄水缸”关键词），同时天井的空间开阔性也能起到一定的热量释放和烟气排放作用。\\n\\n3. 粉墙（被动防火保护）：粉墙对内部木结构的包裹，能够延缓火灾对核心结构柱和梁的侵蚀。部分史料记载的“墙体刷白”也使其在夜间更易辨识道路和逃生口，但这更多是辅助作用。\\n\\n4. 屋顶（控制火势向上）：传统的坡屋顶和举折做法中，木构梁架和瓦片的布置方式在一定程度上能延缓火势穿透屋顶的速度，为人员转移争取时间。\\n\\n综合评价：系统通过将这四个构件的防火功能联动起来（尤其是在模块二的宏观逻辑图或模块总结中），向您展示了徽州建筑是一个“防火墙阻断 + 消防水源就近 + 围护结构包裹 + 木结构延缓”的多层次、立体化防火系统。这一智慧源于在高度密集的乡村环境中长期应对火灾挑战的实践经验。"},{"id":"prep-sys-SYSQ010","questions":["天井是如何利用“烟囱效应”和“热压通风”原理来调节微气候的？","“烟囱效应”在传统天井中是如何实现的？系统里有没有物理原理图？","天井的通风原理是什么？如何实现无动力降温换气？","我想从热物理学角度理解天井的空气流动机制。","系统是如何分析和解释天井的垂直通风能力的？"],"keywords":["系统","全览","构件物理原理综合","模块","天井"],"answer":"天井利用“烟囱效应”和“热压通风”实现室内外空气循环，是传统建筑中精妙的无动力通风技术，这一原理在模块二的“天井·关键词词云图”中有明确的术语标注（“烟囱效应”、“热压通风”），并在“天井·形成逻辑关系图”中作为“通风需求”的关键实现方式被深度解析。\\n\\n具体原理：\\n1. 热压通风：天井在白天吸收太阳辐射，其内部空气温度升高。由于热空气密度小（质量轻），它会自然向上浮升，从而在天井顶部形成正压区。\\n2. 烟囱效应：随着天井上部的热空气不断排出室外，天井底部（地面及周边房间门口）会形成低气压区（负压区）。\\n3. 自然换气：由于压强差的存在，周围房间内相对凉爽的空气被“吸入”天井底部，参与循环。空气通过天井向上抽升、排出，形成持续的对流。\\n\\n系统如何量化展示：您也可以参考模块二右下角的“冬季热环境影响分析” 折线图。虽然该图侧重于温度/湿度/风速数据，但它展示了天井作为一个微气候管理节点，在入口与室内的多重空间中实现了显著的空气混合和温湿度平衡调节过程——这正是热压通风和烟囱效应共同工作后的宏观表现。"},{"id":"prep-sys-SYSQ011","questions":["在建筑物理中，“步架”、“举高比”、“和风区占比”这些参数分别是衡量什么的？","屋顶的“步架”和“举高比”是用来计算什么的？","天井的“和风区占比”是什么概念？和通风效果有什么关系？","系统中有哪些关键的物理计算参数？它们有什么实际意义？","如何用这些参数来量化评估传统建筑的性能？"],"keywords":["系统","全览","物理参数与计算指标","模块","屋顶","天井"],"answer":"这些关键物理参数分别对应模块二的“屋顶”和 “天井” 部分，是系统对传统建筑进行科学量化分析的重要工具。\\n\\n1. 步架（屋顶部分）\\n- 衡量对象：相邻两根檩条之间的水平距离。\\n- 实际意义：它是构成屋顶“举折”技术的基础单位。通过调整每个“步”上的举高（垂直高度），工匠可以控制屋面的不同坡度，从而形成整体平滑而优雅的凹曲面。这也是决定屋面排水速度和结构稳定性的关键参数。\\n\\n2. 举高比 H/L（屋顶部分）\\n- 衡量对象：屋顶总垂直高度（H）与水平跨度（L）之间的比值。\\n- 实际意义：这个比值决定了屋顶的陡峭程度。比值越高（如0.5），屋顶越陡，排水越快，但在视觉上更显庄重宏伟；比值越低，屋顶越平缓，显得舒展。它是古建筑等级和形制的重要指标。\\n\\n3. 和风区占比（天井部分）\\n- 衡量对象：在天井空间的有效面积内，能够获得良好自然通风的区域所占的比例（百分比）。\\n- 实际意义：它直接量化了天井的通风性能。通过“天井·性能评估气泡图”，您可以看到不同尺寸天井的和风区占比变化趋势，从而预判该天井能为周围房间提供多大程度的舒适新风。"},{"id":"prep-sys-SYSQ012","questions":["系统里有没有将建筑构件与其文化象征意义（如“四水归堂”、“天人合一”）结合起来分析的板块？","我想知道天井的“四水归堂”不仅仅是个说法，它在系统和物理上是怎么体现的？","有没有哪个部分专门讲“天人合一”思想如何在建筑构件中落实？","我在词云里看到了“聚财”、“风水”，这些概念对应哪些具体构件和做法？","系统能否帮我理解徽州建筑中“形式”与“意义”之间的关系？"],"keywords":["系统","全览","构件的文化内涵与符号","模块","屋顶","天井","粉墙","马头墙","三雕"],"answer":"是的，这部分是模块二（尤其是“天井”、“屋顶”部分）与模块三紧密衔接的核心特色。\\n\\n模块二中，每个构件的页面都包含一个“关键词词云图”，它直观地将物质构件（如“砖雕”、“木雕”、“粉墙”）与核心文化理念（如“四水归堂”、“天人合一”、“聚财”、“风水”）并列。\\n\\n- 天井：如“四水归堂”不仅是一个吉祥的词汇，在物理上对应着天井中央的排水明沟、蓄水缸和坡顶内向的构造。系统通过逻辑关系图表明：这一构造的灵感源于哲学思想和风水观念，最终“聚财”和“蓄水”的功能双双得以实现。\\n- 屋顶：在“屋顶·形成逻辑关系图”中，“等级制度”直接导向特定屋顶类型的选择，说明了屋顶形制是社会等级和礼制观念的物理体现。\\n- 马头墙：除了防火，其阶梯状、不断升高的形态在文化上也被赋予“步步高升”的美好寓意。\\n\\n模块三则更进一步，通过追溯《营造法式》与徽州工匠的传承，探讨了这些文化理念是如何通过“徽州三雕”（砖、木、石雕）等技术工艺，被具象化地雕刻在构件（如窗棂、雀替、门楼）之上的，实现了设计理念→构造做法→匠人传承的文化闭环。"},{"id":"prep-sys-SYSQ013","questions":["《营造法式》和《工程做法则例》这两本书与徽州建筑有什么关系？系统里有介绍吗？","《营造法式》对徽州建筑的影响体现在哪些地方？","系统里有没有介绍徽州工匠参考过哪些古代官方营造典籍？","李诫的《营造法式》和清代的《工程做法则例》在徽州建筑中有应用吗？","我想了解宋代和清代官方规范与徽州地方做法之间的传承关系。"],"keywords":["系统","全览","传统匠师与营造著作","模块","三雕"],"answer":"是的，这些信息和梳理主要收录在模块三：著作、科学家与三雕传承中。\\n\\n《营造法式》的影响：\\n- 背景：由北宋李诫编纂，是中国第一部官方建筑技术标准。\\n- 对徽州的影响：徽州建筑的许多核心形制（如梭柱、月梁、上昂铺作等）都与《营造法式》中记载的做法高度吻合。系统将会通过图文对比，展示徽州现存早期建筑（如绩溪龙川胡氏宗祠、西递、宏村的部分祠堂）中符合《营造法式》规范的木构节点实例，证明徽州匠人确实继承并发展了这一宋代官方体系。\\n\\n《工程做法则例》的影响：\\n- 背景：清代雍正年间颁布的官方建筑规范。\\n- 对徽州的影响：虽然徽州地区相对封闭，但清代随着徽商的兴盛和建筑的规模升级，部分大型宅第和宗族祠堂也引入了清代官式做法（如更标准化的斗拱、梁枋比例和举架算法）。系统会展示这些影响是如何渗透到地方工匠体系中，并与徽州本地习惯相结合，形成独特的“徽州清代做法”的。\\n\\n核心价值：模块三不仅介绍这两本书籍的内容，更深入探讨了它们是如何通过师徒传承和匠人流动，将国家层面的规范沉淀到徽州地方营造体系中的，为你理解“徽州建筑”与“中国建筑主流技术”之间的血缘关系提供了权威背景。"},{"id":"prep-sys-SYSQ014","questions":["我想系统了解徽州“三雕”（砖雕、木雕、石雕）的传承关系和典型做法，系统里有相关的介绍吗？","徽州三雕的传承脉络是什么？它们之间有什么区别和联系？","模块三里有没有介绍砖雕、木雕、石雕的典型工艺和师徒传承？","我想知道“三雕”在徽州建筑中分别应用在什么位置，有什么经典做法？","系统能否帮我梳理徽州三雕从选材、设计到雕刻成型的完整工艺链？"],"keywords":["系统","全览","徽州三雕技艺与传承","模块","三雕"],"answer":"是的，这一系统性的梳理和展示是模块三：著作、科学家与三雕传承的核心功能之一。\\n\\n关于传承关系：系统会详细梳理“徽州三雕”的传承脉络：\\n- 纵向传承：从唐宋至明清，徽州三雕技艺如何代代相传，并形成了不同的地域流派（如歙县派、休宁派等）和家族传承谱系。\\n- 横向关系：虽然“三雕”统称“三雕”，但砖雕多用于门楼、照壁；木雕多用于梁架、窗扇、栏杆；石雕多用于柱础、栏板、门额。系统会展示它们之间在题材、构图和技法上的相互借鉴与融合。\\n\\n关于典型做法：系统会通过图解、实物照片和工艺流程图，详细解析典型作品的制作流程：\\n- 砖雕：讲究“铲、凿、剔、刻”等手法，代表作如门罩上的戏曲人物故事。\\n- 木雕：讲究“圆雕、浮雕、透雕”的组合运用，代表作如窗棂上的“渔樵耕读”或“福禄寿喜”。\\n- 石雕：讲究“线刻、平雕、浮雕”，代表作如祠堂前的牌坊基座、石狮、蟠龙柱。\\n\\n关于应用位置：系统会直观标注三雕在建筑平面图和立面图上的分布位置（如木雕在门窗、砖雕在门楼、石雕在柱础）。这部分内容将与模块二的构件分析形成对应，帮助您将三雕的艺术表现与具体的承重、围合、装饰构件的功能和结构紧密结合。"},{"id":"prep-sys-SYSQ015","questions":["这个系统对现代建筑修缮或新建筑设计有什么参考价值？","我从这个系统能学到什么来应用在现代建筑设计上？","在修复古建筑时，这个系统能提供哪些关键数据和方法？","传统天井的通风原理，可以运用于现代住宅设计吗？系统里有没有启示？","系统对于“新徽派”建筑的设计创新有没有提供数据或理论支撑？"],"keywords":["系统","全览","古建筑修缮与现代设计启发","模块","架构","屋顶","天井","粉墙","马头墙","三雕"],"answer":"这个系统的三模块架构，为现代建筑提供了从“数据实证”到“设计理念”的完整参考价值：\\n\\n1. 对古建筑修缮的指导价值：\\n- 模块二提供的精确物理数据（如天井气泡图的和风区占比、冬季热环境曲线、屋顶举高比参数）是指导修复工作的科学依据。例如，若要恢复某个天井的原貌，但发现其当前的气泡坐标偏离历史设计基准（和风区占比过低），修缮时可以依据原数据进行结构调整。\\n- 模块三对于“三雕”传统做法的工艺记录，为修复过程中还原细部技法提供了蓝本。\\n\\n2. 对现代新建筑设计的启发价值：\\n- 气候适应性设计：天井（模块二） 的“烟囱效应”和“热压通风”原理，可以被转化为现代中庭设计或被动式建筑的核心策略。在现代住宅或商业空间中，合理设计通高中庭和通风口，可以大大降低夏天空调能耗。\\n- 防火体系思维：马头墙作为建筑之间的“防火隔离带”，其设计思路可与现代建筑防火分区、防火墙概念结合，在村镇规划和建筑群设计中创造性地解决传统密集聚落与现代防火规范的衔接问题。\\n- 材料与耐久性：粉墙的“糯米灰浆”等传统材料配比的耐久性表现，可启发现代墙体材料研发，寻找传统天然材料与现代建筑材料性能优点结合的“新质”外墙方案。\\n\\n总结：系统不仅是知识的“档案馆”，更是现代设计灵感的“孵化器”。它将传统徽州建筑解决物理问题的“地方性智慧”，转化为通用且可量化的“建筑原理”。"},{"id":"prep-err-ERR001","questions":["你是谁呀？","你好，请问你是？","你是谁？","介绍一下你自己吧。","你叫什么名字？","hello，你是什么系统？","hi，能告诉我你是做什么的吗？","你好呀，你是什么软件？","你是什么助手？","我能叫你什么？","你是谁？为什么在这里？","请问你是什么类型的机器人？","你好，你的名字是？","你好，你是小助手吗？","你是谁？我不认识你。","介绍一下你的功能。"],"keywords":["助手","小徽","异常输入处理-问候与身份","机器人"],"answer":"您好！我是徽州建筑综合分析系统的智能助手，专注于为您解析模块一的建筑分布、模块二的核心构件（屋顶/天井/粉墙/马头墙）数据，以及模块三的营造著作与三雕传承。如果您想了解某个具体构件的物理性能、文化内涵或防火原理，可以直接告诉我哦！"},{"id":"prep-err-ERR002","questions":["1   跑跑跑","跑跑跑","1","12345","abcde","&*%#@!","qqqq","zzz","你好 1 2 3","asdfghjkl","!@#$%^","112233","喵喵喵","哈哈哈哈哈","水水水水","随便打几个字"],"keywords":["助手","小徽","异常输入处理-无意义乱码"],"answer":"抱歉，我暂时无法理解您输入的这串信息。我的系统数据库目前只支持与徽州建筑、构件性能、三雕技艺以及相关营造著作（如《营造法式》）有关的问题。如果需要帮助，您可以尝试输入诸如 '天井通风原理'、'马头墙防火' 或 '屋顶举架' 这类关键词。"},{"id":"prep-err-ERR003","questions":["今天天气怎么样？","今天几号？","现在几点了？","帮我算一下1+1等于多少？","你是人工智能吗？","讲个笑话吧。","明天会下雨吗？","我想听首歌。","你会写诗吗？","请帮我想个网名。","怎么去北京？","我的手机没电了怎么办？","你吃饭了吗？","你住在哪里？","有什么电影推荐？","请帮我翻译一下‘你好’的英文。"],"keywords":["助手","小徽","异常输入处理-无关问题"],"answer":"抱歉，我的系统是一个聚焦于徽州古建筑构件数据分析的知识库，并没有接入实时气象、通用百科或娱乐功能。关于 '今天天气怎么样？'，建议您使用手机上的天气App或者搜索引擎查询。如果您想了解徽州建筑的微气候调节能力（例如天井的冬季热环境），我可以为您调取相关数据图表。"},{"id":"m1-qa-Q001","questions":["徽州地区共有多少处各级重点文物保护单位（古建筑）？","徽州古建筑文物单位的总数量是多少？","统计到的徽州各级古建筑有多少处？","我想知道徽州地区古建筑文物的总数","767处这个数字是徽州所有古建筑的数量吗？","你能告诉我徽州一共登记了多少处古建筑文物吗？","徽州一府六县的重点古建筑加起来大概有多少？"],"keywords":["模块一","徽韵千年","总体概况","徽州","婺源","绩溪","767","民居"],"answer":"截至2026年2月，徽州一府六县核心区域（包括黄山市全域、宣城市绩溪县、上饶市婺源县）共统计到767处各级重点文物保护单位（古建筑）。其中县级465处、市级103处、省级149处、国家级50处。需要说明的是，这个数字只包含列入文物保护名录的古建筑，并且已经剔除了1911年以后的建筑以及遗址、墓碑、庙宇、宝塔等非民居类建筑。"},{"id":"m1-qa-Q002","questions":["徽州古建筑主要有哪些类型？各类型数量是多少？","徽州古建筑的类型分布是怎样的？","徽州最多的古建筑类型是什么？","徽州的祠堂、民居、牌坊分别有多少处？","徽州古建筑中桥梁占比多少？","能不能给我列一下徽州各类型古建筑的数量？"],"keywords":["模块一","徽韵千年","总体概况","徽州","767","牌坊","祠堂","民居","桥梁"],"answer":"767处古建筑按类型划分：民居253处，占总数的33.0%；祠堂186处，占比24.2%；桥梁132处，占比17.2%；牌坊86处，占比11.2%；综合用途或建筑群39处，占比5.1%；其他类型71处，占比9.3%。可以看出，民居是数量最多的建筑类型，其次是祠堂和桥梁。"},{"id":"m1-qa-Q003","questions":["徽州古建筑的年代分布有什么特点？","徽州明清时期的古建筑占比多少？","徽州最早的古建筑是什么朝代的？","徽州明代和清代的古建筑分别有多少处？","为什么徽州古建筑大多是明清时期的？","唐宋时期的徽州古建筑多吗？"],"keywords":["模块一","徽韵千年","总体概况","徽州","黟县","祁门","屯溪","明清"],"answer":"徽州古建筑呈现“明清绝对主导”的特点。具体年代分布为：唐代及以前10处，宋元时期18处，明代198处，清代540处。明清两代的建筑合计占比高达96.09%。其中祁门县和屯溪区的古建筑甚至全部为明清时期遗存，而黟县的明清占比更是达到了98.8%，是纯度最高的地区。"},{"id":"m1-qa-Q004","questions":["徽州哪个地区的古建筑数量最多？","婺源县和歙县哪个古建筑更多？","徽州各县区古建筑数量排名是怎样的？","徽州古建筑最集中的地方是哪里？","哪个县的古建筑最多？","我想知道徽州各县古建筑数量对比"],"keywords":["模块一","徽韵千年","总体概况","徽州","歙县","婺源","黟县","绩溪","祁门","休宁","屯溪","徽州区","黄山区"],"answer":"按总数量从高到低排名：婺源县241处（第一），歙县201处（第二），黟县86处，绩溪县81处，祁门县40处，休宁县40处，屯溪区25处，徽州区33处，黄山区20处。婺源和歙县两地合计占了徽州古建筑总量的57.6%，是名副其实的古建筑大县。"},{"id":"m1-qa-Q005","questions":["徽州哪个地区的古建筑密度最高？","单位面积古建筑最多的徽州地区是哪个？","屯溪区的古建筑密度是多少？","徽州古建筑密度排名是怎样的？","面积小的地方密度是不是更高？"],"keywords":["模块一","徽韵千年","总体概况","徽州","歙县","婺源","黟县","绩溪","祁门","休宁","屯溪","徽州区","黄山区"],"answer":"按每百平方千米的古建筑数量计算，密度排名为：屯溪区13.09个/百km²（第一），黟县10.04个/百km²，歙县9.47个/百km²，婺源县8.12个/百km²，徽州区7.69个/百km²，绩溪县7.19个/百km²，休宁县1.88个/百km²，祁门县1.81个/百km²，黄山区1.14个/百km²。屯溪区面积小、历史商贸发达，因此密度遥遥领先。"},{"id":"m1-qa-Q006","questions":["徽州哪个地区的高等级古建筑（国省级）最多？","徽州国家级古建筑最多的县是哪个？","歙县有多少处国家级古建筑？","徽州国省级古建筑密度最高的地区是哪里？","哪些地方的“含金量”更高？"],"keywords":["模块一","徽韵千年","总体概况","徽州","歙县","婺源","黟县","绩溪","祁门","休宁","屯溪","徽州区","黄山区","国省级"],"answer":"按国省级古建筑总数量排名：歙县73处（国家级21+省级52），遥遥领先；其次是绩溪县38处（3+35），黟县17处（4+13），徽州区13处（7+6），婺源县12处（5+7），休宁县18处（4+14），祁门县12处（1+11），屯溪区7处（3+4），黄山区9处（2+7）。如果考虑密度，屯溪区以3.66个/百km²排第一，歙县3.44个/百km²第二，绩溪县3.37个/百km²第三。"},{"id":"m1-qa-Q007","questions":["徽州古建筑的核心分布特征是什么？","徽州古建筑在空间和时间上有什么分布规律？","徽州古建筑最突出的特点是什么？","能不能总结一下徽州古建筑的分布特征？"],"keywords":["模块一","徽韵千年","总体概况","徽州","歙县","婺源","黟县","绩溪","屯溪","徽州区","牌坊","明清","国省级"],"answer":"徽州古建筑的分布特征可以总结为五点：第一，空间密度上，屯溪区、黟县、歙县单位面积古建筑最多；第二，高等级价值上，歙县、屯溪区、绩溪县、徽州区的国省级古建筑含金量最高；第三，时间分布上，歙县和婺源县绝对数量最多，且都以明清建筑为主体；第四，历史纵深上，歙县拥有最多的唐以前及宋元早期遗存；第五，类型丰富度上，歙县的建筑种类最全，光牌坊就有55处，为徽州之最。"},{"id":"m1-qa-Q008","questions":["歙县的古建筑情况是怎样的？","歙县有多少处各级古建筑？","歙县的古建筑类型分布如何？","歙县明清古建筑占比多少？","歙县有什么值得看的古建筑？"],"keywords":["模块一","徽韵千年","分地区详情","徽州","歙县","许国","棠樾","渔梁","牌坊","祠堂","民居","桥梁","明清"],"answer":"歙县共有各级古建筑201处，其中国家级21处、省级52处、市级15处、县级113处。类型分布：民居49处、祠堂56处、牌坊55处、桥梁7处、综合建筑群3处、其他31处。年代分布上，唐以前7处、宋元10处、明代58处、清代126处，明清占比91%。可以说，歙县是徽州牌坊最多、历史遗存最悠久、高等级古建筑最集中的地区，许国石坊、棠樾牌坊群、渔梁坝都在这里。"},{"id":"m1-qa-Q009","questions":["婺源县的古建筑情况是怎样的？","婺源县为什么古建筑数量最多？","婺源县的桥梁有多少处？","婺源县的牌坊为什么这么少？","婺源的古建筑有什么特色？"],"keywords":["模块一","徽韵千年","分地区详情","徽州","婺源","牌坊","祠堂","民居","桥梁","明清"],"answer":"婺源县共有各级古建筑241处，数量居徽州第一。其中国家级5处、省级7处、市级22处、县级207处。类型分布极具特色：桥梁78处（徽州最多），民居103处，祠堂38处，牌坊仅1处，综合建筑群5处，其他16处。年代分布：唐以前1处、宋元5处、明代32处、清代203处，明清占比97.5%。婺源水系发达，因此古桥梁特别密集，清华彩虹桥就是其中的代表。"},{"id":"m1-qa-Q010","questions":["黟县的古建筑情况是怎样的？","黟县有多少处国家级古建筑？","黟县为什么没有牌坊？","黟县的民居占比多少？","宏村和西递在哪个县？"],"keywords":["模块一","徽韵千年","分地区详情","徽州","黟县","宏村","西递","牌坊","祠堂","民居","桥梁","明清"],"answer":"黟县共有各级古建筑86处，其中国家级4处（宏村、西递、南屏、屏山舒氏宗祠）、省级13处、市级17处、县级52处。类型分布：民居46处，占比高达53.5%；祠堂18处；桥梁6处；牌坊0处；综合建筑群9处；其他7处。年代分布上，唐以前1处、宋元0处、明代11处、清代74处，明清占比98.8%，是徽州明清建筑纯度最高的地区。虽然没有牌坊，但宏村和西递的世界文化遗产地位无可替代。"},{"id":"m1-qa-Q011","questions":["绩溪县的古建筑情况是怎样的？","绩溪县的祠堂有多少处？","绩溪县的古建筑密度是多少？","龙川胡氏宗祠在哪个县？"],"keywords":["模块一","徽韵千年","分地区详情","徽州","绩溪","龙川","牌坊","祠堂","民居","桥梁","明清","国省级"],"answer":"绩溪县共有各级古建筑81处，其中国家级3处（龙川胡氏宗祠、奕世尚书坊和胡炳衡宅、上庄古建筑群）、省级35处、市级2处、县级41处。类型分布：民居24处、祠堂26处、牌坊9处、桥梁8处、综合建筑群11处、其他3处。年代分布：唐以前0处、宋元2处、明代21处、清代58处，明清占比97.5%。绩溪县的国省级古建筑密度位居徽州第三，龙川胡氏宗祠的“木雕博物馆”美誉享誉中外。"},{"id":"m1-qa-Q012","questions":["徽州区的古建筑情况是怎样的？","徽州区有哪些著名的古建筑群？","徽州区的国家级古建筑有多少处？","呈坎、唐模属于哪个区？"],"keywords":["模块一","徽韵千年","分地区详情","徽州","徽派","徽州区","呈坎","牌坊","祠堂","民居","桥梁","明清"],"answer":"徽州区共有各级古建筑33处，其中国家级7处（潜口民宅、老屋阁及绿绕亭、罗东舒祠、呈坎村古建筑群、洪坑牌坊群及洪氏家庙、蜀源牌坊群、唐模檀干园）、省级6处、市级5处、县级15处。类型分布：民居6处、祠堂8处、牌坊7处、桥梁5处、综合建筑群3处、其他4处。年代分布：唐以前0处、宋元1处、明代22处、清代10处，明清占比97%。呈坎八卦村、潜口民宅、唐模村都是体验徽派建筑的绝佳去处。"},{"id":"m1-qa-Q013","questions":["祁门县、休宁县、屯溪区、黄山区的古建筑情况分别是怎样的？","祁门县的古戏台有多少处？","屯溪区的国家级古建筑有哪些？","休宁县的古建筑为什么这么少？","黄山区有什么古建筑？"],"keywords":["模块一","徽韵千年","分地区详情","徽州","祁门","休宁","屯溪","黄山区","祠堂","桥梁","明清"],"answer":"祁门县共40处，其中国家级1处（祁门古戏台群）、省级11处、市级14处、县级14处。祠堂21处占52.5%，全部为明清建筑。休宁县共40处，其中国家级4处（溪头三槐堂、黄村进士第、休宁登封桥、休宁同安堂）、省级14处、市级10处、县级12处。桥梁10处，明清占比97.5%。屯溪区共25处，其中国家级3处（程大位故居、程氏三宅、屯溪镇海桥）、省级4处、市级13处、县级5处。全部为明清建筑，古建筑密度徽州第一。黄山区共20处，其中国家级2处（兴村程氏宗祠、黄山登山古道及古建筑）、省级7处、市级5处、县级6处。祠堂9处，明清占比95%。"},{"id":"m1-qa-Q014","questions":["宏村古建筑群的历史沿革是怎样的？","宏村是什么时候建的？","宏村的牛形水系是怎么形成的？","承志堂是哪一年建造的？","宏村为什么被称为“牛形村”？"],"keywords":["模块一","徽韵千年","代表性建筑","徽派","黟县","宏村","明清","承志堂"],"answer":"宏村位于黟县，始建于南宋绍兴元年（1131年）。明永乐年间，汪辛之妻胡重主持风水规划，开凿月沼和水圳，奠定了牛形水系的基础。明万历三十五年（1607年），汪氏宗族又开凿南湖，最终形成“山为牛头、树为角、屋为牛身、桥为脚”的完整牛形村落格局。明清时期因徽商崛起达到鼎盛，清嘉庆十九年（1814年）建南湖书院，清咸丰五年（1855年）建被誉为“民间故宫”的承志堂。宏村是徽派水系村落的杰出典范。"},{"id":"m1-qa-Q015","questions":["西递村古建筑群的历史沿革是怎样的？","西递村的胡氏家族是怎么来的？","胡文光刺史牌坊建于哪一年？","西递村的船形布局是怎么形成的？","西递为什么叫“桃花源里人家”？"],"keywords":["模块一","徽韵千年","代表性建筑","徽州","徽派","婺源","黟县","西递","牌坊"],"answer":"西递村位于黟县，为明经胡氏聚居地。唐末，唐昭宗之子为避朱温之乱，被婺源人胡三收养，改名胡昌翼，是为明经胡氏始祖。北宋皇祐初年（1049-1050年），胡昌翼五世孙胡仕良迁居西递，正式开村。明代景泰年间，随着徽商兴起，村落沿三条溪流扩展，形成独特的船形布局。明万历六年（1578年）建胡文光刺史牌坊，成为明代徽派石坊的代表作。清康乾至道咸年间达到鼎盛，建有走马楼、追慕堂、西园等标志性建筑，曾有“三千烟灶九千丁”的盛况。村中大夫第的“作退一步想”门额，尽显徽州人的处世哲学。"},{"id":"m1-qa-Q016","questions":["许国石坊有什么特别之处？","许国石坊为什么是八脚的？","许国石坊建于哪一年？","许国石坊的历史价值是什么？","全国唯一的八脚牌坊在哪里？"],"keywords":["模块一","徽韵千年","代表性建筑","歙县","许国","牌坊"],"answer":"许国石坊位于歙县，建于明万历十二年（1584年），是全国罕见的八柱石牌坊，堪称明代石构建筑的孤例。它是为表彰大学士许国平定云南叛乱功绩而敕建。有趣的是，许国采用“先斩后奏”的方式，将工期延至八个月，建成了逾制的八脚牌坊，回朝后借皇帝“八脚也早就造好了”的戏言使其合法化。石坊通体青石构筑，雕刻精美，历经500余年仍保存完好，是皇权褒奖与建筑艺术完美结合的典范。"},{"id":"m1-qa-Q017","questions":["棠樾石牌坊群的“忠孝节义”分别对应哪座牌坊？","棠樾有多少座牌坊？","棠樾牌坊群的建造时间跨度是多久？","乐善好施坊是哪一年建的？","哪座牌坊代表“义”？"],"keywords":["模块一","徽韵千年","代表性建筑","歙县","棠樾","牌坊"],"answer":"棠樾石牌坊群位于歙县，由7座牌坊纵向排列而成，建造时间从明永乐十八年（1420年）到清嘉庆二十五年（1820年），跨度长达400年，集齐了“忠、孝、节、义”四大主题。具体对应：忠——鲍象贤尚书坊（明天启二年，1622年）；孝——慈孝里坊（明永乐十八年，1420年）、鲍灿坊（明嘉靖十三年，1534年）、鲍逢昌孝子坊（清嘉庆二年，1797年）；节——鲍文龄妻汪氏节孝坊（清乾隆四十一年，1776年）、鲍文渊继妻吴氏节孝坊（清乾隆五十二年，1787年）；义——乐善好施坊（清嘉庆二十五年，1820年）。每座牌坊背后都有一个感人至深的故事。"},{"id":"m1-qa-Q018","questions":["渔梁坝的历史和作用是什么？","渔梁坝是什么时候建成的？","渔梁坝为什么被称为\\"徽州都江堰\\"？","渔梁坝的建造工艺有什么特点？","渔梁坝为什么被称为“徽州都江堰”？","渔梁坝对徽商有什么意义？"],"keywords":["模块一","徽韵千年","代表性建筑","徽州","歙县","渔梁"],"answer":"渔梁坝位于歙县，是新安江上游最重要的水利工程，被誉为“徽州都江堰”。它始建于隋末唐初，当时垒木桩为坝；唐开元年间正式筑坝成形；南宋绍定二年改为石坝；明万历三十三年（1605年）大规模重建，采用“元宝钉”和“燕尾锁”将花岗岩条石相互连接，形成坚固的重力滚水坝，现存主体即为此期所建。渔梁坝兼具防洪、灌溉、航运功能，是古代徽州水运的核心码头，支撑了徽商数百年的贸易繁荣。"},{"id":"m1-qa-Q019","questions":["龙川胡氏宗祠为什么被称为“木雕博物馆”？","龙川胡氏宗祠建于哪一年？","奕世尚书坊是谁题写的？","胡宗宪与龙川胡氏宗祠有什么关系？"],"keywords":["模块一","徽韵千年","代表性建筑","徽派","绩溪","龙川","三雕"],"answer":"龙川胡氏宗祠位于绩溪县，始建于宋代，后毁于兵燹。明嘉靖二十六年（1547年），兵部尚书胡宗宪主持重建，现存主体为明代遗构，清光绪年间大修后形成“明体清饰”的独特风貌。宗祠集徽派砖、木、石三雕之大成，尤以木雕最为精湛，正厅的荷花图隔扇民间传为明代大画家徐渭的稿本，因此被誉为“木雕博物馆”。宗祠西侧的奕世尚书坊建于明嘉靖四十一年，坊上“奕世尚书”“奕世宫保”八字为文徵明手书，弥足珍贵。"},{"id":"m1-qa-Q020","questions":["呈坎村古建筑群的风水布局有什么特点？","呈坎村为什么叫\\"八卦村\\"？","罗东舒祠有什么特别之处？","呈坎村为什么叫“八卦村”？","呈坎村的女祠是怎么回事？"],"keywords":["模块一","徽韵千年","代表性建筑","徽州","徽州区","呈坎"],"answer":"呈坎村位于徽州区，始建于唐末。江西南昌的罗天真、罗天秩兄弟为避黄巢之乱迁居于此，依《易经》风水理论将村落改名为“呈坎”，并规划了“二圳五街九十九巷”的八卦布局，因此被称为“八卦村”。村中核心建筑罗东舒祠始建于明弘治十一年，万历年间续建，占地5亩，四进四院，后寝达11开间，规制罕见，素有“江南第一祠”之称。祠内藏有董其昌手书“彝伦攸叙”巨匾。特别值得一提的是，享堂南侧附建了女祠“内则”，开创了再婚妇女亦可入祠的先河，体现了徽州文化中进步的一面。"},{"id":"m1-qa-Q021","questions":["其他代表性建筑的基本信息是什么？","屯溪镇海桥的历史是怎样的？","程大位故居有什么意义？","清华彩虹桥是宋代的吗？","祁门古戏台有什么价值？"],"keywords":["模块一","徽韵千年","代表性建筑","徽州","歙县","婺源","祁门","屯溪","徽州区","牌坊","廊桥"],"answer":"这里简要介绍几处：屯溪镇海桥（老大桥），始建于明嘉靖十五年（1536年），清康熙年间由程子谦父子两次重建，有“父子修桥”的佳话，2020年遭洪水冲毁后按原貌修复。程大位故居位于屯溪区，始建于明弘治年间，是珠算大师程大位的出生地，他在这里完成了珠算经典《直指算法统宗》。清华彩虹桥位于婺源县，始建于宋代，是江南现存最早、保存最完整的廊桥之一。祁门古戏台是明代戏曲建筑遗存，为徽州目连戏、徽剧发展的重要实物载体。竹山书院位于歙县，建于清代，是徽商“贾而好儒”精神的标志性遗存。洪坑牌坊群及洪氏家庙位于徽州区，为明代礼制建筑典范。"},{"id":"m1-qa-Q022","questions":["什么是徽派建筑？主要分布在哪些地区？","徽派建筑的核心分布区是哪里？","古徽州包括现在的哪些地方？","徽派建筑为什么那么有名？"],"keywords":["模块一","徽韵千年","建筑总体介绍","徽州","徽派","歙县","婺源","黟县","绩溪","祁门","休宁","屯溪","徽州区","黄山区","明清","三雕"],"answer":"徽派建筑是中国传统建筑流派中的一颗璀璨明珠，主要分布于古徽州一府六县，也就是现在的安徽省黄山市（歙县、黟县、休宁县、祁门县、徽州区、屯溪区、黄山区）、宣城市绩溪县以及江西省上饶市婺源县。它以明清时期为鼎盛，是徽州地理环境、宗族文化与商贸经济深度融合的产物，以“粉墙黛瓦、马头墙、三雕”为鲜明标识。"},{"id":"m1-qa-Q023","questions":["徽派建筑的核心特征是什么？","徽派建筑有哪些标志性元素？","粉墙黛瓦马头墙是徽派建筑的特点吗？","徽派建筑和别的流派有什么不同？"],"keywords":["模块一","徽韵千年","建筑总体介绍","徽派","宏村","呈坎","祠堂","民居","马头墙"],"answer":"徽派建筑的核心特征可以概括为四个方面：第一，外观标识——粉墙黛瓦、马头墙、小青瓦、高脊飞檐，形成素雅明快的视觉风格。第二，结构特点——多采用穿斗式与抬梁式结合的木结构，注重通风防潮与空间利用。第三，工艺特色——集木雕、石雕、砖雕“三绝”于一体，题材涵盖山水花鸟、人物典故，雕刻精美。第四，布局特点——遵循宗族礼制，以祠堂为核心、民居环绕，村落多依山水格局规划，如宏村的牛形水系、呈坎的八卦布局。"},{"id":"m1-qa-Q024","questions":["徽派建筑的“三雕”指的是什么？","徽派建筑的雕刻工艺有什么特点？","木雕、石雕、砖雕分别用在什么地方？","哪里的木雕最出名？"],"keywords":["模块一","徽韵千年","建筑总体介绍","徽派","黟县","宏村","许国","龙川","牌坊","桥梁","承志堂","三雕"],"answer":"“三雕”指木雕、石雕、砖雕，是徽派建筑工艺的精华。木雕主要用于梁架、斗拱、门窗、隔扇、栏杆等部位，题材丰富，工艺精湛，龙川胡氏宗祠的荷花木雕被称为“木雕博物馆”。石雕主要用于牌坊、桥梁、柱础、石狮等部位，材质多为黟县青和花岗岩，代表如许国石坊、胡文光刺史牌坊。砖雕主要用于门楼、照壁、窗楣等部位，以青砖为原料，雕刻精细，宏村承志堂的砖雕门楼就是典型代表。"},{"id":"m1-qa-Q025","questions":["这些古建筑数据的来源是什么？统计截止到什么时候？","数据是最新的吗？","国家级文物名录更新到哪一批？","你们的统计数据可靠吗？"],"keywords":["模块一","徽韵千年","数据来源","婺源","绩溪"],"answer":"本数据统计截止到2026年2月，所有数据均来自政府及博物馆官方网站。具体包括：黄山市各级文物名录来自黄山市人民政府官网；安徽省第九批省级文物保护单位来自安徽省人民政府官网（2026年2月9日发布）；江西省第七批省级文物保护单位来自江西省人民政府官网（2025年7月18日发布）；绩溪县数据来自绩溪县博物馆官网；婺源县数据来自婺源县人民政府官网和江西省文化和旅游厅官网。国家级文物保护单位名录目前更新至2019年第八批，第九批预计2026年中旬发布，暂未纳入本次统计。"},{"id":"m1-qa-Q026","questions":["数据统计时排除了哪些建筑类型？","为什么数据里没有庙宇和宝塔？","1911年后的建筑为什么不统计？","是不是所有古建筑都统计了？"],"keywords":["模块一","徽韵千年","数据来源","徽州","767","牌坊","祠堂","民居","桥梁"],"answer":"为了保证研究的聚焦性和数据的可比性，我们排除了以下三类：第一，1911年以后建造或重建的建筑（因为研究的是传统古建筑的原生形态）；第二，遗址、墓碑、步道、庙宇、宝塔、石窟等非民居类建筑（主要聚焦于民居、祠堂、牌坊、桥梁等核心类型）；第三，不属于徽州一府六县核心区域的建筑（如泾县、浮梁县的建筑仅作参考，未纳入767处的总数）。"},{"id":"m1-qa-Q027","questions":["数据有误差吗？误差范围是多少？","为什么实际看到的古建筑比统计的多？","统计误差是怎么产生的？","这个数据精确吗？"],"keywords":["模块一","徽韵千年","数据来源","民居","文保"],"answer":"由于各地区统计标准和口径存在差异，数据可能存在3%到5%的误差，但这个误差范围整体不影响分析结论。需要特别说明的是，我们的数据只统计了各级重点文物保护单位中的古建筑，实际存在的未列入文保名录的历史建筑数量远远多于这个数字（比如很多村落中未被定级的古民居），但那部分数据很难全面准确地统计。"},{"id":"m1-qa-Q028","questions":["古建筑密度是怎么计算的？","密度计算公式是什么？","地区面积数据来自哪里？","为什么屯溪区密度那么高？"],"keywords":["模块一","徽韵千年","数据来源","屯溪"],"answer":"古建筑密度的计算公式为：密度（个/百平方千米）=（该地区古建筑总数 ÷ 该地区总面积）× 100。各地区面积数据均来自当地人民政府官网公布的官方行政区划面积。以屯溪区为例，总面积仅191平方公里，却拥有25处古建筑，因此密度高达13.09个/百平方千米。"},{"id":"m1-qa-Q029","questions":["徽州古建筑中明代的比清代的多吗？","明代建筑在徽州占比更高吗？","清代建筑是不是比明代少？","哪个朝代的建筑更多？"],"keywords":["模块一","徽韵千年","反向确认","徽州","明清"],"answer":"不是的。徽州古建筑中清代有540处，明代只有198处，清代建筑数量是明代的2.7倍。明清两代合计占比96.09%，但清代明显多于明代。这主要是因为清代社会稳定、经济繁荣，加上徽商在清代达到鼎盛，因此建造了大量建筑。"},{"id":"m1-qa-Q030","questions":["婺源县的牌坊数量是徽州最多的吗？","婺源有很多牌坊吗？","哪个县的牌坊最多？","歙县的牌坊多还是婺源多？"],"keywords":["模块一","徽韵千年","反向确认","徽州","歙县","婺源","许国","棠樾","牌坊"],"answer":"不是的。婺源县只有1处牌坊，而歙县拥有55处牌坊，是徽州牌坊最多的地区，占徽州牌坊总数的64%。棠樾牌坊群、许国石坊、稠墅牌坊群等都在歙县。"},{"id":"m1-qa-Q031","questions":["黟县没有国家级古建筑吗？","黟县的国保单位有哪些？","宏村是国家级文物吗？","西递是国保吗？"],"keywords":["模块一","徽韵千年","反向确认","黟县","宏村","西递","国保"],"answer":"有的。黟县有4处国家级重点文物保护单位，分别是宏村古建筑群、西递村古建筑群、南屏村古建筑群和屏山舒氏宗祠。宏村和西递还是世界文化遗产，级别非常高。"},{"id":"m1-qa-Q032","questions":["所有数据都包含了泾县和浮梁县的古建筑吗？","泾县属于徽州地区吗？","浮梁县的建筑算徽派吗？","为什么泾县的古建筑没有统计进去？"],"keywords":["模块一","徽韵千年","反向确认","徽州","徽派","767"],"answer":"没有。泾县和浮梁县虽然与徽州地区接壤，也分布着不少徽派建筑，但它们不属于古徽州一府六县的核心区域，因此其古建筑仅作参考，并未纳入本次767处的统计总数中。附件2中我们有标注“不属于徽州地区，但和XX接壤”的字样。"},{"id":"m1-qa-Q033","questions":["徽州地区共有多少个国家级传统村落？","徽州国家级传统村落的总数是多少？","徽州有多少个中国传统村落？","哪个县的国家级传统村落最多？","歙县的传统村落数量在全国排第几？"],"keywords":["模块一","徽韵千年","历史村落","徽州","歙县","婺源","黟县","绩溪","祁门","休宁","屯溪","徽州区","黄山区","传统村落"],"answer":"徽州一府六县核心区域共有369个国家级传统村落。按数量排名：歙县167个（全国县级第一）、黟县46个、休宁县37个、祁门县33个、绩溪县31个、婺源县30个、黄山区13个、徽州区12个、屯溪区0个。歙县的传统村落数量在全国县级行政区中名列前茅，堪称“传统村落第一县”。"},{"id":"m1-qa-Q034","questions":["徽州有多少个中国历史文化名村？","徽州历史文化名村名单有哪些？","哪个县的历史文化名村最多？","西递宏村是历史文化名村吗？"],"keywords":["模块一","徽韵千年","历史村落","徽州","歙县","婺源","黟县","绩溪","祁门","休宁","徽州区","宏村","西递","渔梁","呈坎"],"answer":"徽州共有26个中国历史文化名村。按数量排名：婺源县7个、黟县6个、歙县5个、绩溪县3个、徽州区3个、休宁县1个、祁门县1个。代表村落包括西递、宏村、呈坎、唐模、渔梁、理坑等。其中西递和宏村还是世界文化遗产。"},{"id":"m1-qa-Q035","questions":["徽州有多少个中国历史文化名镇？","徽州历史文化名镇有哪些？","许村镇是历史文化名镇吗？","万安镇有什么特色？"],"keywords":["模块一","徽韵千年","历史村落","徽州","歙县","休宁","徽州区","许国"],"answer":"徽州共有3个中国历史文化名镇，分别是：安徽省黄山市歙县的许村镇、安徽省黄山市休宁县的万安镇、安徽省黄山市徽州区的西溪南镇。许村镇以许国石坊和许村古建筑群闻名，万安镇曾是休宁县治所在，保留着万安老街，西溪南镇则有千年古村西溪南。"},{"id":"m1-qa-Q036","questions":["徽州有多少个国家历史文化名城？","徽州国家历史文化名城名单","黟县是国家历史文化名城吗？","歙县是历史文化名城吗？"],"keywords":["模块一","徽韵千年","历史村落","徽州","歙县","黟县","绩溪"],"answer":"徽州共有3个国家历史文化名城，分别是：安徽省黄山市的歙县、安徽省宣城市的绩溪县、安徽省黄山市的黟县。这三个县都保留了大量的历史文化遗产，其中歙县是古徽州府治所在地，历史文化积淀最为深厚。"},{"id":"m1-qa-Q037","questions":["徽派建筑的马头墙有什么作用？","为什么徽派建筑有马头墙？","马头墙只是装饰吗？","马头墙能防火吗？"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","徽派","马头墙"],"answer":"马头墙是徽派建筑的标志性元素，主要作用有三个：第一，防火——相邻建筑发生火灾时，高耸的马头墙能阻断火势蔓延，因此也叫“封火墙”或“风火墙”；第二，防风——徽州山区多风，高大的马头墙能降低风速，保护房屋结构；第三，装饰——高低错落的马头墙形成丰富的天际线，具有独特的审美价值，同时“马头”也寓意“马到成功”。"},{"id":"m1-qa-Q038","questions":["徽派建筑的天井有什么功能？","什么是\\"四水归堂\\"？","天井为什么要向内倾斜？","什么是“四水归堂”？","天井能调节温度吗？"],"keywords":["模块一","徽韵千年","建筑工艺","徽派","民居","天井"],"answer":"天井是徽派民居的核心空间，主要功能有：第一，通风采光——解决了封闭式合院的通风和采光问题；第二，排水——屋顶雨水通过天井排入地下，形成“四水归堂”的格局，寓意“肥水不流外人田”；第三，调节气候——天井能形成空气对流，夏季降温、冬季保温；第四，文化寓意——天井象征“天人合一”，是人与自然沟通的空间。"},{"id":"m1-qa-Q039","questions":["什么是徽州古建三绝？","徽州最具代表性的三种建筑是什么？","古建三绝指的是哪三个？","为什么称它们为三绝？"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","徽派","牌坊","祠堂","民居"],"answer":"徽州古建三绝指的是民居、祠堂、牌坊，它们是徽派建筑最具代表性的三种类型。民居是徽州人日常生活的载体，体现了实用与审美的完美结合；祠堂是宗族祭祀和议事的场所，是宗族制度的物化体现；牌坊是封建礼制的象征，用于旌表功名、节孝、长寿等。这三种建筑共同构成了徽州村落的社会空间和伦理秩序。"},{"id":"m1-qa-Q040","questions":["徽州牌坊有哪些类型？","牌坊是用来做什么的？","功德坊和节孝坊有什么区别？","牌坊有几种？"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","许国","棠樾","牌坊"],"answer":"徽州牌坊按功能主要分为四类：功德坊——表彰官员的政绩和军功，如许国石坊、鲍象贤尚书坊；节孝坊——表彰妇女的贞节和孝道，如棠樾的鲍文龄妻汪氏节孝坊；百岁坊——表彰长寿老人；标志坊——用于村落入口或道路旁，起到标识作用。按建筑材料可分为石牌坊、木牌坊、砖牌坊，其中石牌坊数量最多、保存最完好。"},{"id":"m1-qa-Q041","questions":["徽州祠堂的布局有什么特点？","祠堂一般有几进？","祠堂的核心部分是什么？","为什么祠堂的门楼特别精美？"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","呈坎","祠堂"],"answer":"徽州祠堂一般采用中轴线对称布局，典型的祠堂为三进三开间或三进五开间。第一进为门楼（常做成五凤楼形式），是祠堂的门面，砖雕、石雕最为精美；第二进为享堂，是宗族议事和举行祭祀仪式的主要场所，空间最为开阔；第三进为寝堂，是供奉祖先牌位的地方，通常不对外开放。部分大型祠堂还设有偏房、戏台、花园等附属建筑，如呈坎罗东舒祠还附建了女祠。"},{"id":"m1-qa-Q042","questions":["徽州三雕的题材主要有哪些？","三雕上都刻些什么内容？","雕刻图案有什么寓意？","为什么徽州人喜欢雕刻历史故事？"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","三雕"],"answer":"徽州三雕的题材非常广泛，主要包括：第一，人物故事——如二十四孝、三国演义、西厢记、郭子仪上寿等历史典故和戏曲故事，用来教育后代；第二，山水花鸟——如梅兰竹菊、松鹤延年、荷花鸳鸯等，寄托了文人的雅趣；第三，吉祥图案——如龙、凤、狮子、麒麟、蝙蝠、如意等，寓意吉祥如意、富贵平安、福寿绵长；第四，民俗风情——如渔樵耕读、百子闹元宵等，反映了徽州人的生活场景。每一幅雕刻都有其文化内涵。"},{"id":"m1-qa-Q043","questions":["歙县有哪些国家级重点文物保护单位（古建筑）？","歙县的国保单位名单","歙县21处国保建筑分别是什么？","去歙县必看的国保有哪些？"],"keywords":["模块一","徽韵千年","分地区国保","歙县","许国","棠樾","渔梁","牌坊","民居","国保","廊桥"],"answer":"歙县共有21处国家级重点文物保护单位（古建筑），包括：许国石坊、棠樾石牌坊群、渔梁坝、许村古建筑群、竹山书院、郑氏宗祠、洪氏宗祠（敬本堂）、棠樾古民居、北岸吴氏宗祠、员公支祠、昌溪周氏宗祠、北岸廊桥、三阳洪氏宗祠、石潭吴氏宗祠、稠墅牌坊群、歙县太平桥、巴慰祖宅、歙县许氏宗祠、歙县鲍氏宗祠、大阜潘氏宗祠、昌西太湖祠。其中许国石坊、棠樾牌坊群、渔梁坝是最具代表性的。"},{"id":"m1-qa-Q044","questions":["黟县有哪些国家级重点文物保护单位（古建筑）？","黟县的国保单位名单","西递和宏村是国保吗？","黟县除了宏村西递还有哪些国保？"],"keywords":["模块一","徽韵千年","分地区国保","徽派","黟县","宏村","西递","祠堂","国保"],"answer":"黟县共有4处国家级重点文物保护单位（古建筑）：宏村古建筑群、西递村古建筑群、南屏村古建筑群、屏山舒氏宗祠。其中宏村和西递于2000年被列入世界文化遗产，是徽派建筑最杰出的代表。南屏村以祠堂群闻名，屏山舒氏宗祠则是明代宗祠的精品。"},{"id":"m1-qa-Q045","questions":["徽州区有哪些国家级重点文物保护单位（古建筑）？","徽州区的国保单位名单","呈坎和潜口是国保吗？","唐模檀干园是什么？"],"keywords":["模块一","徽韵千年","分地区国保","徽州","徽派","徽州区","呈坎","牌坊","民居","国保"],"answer":"徽州区共有7处国家级重点文物保护单位（古建筑）：潜口民宅、老屋阁及绿绕亭、罗东舒祠、呈坎村古建筑群、洪坑牌坊群及洪氏家庙、蜀源牌坊群、唐模檀干园。呈坎村古建筑群被誉为“江南第一村”，潜口民宅是徽派民居的集中展示地，罗东舒祠素有“江南第一祠”之称。"},{"id":"m1-qa-Q046","questions":["婺源县有哪些国家级重点文物保护单位（古建筑）？","婺源县的国保单位名单","清华彩虹桥是国保吗？","理坑村民居值得去吗？"],"keywords":["模块一","徽韵千年","分地区国保","婺源","祠堂","民居","国保","明清","廊桥"],"answer":"婺源县共有5处国家级重点文物保护单位（古建筑）：清华彩虹桥、婺源宗祠（含7处）、理坑村民居、凤山查氏宗祠、新源俞氏宗祠。清华彩虹桥是宋代廊桥的经典之作，理坑村民居以保存完好的明清官宅著称，婺源宗祠则包含了多个村落中的优秀祠堂。"},{"id":"m1-qa-Q047","questions":["绩溪县有哪些国家级重点文物保护单位（古建筑）？","绩溪县的国保单位名单","龙川胡氏宗祠是国保吗？","奕世尚书坊在哪里？"],"keywords":["模块一","徽韵千年","分地区国保","绩溪","龙川","国保"],"answer":"绩溪县共有3处国家级重点文物保护单位（古建筑）：龙川胡氏宗祠、奕世尚书坊和胡炳衡宅、上庄古建筑群。龙川胡氏宗祠被称为“木雕博物馆”，奕世尚书坊上的题字为文徵明手书，上庄古建筑群则是胡适故乡的珍贵遗存。"},{"id":"m1-qa-Q048","questions":["休宁县有哪些国家级重点文物保护单位（古建筑）？","休宁县的国保单位名单","溪头三槐堂是国保吗？","黄村进士第有什么故事？"],"keywords":["模块一","徽韵千年","分地区国保","徽州","休宁","国保"],"answer":"休宁县共有4处国家级重点文物保护单位（古建筑）：溪头三槐堂、黄村进士第、休宁登封桥、休宁同安堂。黄村进士第是明代徽州科举文化的见证，休宁登封桥是清代石拱桥的代表。"},{"id":"m1-qa-Q049","questions":["祁门县、屯溪区、黄山区的国家级古建筑分别有哪些？","祁门古戏台是国保吗？","程大位故居是国保吗？","黄山区的国保在哪里？"],"keywords":["模块一","徽韵千年","分地区国保","祁门","屯溪","黄山区","祠堂","民居","国保"],"answer":"祁门县有1处：祁门古戏台（明代戏曲建筑遗存，包含多个戏台群）。屯溪区有3处：程大位故居（珠算大师故居）、程氏三宅（明代民居精品）、屯溪镇海桥（明代石拱桥）。黄山区有2处：兴村程氏宗祠（清代祠堂）、黄山登山古道及古建筑（包括古道、古亭、古桥等）。"},{"id":"m1-qa-Q050","questions":["为什么黟县没有牌坊类古建筑？","黟县为什么一座牌坊都没有？","黟县历史上有牌坊吗？","是不是漏统计了？"],"keywords":["模块一","徽韵千年","数据统计逻辑","黟县","西递","牌坊","文保"],"answer":"根据本次统计数据，黟县的86处各级古建筑中确实没有牌坊类建筑。这主要有两个原因：第一，黟县历史上虽有不少牌坊，但多数在文革等历史时期被损毁，现存数量极少；第二，现存的少数牌坊（如西递附近的个别残坊）未被列入各级重点文物保护单位名录，因此未纳入本次统计范围。需要说明的是，这并不代表黟县历史上没有牌坊，只是现存文保名录中缺失。"},{"id":"m1-qa-Q051","questions":["为什么婺源县的桥梁数量是徽州最多的？","婺源为什么有这么多古桥？","婺源的地理环境对建筑有什么影响？","婺源的古桥有什么特色？"],"keywords":["模块一","徽韵千年","数据统计逻辑","徽州","婺源","桥梁","明清","廊桥"],"answer":"婺源县桥梁数量多达78处，居徽州之首，主要原因有三：第一，地理环境——婺源境内水系发达，河流纵横交错，需要大量桥梁连接交通；第二，经济因素——明清时期婺源徽商发达，捐资修桥是徽商回报家乡的重要方式，许多桥梁都有商人的捐建题记；第三，文化传统——婺源人认为“修桥铺路”是积德行善之举，因此形成了良好的传统。婺源的廊桥（如清华彩虹桥）尤为著名。"},{"id":"m1-qa-Q052","questions":["为什么祁门县的祠堂数量占比最高？","祁门为什么有这么多祠堂？","祁门的宗族文化很发达吗？","祁门古戏台和祠堂有什么关系？"],"keywords":["模块一","徽韵千年","数据统计逻辑","祁门","祠堂","明清"],"answer":"祁门县40处古建筑中有21处是祠堂，占比高达52.5%，主要原因是：第一，宗族制度——祁门地区宗族观念极强，祠堂是宗族凝聚力的象征，很多村落甚至有多座分房祠堂；第二，经济基础——明清时期祁门茶商崛起，积累了大量财富，有能力修建规模宏大的祠堂；第三，戏曲文化——祁门是目连戏的发源地，许多祠堂内附设戏台，用于宗族祭祀和戏曲演出，祁门古戏台就是其中代表。"},{"id":"m1-qa-Q053","questions":["为什么屯溪区的古建筑密度是徽州最高的？","屯溪区面积很小吗？","屯溪的古建筑为什么这么集中？","屯溪历史上是什么地位？"],"keywords":["模块一","徽韵千年","数据统计逻辑","徽州","屯溪","明清"],"answer":"屯溪区古建筑密度高达13.09个/百km²，居徽州第一，主要原因是：第一，面积最小——屯溪区总面积仅191km²，是徽州各县区中面积最小的；第二，历史地位——明清时期屯溪是徽州的水陆商贸中心，素有“屯溪老街”之称，经济发达，建筑密集；第三，保护较好——屯溪老街、程氏三宅、镇海桥等核心区域保存完好，古建筑相对集中。"},{"id":"m1-qa-Q054","questions":["宏村承志堂有多大？有多少间房？","承志堂为什么被称为民间故宫？","承志堂的建筑规模是多少？","承志堂是谁建的？"],"keywords":["模块一","徽韵千年","代表性建筑细节","徽州","宏村","承志堂","天井"],"answer":"承志堂是宏村最具代表性的建筑，建于清咸丰五年（1855年），由大盐商汪定贵建造。占地面积约2000平方米，建筑面积约3000平方米，共有9个天井、60余间房屋。承志堂以其精美的木雕、砖雕和石雕著称，尤其是前厅横梁上的“唐肃宗宴官图”木雕，长2.26米，雕刻了文武百官赴宴的场景，人物神态各异，是徽州木雕中的极品。因为规模宏大、雕刻奢华，它被誉为“民间故宫”。"},{"id":"m1-qa-Q055","questions":["西递胡文光刺史牌坊的尺寸是多少？","胡文光牌坊有多高？","胡文光牌坊用什么材料建造的？","胡文光是谁？"],"keywords":["模块一","徽韵千年","代表性建筑细节","徽派","黟县","西递","牌坊"],"answer":"胡文光刺史牌坊位于西递村，建于明万历六年（1578年），为三间四柱五楼式石牌坊，高12.3米，宽9.95米，通体采用黟县青大理石雕筑而成。牌坊上雕刻有32个圆形花盘、12只仙鹤、4只狮子，以及各种花卉图案。胡文光是明嘉靖三十四年进士，官至荆州王府长史，牌坊为表彰其为官23年的政绩而建，是明代徽派石坊的代表作。"},{"id":"m1-qa-Q056","questions":["渔梁坝的长度和宽度是多少？","渔梁坝有多大？","渔梁坝的坝体结构是怎样的？","渔梁坝用了什么特殊的建造技术？"],"keywords":["模块一","徽韵千年","代表性建筑细节","渔梁"],"answer":"渔梁坝全长138米，底宽27米，顶宽4米，高约5米，是一座重力滚水坝。坝体全部用花岗岩条石砌筑，采用“元宝钉”和“燕尾锁”将条石相互连接，形成一个坚固的整体。这种榫卯式的石构连接方式在中国水利工程史上非常独特，保证了坝体数百年的稳固。坝体分为三段，中间段较高，用于泄洪，两侧较低，用于通行和灌溉。"},{"id":"m1-qa-Q057","questions":["许国石坊的尺寸是多少？","许国石坊有多高？","许国石坊有几根柱子？","许国石坊为什么是八脚？"],"keywords":["模块一","徽韵千年","代表性建筑细节","许国","牌坊"],"answer":"许国石坊是全国罕见的八柱石牌坊，高11.4米，宽11.5米，进深6.77米。它由前后两座三间四柱三楼坊和左右两座单间双柱三楼坊组成，形成一个口字形结构，共有八根立柱，因此俗称“八脚牌坊”。石坊通体采用青色茶园石建造，雕刻有龙、凤、狮子、麒麟等图案，工艺精湛。这种形制在中国牌坊建筑中是孤例，极为珍贵。"},{"id":"m1-qa-Q058","questions":["徽派建筑体现了哪些徽州文化？","徽派建筑的文化内涵是什么？","建筑和徽州文化有什么关系？","从建筑上能看出徽州人的哪些思想？"],"keywords":["模块一","徽韵千年","文化内涵","徽州","徽派","宏村","西递","呈坎","牌坊","祠堂"],"answer":"徽派建筑是徽州文化的物化载体，主要体现了以下文化内涵：第一，宗族文化——以祠堂为核心的村落布局，体现了徽州人强烈的宗族观念和“聚族而居”的传统；第二，儒商文化——“贾而好儒”的徽商将儒家思想融入建筑，如西递大夫第的“作退一步想”门额，体现了谦和礼让的处世哲学；第三，风水文化——村落选址和布局遵循“天人合一”的风水理念，如宏村的牛形水系、呈坎的八卦布局；第四，礼制文化——牌坊、祠堂等建筑是封建礼制的象征，体现了等级制度和伦理规范。"},{"id":"m1-qa-Q059","questions":["为什么徽州人喜欢在建筑上雕刻？","徽州三雕的文化意义是什么？","雕刻只是为了好看吗？","雕刻有什么教育意义？"],"keywords":["模块一","徽韵千年","文化内涵","徽州","三雕"],"answer":"徽州人在建筑上大量使用雕刻，不仅是为了装饰，更重要的是为了传递文化和价值观。第一，教育后代——雕刻中的历史典故（如二十四孝、三国故事）和吉祥图案，能够潜移默化地教育子孙后代忠孝节义；第二，彰显身份——精美的雕刻是财富和地位的象征，徽商通过雕刻展示自己的实力和品味；第三，祈福纳祥——雕刻中的吉祥图案（如蝙蝠寓意“福”、鹿寓意“禄”），寄托了徽州人对美好生活的向往；第四，传承文化——雕刻是徽州文化的重要载体，通过建筑得以代代相传，成为“无声的教科书”。"},{"id":"m1-qa-Q060","questions":["徽州古建筑的保护现状如何？","徽州古建筑保存得好吗？","有哪些保护措施？","政府是怎么保护这些古建筑的？"],"keywords":["模块一","徽韵千年","保护现状","徽州","国保","传统村落"],"answer":"徽州古建筑的保护现状总体良好，各级政府和民间都采取了多种保护措施。第一，建立文物保护单位制度——大量古建筑被列入国保、省保、市保、县保名录，依法进行重点保护；第二，设立文化生态保护区——徽州文化生态保护实验区是全国第一个跨省国家级文化生态保护区；第三，开展传统村落保护——实施传统村落集中连片保护利用示范工程，投入专项资金；第四，数字化保护——利用三维扫描、无人机航拍等数字技术对古建筑进行数字化存档；第五，活化利用——将部分古建筑改造为博物馆、民宿、文创空间，实现“以用促保”。不过，部分偏远地区的古建筑仍面临年久失修、自然损毁、空心化等问题，保护工作任重道远。"},{"id":"m1-qa-Q061","questions":["我想了解徽州古建筑的基本情况","给我介绍一下徽州古建筑","徽州古建筑概览","徽州古建筑整体情况是什么样的？"],"keywords":["模块一","徽韵千年","陈述句触发","徽州","徽派","歙县","婺源","黟县","屯溪","767","宏村","西递","许国","棠樾","渔梁","龙川"],"answer":"徽州一府六县核心区域共有767处各级重点文物保护单位（古建筑），以明清建筑为主（占比96.09%）。主要类型包括民居（253处，占33%）、祠堂（186处，占24%）、桥梁（132处，占17%）、牌坊（86处，占11%）等。婺源县和歙县的古建筑数量最多，屯溪区和黟县的密度最高。代表性建筑有宏村、西递、许国石坊、棠樾牌坊群、渔梁坝、龙川胡氏宗祠等。徽派建筑以粉墙黛瓦、马头墙、三雕工艺为核心特征，是徽州文化的重要载体。"},{"id":"m1-qa-Q062","questions":["给我介绍一下徽州最有名的几个古建筑","徽州必看的古建筑有哪些？","推荐几个徽州著名的古建筑","最值得去的徽州古建筑是哪些？"],"keywords":["模块一","徽韵千年","陈述句触发","徽州","徽派","歙县","宏村","西递","许国","棠樾","渔梁","龙川","牌坊","承志堂"],"answer":"徽州最具代表性的古建筑包括：第一，宏村——徽派水系村落的典范，牛形水系和承志堂闻名于世，是世界文化遗产；第二，西递——船形布局的古村落，胡文光刺史牌坊是明代石坊精品，也是世界文化遗产；第三，许国石坊——全国罕见的八脚牌坊，明代石构建筑孤例，位于歙县古城；第四，棠樾牌坊群——7座牌坊集齐“忠孝节义”四大主题，是徽州牌坊的集中展示；第五，渔梁坝——被誉为“徽州都江堰”，古代徽州水运的核心枢纽；第六，龙川胡氏宗祠——被称为“木雕博物馆”，明代宗祠建筑的代表。"},{"id":"m1-qa-Q063","questions":["徽州哪个地方最值得去看古建筑","徽州古建筑旅游推荐","哪里的徽州古建筑最集中","如果只有一天，去哪里看徽派建筑最好？"],"keywords":["模块一","徽韵千年","陈述句触发","徽州","徽派","歙县","婺源","黟县","徽州区","宏村","西递","许国","棠樾","渔梁","呈坎","牌坊"],"answer":"如果想集中看徽州古建筑，推荐以下几个地方：第一，歙县——拥有最多的高等级古建筑和牌坊，徽州古城、许国石坊、棠樾牌坊群、渔梁坝都在这里，一天到两天可以看精华；第二，黟县——宏村和西递是世界文化遗产，明清民居保存最完好，适合深度体验；第三，婺源县——古桥梁最多，清华彩虹桥、理坑村民居、江湾古村值得一看，春季搭配油菜花更美；第四，徽州区——呈坎八卦村、潜口民宅、唐模等古村落各具特色，且相对集中。如果时间有限，首选歙县古城+宏村/西递。"},{"id":"m1-qa-Q064","questions":["这些数据是怎么来的","数据来源可靠吗？","统计依据是什么？","你们的数据有官方背书吗？"],"keywords":["模块一","徽韵千年","陈述句触发","婺源","绩溪","民居"],"answer":"本数据全部来自政府及博物馆官方网站，统计截止到2026年2月。具体包括：黄山市各级文物名录（黄山市人民政府官网）、安徽省第九批省级文物保护单位（安徽省人民政府官网，2026年2月9日发布）、江西省第七批省级文物保护单位（江西省人民政府官网，2025年7月18日发布）、绩溪县文物名录（绩溪县博物馆官网）、婺源县文物名录（婺源县人民政府官网、江西省文化和旅游厅官网）。国家级文物名录更新至2019年第八批，第九批预计2026年中旬发布。数据已剔除1911年后建筑及非民居类建筑，可能存在3%-5%的统计误差，但整体不影响分析结论。"},{"id":"m1-qa-Q065","questions":["徽州所有的古建筑都统计在内了吗？","这个数据是全部古建筑的数量吗？","还有没统计到的古建筑吗？","是不是漏了很多？"],"keywords":["模块一","徽韵千年","反向确认","徽州","767","祠堂","民居","文保"],"answer":"不是的。本数据仅统计了各级重点文物保护单位中的古建筑，未列入文保名录的历史建筑（如许多村落中未被定级的普通民居、小祠堂等）数量远远多于这个数字，但这部分数据难以全面准确统计，因为全国性的文物普查尚未完全覆盖所有未定级建筑。此外，1911年以后的建筑、遗址、墓碑、庙宇、宝塔等也不在统计范围内。所以，767处是“文保单位”中的古建筑数量，不是徽州古建筑的总量。"},{"id":"m1-qa-Q066","questions":["徽州的古建筑都是明清时期的吗？","有唐代或宋代的古建筑吗？","最早的徽州古建筑是什么时候的？","有没有元朝以前的建筑？"],"keywords":["模块一","徽韵千年","反向确认","徽州","歙县","婺源","绩溪","渔梁","明清"],"answer":"不是的。虽然明清建筑占比高达96.09%，但仍有少量更早的珍贵遗存。唐代及以前的有10处，如歙县的渔梁坝（始建于唐）、徽州古城墙（始建于隋）；宋元时期有18处，如婺源县的清华彩虹桥（始建于宋）、绩溪县的中正坊（宋代楼阁）、歙县的紫阳书院（南宋）。歙县拥有最多的早期遗存，历史纵深最长。这些早期建筑是研究徽州建筑演变的重要实物资料。"},{"id":"m1-qa-Q067","questions":["徽派建筑的结构特点是什么？","徽派建筑用什么结构？","穿斗式和抬梁式有什么区别？","为什么徽派建筑能保存这么久？"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","徽派","祠堂","民居","天井"],"answer":"徽派建筑多采用穿斗式与抬梁式相结合的木结构体系。穿斗式：柱子直接承檩，不用梁，结构轻盈、抗震性能好，适合山区和普通民居；抬梁式：梁上立柱，柱上承檩，空间开阔，适合祠堂、大厅等大型建筑。徽派建筑巧妙地混合使用这两种结构，既保证了建筑的稳定性，又满足了不同空间的需求。此外，徽派建筑注重通风防潮，采用高地基、空斗墙、天井等设计，适应徽州多雨潮湿的气候，这也是很多木结构古建筑能保存数百年的重要原因。"},{"id":"m1-qa-Q068","questions":["徽州传统村落的选址有什么特点？","徽州古村为什么都依山傍水？","村落选址遵循什么原则？","风水对村落选址影响大吗？"],"keywords":["模块一","徽韵千年","历史村落","徽州","宏村","呈坎","传统村落"],"answer":"徽州传统村落的选址严格遵循“天人合一”的风水理念，主要特点包括：第一，依山傍水——多建在背山面水的山间盆地或河谷地带，既能阻挡北方寒流，又能保证水源和舟楫之利；第二，负阴抱阳——坐北朝南，保证充足的光照和良好的通风；第三，藏风聚气——选择三面环山、一面开口的“太师椅”地形，形成温暖湿润的小气候；第四，因地制宜——根据地形地貌灵活布局，如宏村的牛形水系利用地势引水入村，呈坎则按八卦分街设巷。这些选址原则不仅具有美学价值，也体现了古人的生态智慧。"},{"id":"m1-qa-Q069","questions":["什么是“贾而好儒”？在建筑上有什么体现？","徽商的特点是什么？","建筑如何体现儒商文化？","徽商为什么喜欢修书院？"],"keywords":["模块一","徽韵千年","文化内涵","歙县","宏村","西递","祠堂","民居","承志堂"],"answer":"“贾而好儒”是徽商的核心特点，指徽商既经商致富，又崇尚儒学、重视教育。在建筑上的体现主要有：第一，修建书院——如歙县的竹山书院，是徽商捐资兴建的教育场所，培养了大量科举人才；第二，匾额楹联——建筑上的匾额楹联多为儒家格言，如西递大夫第的“作退一步想”门额、宏村承志堂的“基开睢涣”匾，体现了儒家的处世哲学和家族理想；第三，建筑布局——遵循儒家礼制，以祠堂为核心，民居围绕，体现长幼有序、尊卑有别的伦理观念；第四，装饰题材——雕刻中大量使用儒家经典故事，如二十四孝、渔樵耕读、科举及第等，宣扬忠孝节义。"},{"id":"m1-qa-Q070","questions":["屯溪镇海桥的历史故事是什么？","镇海桥是谁建的？","父子修桥的故事是真的吗？","镇海桥为什么叫老大桥？"],"keywords":["模块一","徽韵千年","代表性建筑","屯溪"],"answer":"屯溪镇海桥又名老大桥，始建于明嘉靖十五年（1536年），由邑人戴时亮创建。清康熙十五年（1676年），桥毁于洪水，徽商程子谦独资重建，历时两年竣工。康熙三十五年（1696年），桥再次毁于大水，已经年迈的程子谦再次捐资重建，工程未竟而卒。其子程岳继承父志，于康熙三十八年（1699年）建成，定名“镇海桥”，取“镇住洪魔、威镇海阳”之意。“父子修桥”的故事传为佳话，体现了徽商义利兼顾、造福桑梓的精神。2020年，镇海桥被特大洪水冲毁，后按原貌修复，保留了原桥石料与传统工艺。"},{"id":"m1-qa-Q071","questions":["程大位故居有什么历史意义？","程大位是谁？","《直指算法统宗》是什么书？","程大位故居为什么是国保？"],"keywords":["模块一","徽韵千年","代表性建筑","徽派","屯溪","民居","国保","天井"],"answer":"程大位故居位于屯溪区，是明代珠算大师程大位的出生地和居所。程大位（1533-1606）毕生致力于数学研究，在此完成了珠算经典《直指算法统宗》（1592年）。这部书系统总结了珠算的算法体系，统一了算盘口诀，流传至日本、朝鲜及东南亚，影响深远，被誉为“珠算圣经”。故居始建于明弘治年间，名“维新堂”，是一座典型的明代徽派民居，三开间、双天井、砖雕门楼。1986年修缮后设陈列室，展陈程大位生平与珠算文物，是研究中国古代数学史和珠算文化的重要场所。"},{"id":"m1-qa-Q072","questions":["徽州廊桥有什么特点？","廊桥和普通桥有什么区别？","清华彩虹桥为什么是廊桥？","徽州廊桥有哪些功能？"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","婺源","祁门","桥梁","水口","廊桥"],"answer":"徽州廊桥是一种带屋顶的桥梁，主要特点有：第一，功能多样——不仅能通行，还能遮阳避雨、供人休憩乘凉，有的廊桥内还设有神龛、商铺甚至戏台，是村民社交和文化活动的场所；第二，结构独特——采用木石结构，桥墩用石头砌筑，桥身和廊屋用木材建造，不用一钉一铆，全靠榫卯连接，体现了高超的木构技艺；第三，文化内涵——廊桥在徽州风水文化中占有重要地位，被认为能“锁住”村落的水口，聚财纳福。代表有婺源县的清华彩虹桥（宋代，江南现存最早廊桥之一）、祁门县的会源廊桥等。"},{"id":"m1-qa-Q073","questions":["徽州三雕中，木雕、石雕、砖雕分别有哪些代表作？","三雕最有名的作品在哪里？","能不能推荐几处看木雕、石雕、砖雕最好的地方？","我想知道徽州三雕的典型代表建筑"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","歙县","黟县","绩溪","宏村","西递","许国","棠樾","龙川","牌坊","承志堂","三雕"],"answer":"徽州三雕的代表作：木雕首推绩溪龙川胡氏宗祠，正厅荷花图隔扇传为徐渭稿本，被誉为“木雕博物馆”；宏村承志堂前厅横梁的《唐肃宗宴官图》长2.26米，人物神态各异，也是木雕极品。石雕代表作是歙县许国石坊和西递胡文光刺史牌坊，前者八柱口字形为全国孤例，后者高12.3米、通体黟县青雕筑。砖雕则集中在各建筑的门楼上，宏村承志堂、歙县棠樾牌坊群旁的鲍氏宗祠门楼都是精品，题材以人物故事、吉祥纹样为主。"},{"id":"m1-qa-Q074","questions":["什么是“水口”？徽州村落的水口有什么功能？","水口是什么意思？","徽州古村为什么重视水口？","水口园林有什么作用？"],"keywords":["模块一","徽韵千年","历史村落","徽州","歙县","婺源","宏村","水口"],"answer":"水口是徽州村落水系的入口或出口区域，通常位于村口。它的功能有：第一，风水功能——水口被视为村落的“气口”，通过植树、建桥、筑亭、立塔来“锁住”财气和文运，形成“藏风聚气”的格局；第二，实用功能——水口往往建有堤坝、水闸，可以调节水量、防洪灌溉；第三，社交功能——水口区域多建有亭阁、戏台，是村民聚会、休憩、迎送亲友的公共空间。代表有宏村南湖口、歙县昌溪水口、婺源理坑水口等，水口园林更是徽州村落的一大特色。"},{"id":"m1-qa-Q075","questions":["徽州古建筑中的楹联匾额有什么文化内涵？","老房子上的对联匾额写了什么？","徽商喜欢在门上挂什么字？","为什么徽州民居的楹联都很有哲理？"],"keywords":["模块一","徽韵千年","文化内涵","徽州","徽派","宏村","西递","民居"],"answer":"楹联匾额是徽派建筑的“点睛之笔”，主要体现三个方面：一是处世哲学，如西递大夫第的“作退一步想”门额，体现了谦和礼让、不与人争的中庸之道；二是儒家伦理，如宏村乐叙堂的“德同天地”、“道冠古今”，彰显宗族对道德的推崇；三是家族理想，如“读书好、营商好、效好便好”、“几百年人家无非积善”等楹联，传达了徽商“贾而好儒”、重教兴族的价值观。这些文字既是装饰，更是家族代代相传的“家训”。"},{"id":"m1-qa-Q076","questions":["徽州古井有哪些类型？为什么古井也是文物保护单位？","徽州古井为什么那么多？","古井也算文物吗？","徽州最有名的古井是哪些？"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","歙县","婺源"],"answer":"徽州古井按形制可分为单眼井、双眼井、三眼井、四眼井甚至八瓣梅花井。按功能分为生活饮用井、消防蓄水井、风水景观井等。古井之所以被列为文物保护单位，是因为：第一，历史价值——许多古井开凿于唐宋，如歙县“打箍井”为唐井，婺源“八瓣梅花井”为清井，是村落历史的活化石；第二，文化价值——古井常与传说、族规相关，如“洗眼井”有治病传说，“义井”见证宗族互助；第三，科学价值——古代凿井、砌井、水质净化技术反映了当时的工艺水平。附件1县级名录中收录了歙县、婺源县数十处古井，它们是徽州人居文化的重要组成部分。"},{"id":"m1-qa-Q077","questions":["徽商是如何影响徽派建筑的发展的？","徽商和徽派建筑有什么关系？","为什么徽商有钱了先建房？","徽商对建筑风格有什么影响？"],"keywords":["模块一","徽韵千年","文化内涵","徽派","宏村","西递","牌坊","祠堂","桥梁","明清","承志堂"],"answer":"徽商对徽派建筑的影响是全方位的。第一，经济支撑——明清徽商“富可敌国”，大量资金回流家乡，修建了宏村承志堂、西递走马楼等奢华宅第，以及祠堂、牌坊、书院、桥梁等公共建筑。第二，审美导向——徽商“贾而好儒”，追求内敛雅致而非张扬豪华，形成了“粉墙黛瓦”的素雅外观和“外简内华”的装饰风格。第三，文化注入——徽商将儒家的“忠孝节义”、道家“天人合一”以及科举功名追求融入建筑布局和雕刻题材中。可以说，没有徽商就没有徽派建筑的鼎盛。"},{"id":"m1-qa-Q078","questions":["徽派建筑中的“冬瓜梁”是什么？有什么特点？","冬瓜梁是什么形状？","为什么叫冬瓜梁？","冬瓜梁主要用在哪里？"],"keywords":["模块一","徽韵千年","建筑工艺","徽派","宏村","龙川","承志堂"],"answer":"冬瓜梁是徽派建筑中一种特殊的梁构件，因其形似冬瓜（中部粗壮、两端收分，呈饱满弧形）而得名。它通常用于厅堂的月梁位置，主要特点是：第一，结构受力——中部向上拱起，利用拱形原理分散压力，承重能力强；第二，装饰精美——梁身往往雕刻花卉、卷草、祥云等图案，两端雕成“象鼻”或“如意”形状，兼具结构与装饰双重功能；第三，用料讲究——多选用银杏、楠木等整根大木料制作，体现建造者的财力。冬瓜梁在宏村承志堂、龙川胡氏宗祠、罗东舒祠中都能见到，是徽派大木作的代表。"},{"id":"m1-qa-Q079","questions":["徽州古建筑的修复遵循什么原则？有哪些成功案例？","古建筑坏了怎么修？","修复古建筑能用现代材料吗？","徽州有没有修旧如旧的例子？"],"keywords":["模块一","徽韵千年","保护现状","徽州","屯溪","宏村","呈坎","承志堂"],"answer":"徽州古建筑修复严格遵循“不改变原状”和“最小干预”原则，具体包括：原工艺、原材料、原形制、原结构。修复时会优先使用传统材料（小青瓦、杉木、石灰、桐油等）和传统技艺（榫卯、空斗砌法、砖雕修补等）。成功案例包括：屯溪镇海桥2020年被洪水冲毁后，采用原桥石料、原工艺进行重建，保留了明代桥墩和清代桥面特征；宏村承志堂的木雕修缮，邀请国家级非遗传承人用传统工具手工修复破损部位；呈坎罗东舒祠屋面维修时，按照明代《营造法式》复原脊饰。同时，数字化三维扫描技术也被广泛用于修复前的记录和方案设计。"},{"id":"m1-qa-Q080","questions":["徽州民居中的“美人靠”是什么？有什么作用？","美人靠是干什么用的？","为什么叫美人靠？","哪些建筑有美人靠？"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","徽派","宏村","西递","民居","天井"],"answer":"美人靠是徽州民居二楼临天井或临街处的一种木制栏杆式座椅，因其靠背向外倾斜、形如鹅颈，也称“鹅颈椅”。它的主要作用：第一，休憩观景——主妇或小姐可以凭栏而坐，纳凉、做针线、观看天井下的活动，同时保证私密性；第二，通风采光——美人靠采用镂空雕花设计，不阻碍空气流通和光线；第三，装饰美化——靠背上往往雕刻花卉、几何纹样，是徽派木雕的展示窗口。西递、宏村许多民居的“小姐绣楼”都配有美人靠，大夫第的临街阁楼就有典型的美人靠，成为游客打卡的标志。"},{"id":"m1-qa-Q081","questions":["徽州祠堂中的“寝堂”为什么一般不对外开放？","祠堂最后一进为什么不让进？","寝堂里放的是什么？","为什么很多祠堂的第三进锁着门？"],"keywords":["模块一","徽韵千年","文化内涵","徽州","龙川","祠堂"],"answer":"寝堂是祠堂的第三进，也是最后一进，是供奉家族历代祖先牌位（神主牌）的场所。它一般不对外开放的原因有：第一，神圣性——寝堂相当于家族的“宗庙”，是祭祀的核心区域，非本族成员或非祭祀期间不得入内，以保持庄严肃穆；第二，保护需要——牌位多为木制，长期受香火和空气影响容易损毁，限制开放可延长保存寿命；第三，传统禁忌——按照传统礼制，女性、外姓人未经允许不得进入寝堂，现代虽已淡化，但管理上仍保留限制。龙川胡氏宗祠、罗东舒祠的寝堂均不对外开放，游客只能从享堂透过格扇门观看内部陈设。"},{"id":"m1-qa-Q082","questions":["徽州古建筑中为什么大量使用“黟县青”石材？","黟县青是什么石头？","为什么牌坊都用青石？","黟县青有什么优点？"],"keywords":["模块一","徽韵千年","建筑工艺","徽州","徽派","歙县","婺源","黟县","许国","牌坊"],"answer":"黟县青是产自黟县的一种青色大理石，徽州古建筑的牌坊、柱础、门槛、石雕作品大量使用它，原因有四：第一，质地优良——石质细腻、硬度适中，既耐风化又易于雕刻，许国石坊、胡文光牌坊历经四五百年雕刻细节仍清晰可辨；第二，色泽美观——青灰色调与粉墙黛瓦和谐统一，符合徽派建筑素雅的审美；第三，取材方便——黟县及周边地区储量丰富，开采运输成本低；第四，文化寓意——青色在传统文化中象征清廉、坚贞，与牌坊旌表功德、节孝的主题契合。除黟县青外，歙县茶园石、婺源砚石也被用于建筑中，但黟县青最为典型。"},{"id":"m1-qa-Q083","questions":["除了宏村西递，还有哪些小众但值得一看的徽州古村落？","推荐几个游客少的徽州古村","哪些古村落没有被商业化？","徽州有哪些冷门但很美的地方？"],"keywords":["模块一","徽韵千年","分地区详情","徽州","歙县","婺源","黟县","绩溪","休宁","徽州区","宏村","西递","呈坎","祠堂","国保","廊桥"],"answer":"推荐六个小众但各有特色的古村落：第一，歙县许村——有15处国保省保建筑，包括五马坊、大观亭、高阳廊桥，游客极少，元代“双寿承恩坊”独具一格。第二，徽州区灵山村——呈坎旁的隐秘古村，明代梯田式布局，有“灵阳古道”和明代“天尊阁”。第三，黟县屏山村——舒氏宗祠和御前侍卫祠堂保存完好，比宏村安静得多。第四，绩溪县磡头村——千米水街、十座古桥串联，春季有梯田油菜花。第五，婺源县理坑——官宅林立，“尚书第”“天官上卿”府邸可看明代原汁原味木雕。第六，休宁县黄村——进士第建筑宏大，村中百年小学由中挪合作修复，有国际知名度。"},{"id":"m1-qa-Q084","questions":["徽派建筑对周边地区的建筑风格有什么影响？","除了徽州，哪里还能看到徽派建筑？","徽派建筑影响了哪些地方？","为什么江苏浙江也有类似马头墙的房子？"],"keywords":["模块一","徽韵千年","建筑总体介绍","徽州","徽派","呈坎","民居","明清","马头墙","天井"],"answer":"徽派建筑随着徽商的足迹传播到了长江中下游广大地区。第一，江苏扬州、苏州——徽商在扬州经营盐业，建造了带有马头墙和砖雕门楼的“徽州会馆”、“个园”等园林，当地民居也吸收了徽派天井式布局。第二，浙江杭州、金华——徽商主要聚居地，至今保留“徽州码头”、“小瀛洲”等徽派风格建筑，金华兰溪的“诸葛八卦村”布局明显受呈坎影响。第三，江西景德镇、九江——徽派建筑与赣派建筑融合，出现了“半徽半赣”的混合风格，如浮梁“瑶里古镇”。第四，湖北武汉、上海——汉口曾有“新安街”，上海老城厢也有徽派民居遗存。可以说，徽派建筑是明清时期中国影响力最大的地域建筑流派之一。"},{"id":"m2-wd-M2Q001","questions":["在这个系统中，哪一种屋顶类型的统计占比最高？","统计图表里占比最大的那个屋顶构件是哪种？","玫瑰图中面积最大的扇形代表什么屋顶？","数据统计结果显示，最常使用的屋顶类型是什么？","在所有录入的屋顶数据里，数量最多的是哪种类型？"],"keywords":["模块二","屋顶","屋顶构件","图表","玫瑰图","硬山顶"],"answer":"硬山顶（含马头墙）的占比最高。在【模块二的屋顶部分】左上角的“屋顶·类型占比玫瑰图”中，右侧深灰色的扇区代表“硬山顶（含马头墙）”，占比高达28.6%，样本数量为65个。这种形式在徽派和南方传统聚落中非常常见，马头墙的设计尤其适合防火需求高的密集建筑群。"},{"id":"m2-wd-M2Q002","questions":["悬山顶在整个系统中的排行情况如何？","悬山顶在全部屋顶类型中排第几位？","系统里，硬山顶之后使用频率最高的屋顶是哪种？","占比排列中，仅次于硬山顶的屋顶类型是什么？","图表显示，占有率约为21.8%的屋顶类型是哪一个？"],"keywords":["模块二","屋顶","屋顶构件","图表","玫瑰图","硬山顶","悬山顶"],"answer":"悬山顶排名第二，是第二常见的屋顶类型。在【模块二的屋顶部分】左上角的玫瑰图中，紧挨着硬山顶左侧的浅灰色扇区就是“悬山顶”，占比约21.8%，样本数量为52个。相比硬山顶，悬山顶的特点是屋顶两侧伸出山墙之外，这种设计在南方多雨地区的防雨防潮性能更好。"},{"id":"m2-wd-M2Q003","questions":["系统统计中，哪种屋顶类型的使用最少？","玫瑰图里占比最小且未被单独标注大类的屋顶是什么？","统计显示，使用频率最低的传统屋顶构件是哪一种？","在所有列表中，样本数量低于10个的是哪种屋顶？","扇形图中最窄的那个代表哪种屋顶形式？"],"keywords":["模块二","屋顶","屋顶构件","玫瑰图"],"answer":"单坡顶和其他类型的屋顶数量最少。在【模块二的屋顶部分】左上角的玫瑰图左侧，有两个极窄的扇区：“单坡顶”占比仅2.9%（7个），“其他”占比仅2.1%（5个），总和不足5%。单坡顶通常用于辅助用房、棚屋或靠墙的简易空间，等级较低且不作为主要起居建筑。"},{"id":"m2-wd-M2Q004","questions":["“多雨潮湿”的气候条件主要促使了哪种屋顶的广泛使用？","逻辑图中，由“多雨潮湿”直接引出的屋顶类型是哪种？","为了应对降水多的自然环境，传统民居倾向于选择什么屋顶形式？","在成因链路中，“排水需求”对应的主流屋顶形式是哪个？","自然环境因素里，“夏季炎热/多雨”最终导向哪一种屋顶结构？"],"keywords":["模块二","屋顶","屋顶构件","关系图","硬山顶"],"answer":"主要促使了硬山顶（含马头墙）的广泛使用。在【模块二的屋顶部分】右上角的“屋顶·形成逻辑关系图”中，从“自然环境”节点下的“多雨潮湿”向右追踪连线，可以清晰看到它最终连接到了“硬山顶（含马头墙）”。这一逻辑线解释了为什么在多雨地区，硬山顶及马头墙会成为民居的主流选择——它的山墙可以起到防火墙作用，同时排水便捷。"},{"id":"m2-wd-M2Q005","questions":["“通风隔热”需求通常要求设计成哪种屋顶形式？","根据关系图，“通风隔热”这一生活需求最常关联到哪种屋顶？","为了获得更好的夏季隔热效果，通常会选择建造什么屋顶？","逻辑链路中，与“采光需求”和“通风隔热”配套的屋顶样式是什么？","如果想要在屋顶下方留出透气空间，通常会优先考虑哪种类型？"],"keywords":["模块二","屋顶","屋顶构件","关系图","歇山顶"],"answer":"设计上通常倾向于采用歇山顶。在【模块二的屋顶部分】右上角的逻辑图中，找到“生活需求”节点下的“通风隔热”，顺着箭头向右，会发现它直接导向“歇山顶”。同时，附近的“采光需求”箭头也指向歇山顶。歇山顶拥有上半部斜坡和下半部半坡，形成“山花”空间，非常利于夏季热空气的上升和排出，达到通风隔热的效果。"},{"id":"m2-wd-M2Q006","questions":["“等级制度”这种地域文化因素会限制或引导屋顶向哪种形式发展？","在文化层级中，体现最高规制的屋顶形式是什么？","受“等级制度”影响，皇家或高等级建筑主要使用哪种屋顶？","在逻辑图中，由“礼制/风水观念”衍生出的高级别屋顶是哪一种？","传统社会中，代表最高地位的屋顶形式是？"],"keywords":["模块二","屋顶","屋顶构件","歇山顶"],"answer":"从系统数据来看，主要关联的是歇山顶。在【模块二的屋顶部分】右上角的逻辑图中，找到“地域文化”节点下的“等级制度”，顺着箭头向右看，可以发现它与“歇山顶”以及“组合式屋顶”相关联。虽然古代屋顶等级次序最高为庑殿顶，但在本系统的样本数据及逻辑图中，歇山顶是被明确标注为受“等级制度”直接影响的重要形制。"},{"id":"m2-wd-M2Q007","questions":["词云中提到的，最常见的用于覆盖屋面并防水的传统材料是什么？","在屋顶的关键词云里，哪种材料词频最高？","传统屋顶体系中，主要负责覆盖瓦面的是哪种构件？","系统语义分析中，哪类瓦片材料成为了核心高频词？","词云中用较大字体显示的“青色”覆盖物是什么？"],"keywords":["模块二","屋顶","屋顶构件"],"answer":"是小青瓦。在【模块二的屋顶部分】左下角的“屋顶·关键词词云图”中，“小青瓦”三个字位于词云正中央偏上位置，字号非常大，表明它在系统内容中出现的频率和重要性极高。小青瓦搭配砖瓦、瓦当等构件，构成了传统屋面最经典、最具代表性的“深出檐、青瓦顶”防水体系。"},{"id":"m2-wd-M2Q008","questions":["除了石材和砖块，词云中提到了什么用于屋顶装饰/结构的雕刻种类？","屋顶关联词里，提到的关于雕刻的艺术种类有哪些？","在装饰层面，系统主要记录了哪几种材质的具体雕刻形式？","词云中的“砖雕、木雕、石雕”属于什么类别的工艺？","传统的屋顶艺术修饰手法，对应系统记录的三个关键词是什么？"],"keywords":["模块二","屋顶","屋顶构件"],"answer":"系统明确列出了砖雕、木雕、石雕三种雕刻工艺。在【模块二的屋顶部分】左下角的词云图中，扫视中下部区域，可以看到“砖雕、木雕、石雕”三个词集中排列在一起，字体中等，直观展示了屋顶作为艺术载体的特性。传统屋顶不只讲究结构功能，大量精美的装饰细节都体现在这三种雕刻上，如屋脊花饰、檐口斗拱、山花图案等。"},{"id":"m2-wd-M2Q009","questions":["系统中，“飞椽”这个词在构造体系中代表了什么角色？","屋顶界面模块中，词云里提到的专门用于挑檐并带有装饰性的前端木材是什么？","屋顶伸出檐口的最外侧、起承托瓦片作用的那个构件叫什么？","通常和“瓦当、滴水”配合使用，架在屋檐最边缘的木质零件是？","用来形成屋顶优美曲线的那些向外翘起的木椽术语名称是？"],"keywords":["模块二","屋顶","屋顶构件"],"answer":"飞椽是指屋檐最外侧伸出、承托瓦片的关键木质构件。在【模块二的屋顶部分】左下角的词云图中，可以在偏左侧找到“飞椽”词条，虽然字号较小，但它代表了一个非常重要的构造细节。飞椽直接决定了屋檐的“出挑”长度和优美弧度（如飞檐翘角），让屋盖既有飘逸的视觉效果，又能有效保护墙基免受雨水冲刷。"},{"id":"m2-wd-M2Q010","questions":["右下角的图表中，测算屋顶坡度和高度的核心参数“H/L”表示的是什么？","在举折示意图中，横坐标与纵坐标之间的计算比率代表什么？","传统屋顶设计里“总举高比H/L”这个参数具体指代哪种比例？","折线图中的主要斜率指标“0.5”等数值，反映的是屋顶的什么特征？","系统提供的参数计算中，屋架垂直高度与水平步架之和的比值叫什么？"],"keywords":["模块二","屋顶","屋顶构件","图表","雷达图","举架","举折"],"answer":"H/L表示的是总举高比。在【模块二的屋顶部分】右下角的“屋顶·举架关键参数雷达图”和“举折做法示意图”中，查看左下角的文字标签，明确标注着“总举高比 H/L”。这个参数决定了屋顶的陡峭程度：H是屋顶垂直高度，L是水平跨度，比值越大屋顶越陡，比值越小屋顶越平缓，直接影响屋面的排水效率和建筑的外观气势。"},{"id":"m2-wd-M2Q011","questions":["在《工程做法则例》的基础上，该系统图示中的“五架屋”、“七架屋”是按照什么来划分的？","屋顶界面模块中，图示中区分“五架、七架、九架”的核心依据是什么？","传统建筑的桁架数量（也就是俗称的“架”数）是根据什么构件来计算的？","屋顶界面模块的系统技术图里，表示进深等级的“架”指的是什么梁结构的数量？","决定屋顶核心骨架结构的，是图中哪类构件的水平和数量？"],"keywords":["模块二","屋顶","屋顶构件","雷达图","举架"],"answer":"是按照檩条的数量来划分的。在【模块二的屋顶部分】右下角的“屋顶·举架关键参数雷达图”区域右上角，可以看到“五架屋”、“七架屋”、“九架屋”三个标签卡。在古建术语中，“一架”即对应一根横向承重的檩条，五架屋意味着有5根檩条支撑屋顶。檩条数量直接决定了屋顶的进深（房屋宽度），五架屋常用于普通民居，七架屋规格更高，九架屋则常见于大型殿宇。"},{"id":"m2-wd-M2Q012","questions":["图中所示的传统工程规范/古籍名称是什么？","画面右下角提到的用来参考做法的历史文献是哪一本？","古建屋顶研究中，经常引用到的清代官方建筑规范叫什么？","系统引用的参考材料中，包含了哪个著名的建造法则著作？","屋顶部分的“举折法”和“举架法”来源于近代哪本著作？"],"keywords":["模块二","屋顶","屋顶构件","图表","举架","举折"],"answer":"该古籍名称为《工程做法则例》。在【模块二的屋顶部分】右下角的图表中，将视线移至底部中间偏左位置，可以看到一行小字写着“《工程做法则例》对...”，明确引用了这部清代官方颁布的建筑规范。这部书是清代官式建筑的设计和施工标准，相当于当年的“国家建筑规范”，图中的举架数据（如总举高比）正是基于这部古籍的算法来推算的。"},{"id":"m2-wd-M2Q013","questions":["词云里有哪些关键词直接描述了屋顶的物理功能？","系统归纳的核心关键词中，哪些属于屋顶的基础工程作用？","屋顶必须解决的三大物理功能，在词云里对应哪些词语？","除了美学，系统把屋顶的哪些实用价值（如防漏、隔热）提取为了关键词？","从词云里看，屋顶最主要的功能词是？"],"keywords":["模块二","屋顶","屋顶构件","举架"],"answer":"分别是防水、隔热、排水。在【模块二的屋顶部分】左下角的“屋顶·关键词词云图”中，可以清晰地看到这三个词语，它们大小适中，分散在词云的中上部区域，与其他描述形态或装饰的词汇形成了明显区分。这三个功能是传统屋顶设计的三大核心命题：防水靠瓦片和构造缝，隔热靠材料和举架形成的空气层，排水完全依赖屋顶的坡度和檐口设计。"},{"id":"m2-wd-M2Q014","questions":["图中“马头墙”这个词通常与哪种屋顶形式及地域文化绑定在一起？","逻辑图中“硬山顶（含马头墙）”所代表的典型地域建筑风格是什么？","在屋顶分类逻辑中，马头墙附属于哪种山墙和屋面平齐的屋顶？","徽派建筑的典型封火墙（呈现阶梯状），通常安放在什么屋顶上？","“硬山顶”这一类别中，包含了哪种独特的地域性墙体结构？"],"keywords":["模块二","屋顶","屋顶构件","关系图","玫瑰图","硬山顶"],"answer":"它与硬山顶形式以及徽派（或江南）地域文化紧密绑定。在【模块二的屋顶部分】左上角的玫瑰图图例中，明确写着“硬山顶（含马头墙）”。此外，在右上角的逻辑关系图中，由“地域文化”节点导向的屋顶形式中，也直接链接到了硬山顶。马头墙是硬山顶的一种极具地域特色的变体，阶梯状墙体在徽派建筑中被称为“封火墙”，主要用于防止相邻建筑火灾蔓延。"},{"id":"m2-wd-M2Q015","questions":["屋顶界面模块中，用于表达中国传统文化“人与自然和谐”理念的核心关键词是什么？","屋顶界面模块中，词云里哪个词体现了古建筑和自然相处的宇宙观？","传统屋顶构件设计中，追求天地人合一的理念用四个字概括为？","除了“等级制度”，屋顶界面模块词云中还收录了哪个代表哲学态度的核心词？","屋顶界面模块中，哪个词代表了传统建筑艺术追求的最高境界，即建筑与环境的融洽？"],"keywords":["模块二","屋顶","屋顶构件"],"answer":"核心关键词是“天人合一”。在【模块二的屋顶部分】左下角的词云图中，可以在左侧偏下的位置找到“天人合一”这个词，它使用深红色字体，在众多建筑术语中尤为突出。这个词代表了传统建筑设计的哲学高度，意味着屋顶的设计不仅要满足居住和防御需求，更要顺应地理、气候（如采光、通风），达到建筑与自然环境的有机融合。"},{"id":"m2-wd-M2Q016","questions":["“攒尖顶”是一种怎样的屋顶形式（它有什么核心特征）？","词云和逻辑图中，“攒尖顶”通常用于哪种特殊的平面建筑上？","亭、塔类建筑通常使用什么屋顶类型？","所有屋面瓦片交汇于顶部一点的屋顶形式叫什么？","圆形或多边形平面上，没有主脊，仅有一个宝顶的屋顶属于哪种？"],"keywords":["模块二","屋顶","屋顶构件","玫瑰图"],"answer":"攒尖顶是一种所有屋面瓦片在顶部交汇于一点（宝顶），没有主脊的屋顶形式。在【模块二的屋顶部分】左上角的玫瑰图中，“攒尖顶”被单独列出，占比6.7%；左下角词云图中也出现了“攒尖顶”一词；右上角逻辑图中它也被列为独立节点。攒尖顶主要用于亭、阁、塔等小型建筑或园林建筑，核心特征是“无脊”，所有坡面汇聚于顶部，形成圆锥形或方锥形伞状结构。"},{"id":"m2-wd-M2Q017","questions":["“山墙”在中国传统屋顶体系中起到什么重要作用？","在逻辑图中，与“硬山顶”和“悬山顶”紧密相关的那面墙体叫什么？","垂直在房屋两端，直接封堵或者超出屋面的承重墙在术语中叫什么？","用来区分硬山和悬山顶的最主要视觉差异点在于哪里？","用来防火、挡风的建筑两侧末端墙体指的是什么？"],"keywords":["模块二","屋顶","屋顶构件","玫瑰图","硬山顶","悬山顶"],"answer":"山墙起到承重、防火、挡风以及界定屋顶边界的重要作用。在【模块二的屋顶部分】左上角的玫瑰图图例中可以看到“硬山顶（含马头墙）”，这里的“马头墙”就是山墙的特殊形式。山墙是垂直在房屋两端的墙体，硬山顶的山墙与屋面齐平或高出，悬山顶的山墙则被屋顶挑出覆盖。它不仅是房屋的结构支撑，还在视觉上定义了建筑的侧立面轮廓。"},{"id":"m2-wd-M2Q018","questions":["“步架”在屋顶结构计算中是一个怎样的概念？","右下角示意图的横坐标通常表示的是什么构件的间隔？","屋顶举架施工中，相邻两个檩条之间的水平距离专业上叫什么？","举折线图中，x轴的刻度值主要测的是什么长度？","计算出檐距离时，那一格一格的梁架间距术语叫做什么？"],"keywords":["模块二","屋顶","屋顶构件","举架","举折"],"answer":"步架是指相邻两根檩条之间的水平距离。在【模块二的屋顶部分】右下角的“举折做法示意图”中查看折线图横坐标，图中标注了一系列等距竖线，这些竖线之间的水平距离就是“步架”，控制着屋顶各段坡度的转折点。传统屋顶并非简单的平直斜坡，而是由多个“步架”组成的折线，最下方（檐口）步架对应平缓坡段，越往上步架对应越陡的坡段，形成优美的凹曲面。"},{"id":"m2-wd-M2Q019","questions":["“屋脊”在屋顶构造中位于哪里？","屋顶两个坡面相交的最高处水平结构叫什么？","图上画出并标有“正脊、垂脊”的位置属于屋顶的哪个部位？","屋顶瓦片收口、主要用来放置脊兽和装饰的地方是哪里？","屋顶最高点那条长长的水平线条构件叫作什么？"],"keywords":["模块二","屋顶","屋顶构件","玫瑰图"],"answer":"屋脊位于屋顶两个坡面相交的最高处。在【模块二的屋顶部分】左下角的词云图中明确出现了“屋脊”二字，左上角的玫瑰图图例中也包含了“正脊”这一类别。屋脊是屋顶的最高线，分为正脊（最高水平线）和垂脊（从正脊向下斜延的线）。它不仅是屋面瓦片的收口处，也是放置脊兽、进行装饰的重要位置。"},{"id":"m2-wd-M2Q020","questions":["系统中“组合式屋顶”是特指哪种屋顶样式？","玫瑰图里标注为“组合式”的屋顶，通常指两种或多种什么结合？","建筑历史中，当主屋顶和副屋顶交接在一起时，整体被称为什么？","歇山顶其实就是哪两种屋顶形式的结合体？","图上排在前几位的单个屋顶样式混搭出来的一种复杂形式叫什么？"],"keywords":["模块二","屋顶","屋顶构件","玫瑰图","悬山顶","歇山顶"],"answer":"组合式屋顶是指两种或多种基本屋顶样式的结合体，如歇山顶就是悬山顶与庑殿顶的结合。在【模块二的屋顶部分】左上角的玫瑰图中，“组合式屋顶”作为一个独立类别被列出，占比11.8%（28个样本）；右上角逻辑图中也被单独列为节点。组合式屋顶通常用于进深较大、功能复杂的建筑，保留了多种屋顶的优势，体现了传统建筑在结构上的灵活性。"},{"id":"m2-wd-M2Q021","questions":["词云图中的“砖瓦”与哪个词共同构成了屋面覆盖系统？","除了砖瓦，屋顶界面系统中还提到了哪种依附于墙面的屋顶构造装饰？","传统屋顶系统中，砖石瓦片是如何共同完成屋面和墙体封顶的？","屋顶的“砖瓦”通常对应于图中的哪类实体的细分构件标注？","屋顶词云中“砖瓦”搭配的“小青瓦”、“瓦当”属于什么系统？"],"keywords":["模块二","屋顶","屋顶构件"],"answer":"它与“小青瓦”、“砖雕”、“瓦当”等词汇共同构成了屋面覆盖系统。在【模块二的屋顶部分】左下角的词云图中，可以看到“砖瓦”、“小青瓦”、“瓦当”、“砖雕”等词汇集中分布在中部和右下区域。传统屋面覆盖系统是一个完整的产业链：小青瓦负责防水，砖瓦件负责结构咬合，瓦当用于檐口收头，砖雕用于屋脊和山墙装饰。"},{"id":"m2-wd-M2Q022","questions":["屋顶界面模块的逻辑关系图中，“结构技术”与“建筑技术”具体包含了哪些做法？","在屋顶形成的技术线路上，“举架/分水”关联的是哪类技术参数？","屋顶界面模块，图中提及的“榫卯体系”或木构做法属于逻辑图的哪个环节？","对应屋顶界面模块的“建筑技术”节点，图里延伸出了哪些具体的施工/结构词汇？","决定屋顶形式的施工工艺部分，具体被归纳到了哪里？"],"keywords":["模块二","屋顶","屋顶构件","关系图","举架"],"answer":"具体包含了举架/分水、榫卯结构、屋面瓦作（如冷摊瓦）等做法。在【模块二的屋顶部分】右上角的逻辑关系图中，左侧“建筑技术”节点下方延伸出的黑色连线直接指向了“举架/分水”、“结构技术”以及“屋面瓦作”。这些做法是传统屋顶能否安全稳固的基石：举架决定屋面形状，榫卯保证节点柔性，瓦作确保屋面不漏水。"},{"id":"m2-wd-M2Q023","questions":["传统屋顶为什么要有“出檐”的做法？","在“生活需求”和“建筑技术”节点上，屋顶向外延伸是为了满足什么？","逻辑关系图中，屋檐伸出的目的是为了防什么（防雨、防晒）？","如果建筑不把屋顶延伸出去，就不能有效保护什么主体结构？","飞椽的作用之一，就是把屋顶往外挑出去，以保护什么？"],"keywords":["模块二","屋顶","屋顶构件","关系图"],"answer":"出檐的主要目的是为了保护墙体和台基免受雨水冲刷。在【模块二的屋顶部分】右上角的逻辑关系图中，找到“生活需求”节点下的“排水需求”，顺着连线向右可以看到它引导向各种屋顶形式，而出檐是排水系统中最核心的物理构造。中国古代建筑多为木结构，墙体和台基最怕常年被雨水浸泡，出檐形成的“滴水线”将雨水排出到远离墙基的地面上，从根本上保护了建筑安全。"},{"id":"m2-wd-M2Q024","questions":["歇山顶和悬山顶的最主要区别是什么？","从视觉和结构上看，歇山顶和悬山顶最大的不同在于哪部分？","悬山顶是“两山挑出”，而歇山顶的特点是“两山有何特征”？","哪类屋顶具备了半坡和山花元素，而悬山顶没有？","屋顶侧立面的三角形区域暴露在外，是哪种屋顶的特征？"],"keywords":["模块二","屋顶","屋顶构件","悬山顶","歇山顶"],"answer":"最主要的区别在于山面（两端山墙的三角形区域）的形态：悬山顶的山墙被屋顶挑出覆盖，歇山顶的山墙下半部分有半坡，形成一个暴露在外的三角形“山花”。在【模块二的屋顶部分】右上角的逻辑图中，可以同时找到“悬山顶”和“歇山顶”两个节点，二者虽同属坡屋顶，但歇山顶引入了“半坡”结构。悬山顶看起来是“屋顶一直伸到墙外”，歇山顶看起来是“从中间突然收了一个半坡”，视觉上更华丽，等级也更高。"},{"id":"m2-wd-M2Q025","questions":["图中“脊饰”词频的出现，体现了对屋顶什么部分的重视？","在词云中，“正吻”、“鸱吻”对应的是什么建筑构件？","屋顶最高处的那些装饰性构件除了美观，还有什么文化意义？","梁思成等古建专家常研究的“屋脊上的雕塑和兽头”在系统中被归入什么关键词？","古建中既可用于防火迷信象征，又能美化建筑顶部的艺术构件是？"],"keywords":["模块二","屋顶","屋顶构件"],"answer":"体现了对屋顶最高处（屋脊）的美化、等级象征和防火迷信的重视。在【模块二的屋顶部分】左下角的词云图中可以看到“脊饰”、“正脊”、“瓦当”等词，同时右上角逻辑图“地域文化”节点下“风水观念”和“等级制度”直接关联到了脊饰。屋脊是屋顶的“头面”，脊饰（如吻兽）不仅有美化作用，在文化上鸱吻被传说能吸水防火，且不同数量的脊兽代表不同官员品级，是礼制的直观体现。"},{"id":"m2-wd-M2Q026","questions":["在逻辑图中，屋顶形式被哪些主要维度所影响？","系统右上方的逻辑关系图把屋顶成因归为了哪三大类？","影响屋顶长成什么样子的主要因素是来自哪里（自然、人、社会）？","支撑屋顶选择的逻辑支柱，除了建筑技术，还有哪两个主要方面？","决定屋顶形态的宏观因素，被系统划分为了哪几个一级标题？"],"keywords":["模块二","屋顶","屋顶构件","关系图"],"answer":"屋顶形式主要受自然环境、生活需求、建筑技术、地域文化四个核心维度影响。在【模块二的屋顶部分】右上角的逻辑图中，最左侧整齐排列着四个黑色方块图标，分别标注为“自然环境”、“生活需求”、“建筑技术”、“地域文化”，它们通过连线发散到右侧，共同决定了最终的屋顶形式。这四个维度构成完整逻辑闭环：自然环境提供约束条件，生活需求提出功能目标，建筑技术提供实现手段，地域文化赋予精神内涵。"},{"id":"m2-wd-M2Q027","questions":["如果你在系统中查找“隔热”的性能，它会和哪些因素绑定在一起？","词云和逻辑图中，“隔热”需求主要和气候里的什么因素关联？","为了进行隔热，古建通常选择更高敞的哪种屋顶类型？","“隔热”和“采光”在图中被归类到了哪个前置条件的下面？","图中处于“生活需求”节点下的功能关键词“采光”和什么是对应关系？"],"keywords":["模块二","屋顶","屋顶构件","歇山顶"],"answer":"“隔热”性能和“夏季炎热（气候）”、“通风（需求）”、“歇山顶（形式）”绑定在一起。在【模块二的屋顶部分】右上角的逻辑图中，从“自然环境”节点找到“夏季炎热”，再找到“生活需求”节点下的“通风隔热”，顺着箭头右行，这两条线最终都汇聚到“歇山顶”。这说明在传统智慧中，隔热不是一个独立技术难题，而是一个系统性解决方案，歇顶因具有半坡和山花，利于热空气上升排出，因此隔热性能优异。"},{"id":"m2-wd-M2Q028","questions":["“举折”做法的主要目的是什么？","右下角技术图表里，计算“举高/步架”是为了形成什么样的屋面形态？","古代工匠调节屋面坡度，使它上陡下缓的施工技法叫什么？","计算举折的数据，最终是为了达成怎样的视觉效果和实用功能？","传统屋面之所以能形成优美的曲线，而不是一条直线斜坡，是因为采用了什么步骤？"],"keywords":["模块二","屋顶","屋顶构件","图表","举折"],"answer":"举折的主要目的是为了形成优美的凹曲面屋面，并优化排水与采光。在【模块二的屋顶部分】右下角的“举折做法示意图”中，右上角折线图显示屋面的实际坡度不是一条直线，而是由多个折点连接而成的曲线（上陡下缓），这个施工工艺就是“举折”。直线斜坡在视觉上僵硬，且雨水流速过快易损坏檐口瓦片；举折形成的凹曲面（“反宇向阳”），不仅使建筑外观灵动优美，还能减缓雨水下落速度，让冬季阳光更多照入室内。"},{"id":"m2-wd-M2Q029","questions":["“防水”功能在传统屋顶结构中是靠什么部件组合实现的？","为了防风挡雨，最传统的木质屋顶上最外层的覆盖层是由什么构成的？","词云中体现了哪些部件具有防水作用？","小青瓦在进行铺砌时，采用了什么排列方式来增强防漏水？","屋顶的水关键是要靠什么流走，以及由什么挡住水不渗进木架？"],"keywords":["模块二","屋顶","屋顶构件","举架"],"answer":"防水是靠小青瓦（覆盖）、瓦当/滴水（檐口排阻）与合理的排水坡度（举架）三者组合实现的。在【模块二的屋顶部分】综合查看两个区域：左下角词云图中“小青瓦”、“排水”、“防水”三个词独立存在，右下角折线图中“举架”参数决定排水坡度。三重防线包括：小青瓦互相叠压形成“毛细缝隙阻水”层是第一道防线；檐口瓦当和滴水利用“落水”原理将水导走是第二道防线；举架形成的坡度利用重力让水快速离开是第三道防线。"},{"id":"m2-wd-M2Q030","questions":["这套系统是用来做传统屋顶什么的？","综合各个板块的信息（占比、成因、参数、做法），屋顶界面的核心应用场景是什么？","按照系统的功能板块，屋顶界面模块主要是帮助用户解决传统建筑哪方面的问题？","这个屋顶界面模块的前端是一套关于什么建筑构件的综合知识库？","从“类型识别”到“参数计算”再到“文化成因”，屋顶界面模块试图完整地分析什么？"],"keywords":["模块二","屋顶","屋顶构件","举架"],"answer":"这套系统是用来做传统古建筑屋顶构件的数据化分析、展示与学习的交互平台。整体回顾【模块二的屋顶部分】全部内容：左上角是定量统计（类型占比），右上角是定性溯源（形成逻辑），左下角是文本语义（关键词），右下角是工程参数（举架/计算）。这种多维度、可视化的设计，完美满足对屋顶构件进行拆解研究和交互查询的需求，是一个建筑学术研究工具，对建筑史研究、传统村落保护、数字化教学具有极高的实用价值。"},{"id":"m2-mtq-MQ001","questions":["有马头墙和无马头墙时，徽派古建筑的烟气排放速度分别是多少？","马头墙能提高排烟速度吗？","马头墙对烟气流动有什么影响？","有马头墙时烟气速度是多少？"],"keywords":["模块二","马头墙","防火性能"],"answer":"根据王彦等（2010）在《安全与环境学报》的数值模拟研究，有马头墙时徽派古建筑的最高烟气速度为6.0 m/s，无马头墙时仅为4.5 m/s。马头墙与天井围成的竖井结构增强了热压通风，使烟气排放速度提升约33%。此外，有马头墙时地面附近烟气速度降低（0.70 m/s vs 0.95 m/s），烟气在中上部排出，有利于人员逃生，烟气拉升高度约2.5米。"},{"id":"m2-mtq-MQ002","questions":["一阶、三阶、五阶马头墙对火灾横向蔓延的阻隔提升率分别是多少？","马头墙的阶数越高防火效果越好吗？","五阶马头墙能提升多少防火能力？","不同马头墙形式的防火性能差异有多大？"],"keywords":["模块二","马头墙","防火性能","防火"],"answer":"根据陈贵勇（2025）的研究，以普通人字形山墙为基准，考虑热辐射、热羽流、飞火三种蔓延方式的综合贡献率（假定50%、30%、20%）后，一阶马头墙对火灾横向蔓延的整体阻隔提升率为24.37%，三阶马头墙为44.83%，五阶马头墙为53.48%。阻隔提升率与马头墙高出屋面的面积以及墙体立面的不规则程度呈正相关，阶数越高，防火性能越好。"},{"id":"m2-mtq-MQ003","questions":["马头墙在不同蔓延方式下的阻隔提升率有何差异？","马头墙对热辐射的阻隔效果最好吗？","飞火蔓延方式下马头墙的作用大吗？","热羽流的阻隔提升率是多少？"],"keywords":["模块二","马头墙","防火性能"],"answer":"根据陈贵勇的数据，对于热辐射蔓延，一阶马头墙平均阻隔提升率41.47%，三阶75.25%，五阶82.50%；对于热羽流蔓延，一阶11.99%，三阶24.63%，五阶39.40%；对于飞火蔓延，一阶仅0.22%，三阶1.90%，五阶2.05%。马头墙对热辐射的阻隔效果最显著，对飞火的阻隔作用有限。"},{"id":"m2-mtq-MQ004","questions":["马头墙的座头有哪四种主要形制？各有什么象征意义？","印斗式马头墙代表什么寓意？","鹊尾式马头墙为什么叫鹊尾？","坐吻式马头墙上的吻兽有什么作用？"],"keywords":["模块二","马头墙","形制分"],"answer":"马头墙的四种主要形制及象征意义：印斗式——座头形如金印或斗拱中的斗，透雕“卍”字纹或“田”字纹，象征对读书做官的追求；朝笏式——座头做成朝笏样式，彰显身份等级，暗含平步青云的仕途祈愿；坐吻式——座头设吻兽构件（如鳌鱼、天狗），寓意祈求健康平安、辟邪除灾；鹊尾式——座头形似喜鹊尾巴，寓意抬头报喜，表达对美好生活的追求。"},{"id":"m2-mtq-MQ005","questions":["马头墙的“五岳朝天”是什么意思？对应几叠式？","五叠式马头墙叫什么？","最高等级的马头墙是什么？","为什么叫五岳朝天？"],"keywords":["模块二","马头墙","形制分"],"answer":"“五岳朝天”是五叠式马头墙的俗称，是马头墙的最高等级形式。较大型的民居因设前厅后堂、房屋进深较大，马头墙的叠数可多至五叠式，称为“五岳朝天”。一般建筑常见为两叠式或三叠式。叠级数量反映了建筑规模和主人的社会地位。"},{"id":"m2-mtq-MQ006","questions":["马头墙的叠级数与建筑规模有什么关系？","一般民居马头墙是几叠？","叠级越多表示什么？","一叠到五叠分别对应什么建筑？"],"keywords":["模块二","马头墙","叠级体系"],"answer":"根据方根宝的研究，马头墙的叠级数与建筑规模直接相关：一级、二级、三级马头墙适用于一般建筑；五叠式（五岳朝天）适用于较大的民居，因设前厅后堂、房屋进深较大。所有论文均未提供不同叠级的使用比例数据，但明确五叠式是最高等级，体现建筑规模和主人地位。"},{"id":"m2-mtq-MQ007","questions":["马头墙除了防火，还有哪些功能？","马头墙能防风防雨吗？","马头墙的装饰作用是什么？","马头墙如何体现等级？"],"keywords":["模块二","马头墙","功能","封火墙","防火"],"answer":"马头墙除了核心的防火功能（又称封火墙），还具有以下功能：防风防雨——徽州多雨多风，马头墙高出屋面可防止暴风吹翻屋瓦，解决漏渗水问题；装饰美化——高低错落的阶梯状设计使建筑显得错落有致，形成“万马奔腾”的视觉效果；等级象征——通过叠级数量（一至五级）和座头形制（印斗式、朝笏式等）体现建筑等级和主人身份地位。"},{"id":"m2-mtq-MQ008","questions":["马头墙的“马”字有什么文化寓意？","为什么叫马头墙？","马头墙的命名与马有关吗？","马到成功的寓意怎么来的？"],"keywords":["模块二","马头墙","文化寓意","封火墙"],"answer":"马头墙因形似马头而得名。马在传统文化中是吉祥物，有“一马当先、马到成功、汗马功劳”等成语，表达对成功和进取的赞美。将封火墙称为“马头墙”，寄托了主人对事业成功、家族兴旺的美好愿望。登高俯视聚族而居的村落，高低起伏的马头墙给人“万马奔腾”的动感，隐喻宗族生气勃勃、兴旺发达。"},{"id":"m2-mtq-MQ009","questions":["传统空斗墙的传热系数是多少？与马头墙墙体有什么关系？","马头墙墙体的保温性能如何？","空斗墙的K值是多少？","传统墙体传热系数范围是多少？"],"keywords":["模块二","马头墙","热工性能"],"answer":"马头墙墙体采用传统空斗砖墙构造。根据模块二数据，传统空斗墙（350mm厚，含碎砖+轻质粘土夹层）的传热系数为1.17-1.231 W/m²·K，优于现代实心墙（1.8-2.2 W/m²·K）。夹层厚度270mm，导热系数0.47 W/m·K，贡献了86.4%的热阻。马头墙墙体本身具有较好的保温隔热性能，这也是其能减少火灾热辐射传递的原因之一。"},{"id":"m2-mtq-MQ010","questions":["不同墙体砌筑方式下，传热系数有何差异？","青砖空斗填黄泥砌法的传热系数是多少？","水泥砖空斗砌法的保温性能好吗？","哪种墙体热工性能最差？"],"keywords":["模块二","马头墙","热工性能"],"answer":"根据郑彬、傅秀章（2012）的现场实测，四种墙体的传热系数：传统青砖空斗填黄泥砌法最优，为1.892 W/m²·K；水墨宏村新型复合墙体次之，为2.024 W/m²·K；水泥砖空斗砌法为2.821 W/m²·K；际村农民自建房砌块实砌法最差，高达3.588 W/m²·K。传统空斗砌法比现代实砌法性能提升约89.7%，体现了构造方式对热工性能的决定性影响。"},{"id":"m2-mtq-MQ011","questions":["马头墙墙体的夏季内表面温度和冬季热桥部位温度分别是多少？","夏天马头墙内表面热吗？","冬天马头墙会有冷凝吗？","马头墙的热桥问题严重吗？"],"keywords":["模块二","马头墙","热工性能"],"answer":"根据袁玉华的研究，马头墙墙体（空斗砖墙）夏季内表面最高温度可达43.0℃。冬季热桥部位内表面温度仅为2.8℃，低于露点温度（露点温度约12.9℃）10.1℃，容易产生结露和霉菌问题。这说明马头墙墙体在冬季存在热桥效应，需要采取保温措施改善。"},{"id":"m2-mtq-MQ012","questions":["马头墙元素在现代建筑中有哪些创新应用？","马头墙式桥墩是什么？","现代设计如何提取马头墙元素？","马头墙在BIPV技术中怎么用？"],"keywords":["模块二","马头墙","现代应用"],"answer":"马头墙元素的现代应用包括：1）马头墙式桥墩——将马头墙形态用于桥梁设计，墩高约7m，墙顶两层迭落，边跨与中跨比值采用黄金分割（约0.618）；2）抽象简化——简化瓦脊为灰边线条，取消繁复图案；3）材质转换——使用金属、石材、木材等现代材料；4）BIPV/T技术——在西向马头墙内设置太阳能烟囱，流道尺寸0.1×0.7×9.9m，烟囱容积0.79m³，用于改善室内通风和发电。"},{"id":"m2-mtq-MQ013","questions":["马头墙式桥墩的设计高度和比例是多少？","桥墩上的马头墙多高？","马头墙桥墩的边跨中跨比是多少？","桥墩马头墙有几层跌落？"],"keywords":["模块二","马头墙","现代应用"],"answer":"根据赵勇（2008）的研究，马头墙式桥墩的墩高约为7米，墙顶设为两层迭落，显著增强了桥墩的空间感和层次感。边跨与中跨的比值采用黄金分割比率（约0.618），以达到最佳的视觉效果。这种设计将徽派马头墙的形态美学应用于现代桥梁工程中。"},{"id":"m2-mtq-MQ014","questions":["在16篇马头墙相关文献中，出现频率最高的关键词有哪些？","马头墙研究中哪些词最常出现？","防火和形制哪个词频率更高？","徽商和读书做官出现的次数多吗？"],"keywords":["模块二","马头墙","关键词频率","封火墙","防火"],"answer":"根据对16篇文献的关键词统计，高频关键词（出现频率≥10）包括：防火16次、封火墙16次、印斗式14次、鹊尾式14次、坐吻式13次、朝笏式12次、阶梯状15次、徽商15次、读书做官14次、五岳朝天10次、座头10次。此外，隔离火源12次、小青砖12次、白灰粉刷12次、青瓦11次、粉墙黛瓦11次。高频词反映了马头墙研究的核心聚焦：防火功能、形制分类、文化寓意和材料工艺。"},{"id":"m2-mtq-MQ015","questions":["马头墙特征网络中的影响因素分为哪几类？各包括哪些细分因素？","自然环境对马头墙有什么影响？","建筑技术和地域文化如何影响马头墙？","生活需求中的防火防风如何体现？"],"keywords":["模块二","马头墙","结构关联","防火"],"answer":"马头墙特征网络第一层为四大影响因素：自然环境、生活需求、建筑技术、地域文化。第二层细分因素共10个：自然环境→山地地形、多雨潮湿、木材资源；生活需求→防火需求、防风遮阳；建筑技术→硬山顶普及、砖材产能提升；地域文化→宗族观念、徽商经济与崇文重教、美学特征。这些因素共同决定了马头墙的阶梯状跌落、粉墙黛瓦、五岳朝天、座头装饰、墙脊形态、组合式韵律轮廓等特征类型。"},{"id":"m2-mtq-MQ016","questions":["马头墙的主要特征类型对应哪些构造做法？","阶梯状跌落需要哪些构造？","粉墙黛瓦的色彩体系如何实现？","座头装饰的构造细节是什么？"],"keywords":["模块二","马头墙","结构关联"],"answer":"马头墙特征类型对应的构造做法：阶梯状跌落→青砖实心砌筑、阶梯状逐层跌落、墙身尺度按进深与叠数比例控制；粉墙黛瓦的色彩体系→白灰粉刷墙面、小青瓦覆顶；五岳朝天→阶梯状逐层跌落、墙身尺度按进深与叠数比例控制；座头装饰→博风板与座头安装；墙脊形态→三线排檐砖与小青瓦覆顶、墙脊水平带翘角/圆弧面收边；组合式韵律轮廓→阶梯状逐层跌落、墙身尺度按进深与叠数比例控制。"},{"id":"m2-mtq-MQ017","questions":["徽派传统民居在罕遇地震下的层间位移角是多少？加固后有什么提升？","传统木结构民居抗震性能如何？","拼装抱箍加固能提高多少抗震能力？","层间位移角1/81是什么意思？"],"keywords":["模块二","马头墙","抗震性能"],"answer":"根据葛子毅等（2025）的振动台试验，徽派穿斗式木结构传统民居在罕遇地震（加速度0.220g）下，加固前层间位移角为1/81，加固后提升至1/109。整体结构耗能提升21.02%，加固层耗能提升4.30%。拼装抱箍加固技术能有效提高传统民居的抗震性能，满足更高设防烈度要求。"},{"id":"m2-mtq-MQ018","questions":["性能增强古建筑砌体墙的承载力和延性分别能提升多少？","环氧树脂加固砖墙效果如何？","甲基丙烯酸甲酯能提高延性吗？","哪种加固材料延性提升更大？"],"keywords":["模块二","马头墙","抗震性能"],"answer":"根据赵浩等（2022）的研究，使用环氧树脂增强古建筑砌体墙，承载力提升30%，延性提升31%；使用甲基丙烯酸甲酯增强，承载力提升18%，延性提升42%。甲基丙烯酸甲酯对延性的改善更显著，环氧树脂对承载力的提升更突出。两种材料均可用于马头墙等徽派建筑墙体的抗震加固。"},{"id":"m2-mtq-MQ019","questions":["有环梁构造柱和无环梁构造柱的木构架模型抗震设防烈度分别是多少？","环梁和构造柱能提高抗震等级吗？","模型1和模型2的设防烈度差异多大？","木构架节点最大应变是多少？"],"keywords":["模块二","马头墙","抗震性能"],"answer":"根据《北京工业大学学报》研究，有环梁和构造柱的木构架模型（模型1）抗震设防烈度可达IX度，无环梁和构造柱的模型2仅为VIII度。模型1在环梁与构造柱交汇处的榫卯节点最大应变为2055 με，模型2为3050 με（普通混凝土峰值应变为2000 με，极限应变为3800 με）。环梁和构造柱能显著提高木构架的抗震能力。"},{"id":"m2-mtq-MQ020","questions":["马头墙太阳能烟囱技术的尺寸和通风效果如何？","马头墙内可以装太阳能烟囱吗？","太阳能烟囱的流道尺寸是多少？","换气次数能达到多少？"],"keywords":["模块二","马头墙","BIPV/T应用"],"answer":"根据可再生能源期刊的研究，西向马头墙内设置的太阳能烟囱流道尺寸为0.1m（宽）×0.7m（深）×9.9m（高），烟囱容积0.79m³。夏季太阳能烟囱出口最高温度约80℃，可使房间4的换气次数达到1-4次/h，房间1达到4-14次/h，满足规范要求的冬季≥1.0次/h、夏季≥1.0次/h。该技术将马头墙与被动式通风、光伏发电相结合。"},{"id":"m2-mtq-MQ021","questions":["新徽派民居BIPV/T系统的全年发电量是多少？","马头墙结合光伏能发多少电？","太阳能烟囱加光伏瓦的总发电量？","BIPV/T技术的经济效益如何？"],"keywords":["模块二","马头墙","BIPV/T应用"],"answer":"根据案例研究，一栋面阔8.1m、进深8.7m、层高3.3m的新徽派民居，采用西向马头墙太阳能烟囱（0.79m³）和南向45°倾角门楼光伏瓦（面积3.90m²，单晶硅166×166mm），全年发电总量为5367.079 kW·h。该系统不仅改善了室内通风，还提供了可再生能源，实现了传统元素与现代绿色技术的融合。"},{"id":"m2-mtq-MQ022","questions":["现代建筑设计中如何抽象和简化马头墙元素？","新徽派建筑怎么处理马头墙？","马头墙的简化手法有哪些？","材质转换用什么材料？"],"keywords":["模块二","马头墙","现代设计策略"],"answer":"现代建筑对马头墙元素的抽象简化策略包括：1）抽象简化——简化复杂的瓦脊结构为灰边线条，取消脊瓦和其下绘制的繁复图案；2）材质转换——使用现代材料（金属、石材、木材、灰色系涂料）替代传统青砖、白灰，通过色彩过渡创造现代感与古典美并存的视觉效果；3）适度运用——选择最具代表性和特色的部分（如阶梯状轮廓、座头形态），保持设计简洁，避免简单照搬。"},{"id":"m2-mtq-MQ023","questions":["马头墙的总体高度、墙体厚度和基础深度大约是多少？","马头墙一般多高？","墙体厚度有标准吗？","基础需要挖多深？"],"keywords":["模块二","马头墙","尺寸数据"],"answer":"根据研究报告，传统马头墙的尺寸参考范围：墙体总高度5-10米，典型高度6-7米；墙体厚度40-60厘米；马头造型（顶部座头部分）高度2-3米；基础深度大于1米，基础宽度与墙体相同；砖缝宽度小于5毫米，防止渗水。小青瓦规格长约40厘米、宽约20厘米，铺设用量约80-100片/平方米。实际尺寸因建筑规模和地区有所差异。"},{"id":"m2-mtq-MQ024","questions":["马头墙的传统设计比例“华制”是怎样的？","一华等于多少厘米？","马头墙各叠的宽度和高度比例如何？","传统马头墙的尺寸公式是什么？"],"keywords":["模块二","马头墙","传统设计比例"],"answer":"根据方根宝论文中记载的传统设计比例（华制），第一叠宽度为二华，第二叠宽度为一华；第一叠高度为三华，第二叠高度为二华半。“华”是传统营造尺单位，1华约合33厘米（此换算来自外部资料，仅供参考）。原文公式显示不完整，建议查阅原始论文获取完整比例关系。这一比例体系体现了徽州工匠对马头墙形态的精确控制。"},{"id":"m2-fq-WQ001","questions":["传统青砖空斗墙的传热系数是多少？与现代墙体相比性能如何？","传统空斗墙的保温性能怎么样？","青砖空斗墙的K值大概多少？","传统墙体比现代墙体热工性能好吗？"],"keywords":["模块二","粉墙","墙体热工性能","传热"],"answer":"根据郑彬、傅秀章（2012）对徽州民居主要砌体外墙的现场实测，传统青砖空斗填黄泥砌法的平均传热系数为1.892 W/m²·K，而水泥砖空斗砌法为2.821 W/m²·K，水墨宏村外保温做法为2.024 W/m²·K，际村农民自建房砌块实砌法高达3.588 W/m²·K。传统空斗墙的保温性能最优，与现代最差墙体相比性能提升约89.7%。另外，袁玉华论文中记载的350mm完整多层构造空斗墙传热系数更低，为1.17-1.231 W/m²·K，优于现代实心墙（1.8-2.2 W/m²·K）。"},{"id":"m2-fq-WQ002","questions":["传统空斗墙由哪些构造层次组成？每层的热阻贡献是多少？","空斗墙的夹层是什么材料？","传统墙体为什么保温效果好？","空斗墙的厚度和分层是怎样的？"],"keywords":["模块二","粉墙","墙体构造","传热"],"answer":"传统空斗墙总厚度约350mm，从外到内共5层：外石膏/灰泥（10mm，导热系数0.76 W/m·K，热阻占比2.0%）、外粘土砖（30mm，0.93，4.8%）、核心夹层（270mm，碎砖+轻质粘土，0.47，86.4%）、内粘土砖（30mm，0.93，4.8%）、内石膏/灰泥（10mm，0.76，2.0%）。夹层贡献了86.4%的热阻，是保温性能的关键。整体传热系数1.17-1.231 W/m²·K。"},{"id":"m2-fq-WQ003","questions":["徽州传统民居外墙夏季和冬季的表面温度大约是多少？","传统墙体夏天表面温度有多高？","冬天传统墙体表面温度低吗？","新建保温墙体与传统墙体表面温度差异大吗？"],"keywords":["模块二","粉墙","墙体热工性能"],"answer":"根据《徽州民居砌体外墙热工性能剖析与改进技术探索》，传统民居外墙（青砖/土坯）夏季外墙表面最高温度可超过45℃，室内外温差仅3-5℃；冬季外墙表面最低温度低于5℃，室内外温差达8-10℃。而采用新型材料+保温的新建民居外墙，夏季表面温度≤35℃，室内外温差8-10℃；冬季表面温度≥8℃，室内外温差5-7℃。传统墙体在极端天气下热工性能较差。"},{"id":"m2-fq-WQ004","questions":["青砖空斗墙与水泥空斗墙在温度稳定性上有什么差异？","青砖和水泥砖哪种保温效果好？","空斗墙用青砖还是水泥砖好？","为什么传统青砖墙更稳定？"],"keywords":["模块二","粉墙","墙体对比"],"answer":"根据《建筑技艺》期刊对皖南民居的测试（室外温度-5~15℃，热箱加热35℃），青砖空斗墙内表面温度范围为34.5-35.2℃，平均34.9℃，热流密度52-60 W/m²，波动小；水泥空斗墙内表面温度仅23-24℃，平均23.5℃，热流密度70-91 W/m²，波动大。青砖空斗墙内表面温度比水泥空斗墙高11.4℃，且温度稳定性显著优于水泥砖墙，保温性能更好。"},{"id":"m2-fq-WQ005","questions":["徽州传统民居中，外墙、屋顶、天井对防热的贡献率分别是多少？","粉墙的防热效果占多大比例？","哪个构件的防热贡献最大？","天井的防热作用大吗？"],"keywords":["模块二","粉墙","防热贡献","防热"],"answer":"根据黄志甲等（2019）的研究，徽州传统民居中被动式防热设计的总贡献率中，外墙占48.7%，屋顶占39.7%，天井占11.6%。在外墙的各项策略中，反射的贡献率最高（18.6%），其次是外遮阳（14.1%）、蓄热（12.3%）、对流换热（2.9%）和长波辐射（0.8%）。这说明粉墙（外墙）是防热设计中最重要的构件。"},{"id":"m2-fq-WQ006","questions":["徽州民居门罩有哪几种类型？它们的下枋与门框距离分别是多少？","门楣式、垂花式、牌楼式门罩有什么区别？","不同门罩的尺寸范围是多少？","哪种门罩规模最大？"],"keywords":["模块二","粉墙","门罩尺寸"],"answer":"徽州民居门罩主要分为三种类型：门楣式门罩（构造简单，下枋与门框距离0-375mm，平均187.5mm，变异系数86.6%）；垂花门式门罩（有垂珠装饰，距离440-680mm，平均538.3mm，变异系数19.5%）；牌楼式（八字）门楼（规模最大，距离1040-1580mm，平均1241.7mm，变异系数23.7%）。牌楼式门楼用于有殊荣的民居，垂花式和牌楼式尺寸相对规范，门楣式变化较大。"},{"id":"m2-fq-WQ007","questions":["牌楼式门楼的边柱距与门洞宽度的标准比值是多少？实际偏差范围是多少？","门楼的比例设计有标准吗？","边柱和门洞的比例是多少？","徽州门楼的比值一般控制在什么范围？"],"keywords":["模块二","粉墙","门罩比例"],"answer":"根据实测数据，牌楼式门楼边柱到门框距离与门洞宽度的比值，启泰堂为1.082，汤金宝宅为0.800，舒镇华宅为0.995，平均值为0.967。实际偏差在±18%范围内。0.967可作为设计标准值，体现了徽州工匠对比例关系的精确控制。"},{"id":"m2-fq-WQ008","questions":["门楣式门罩各构件之间存在哪些比例关系？","匾额和下枋的尺寸有什么关系？","元宝梁和五路檐线的大致比例是多少？","束腰脊和屋瓦的高度相近吗？"],"keywords":["模块二","粉墙","门罩构件"],"answer":"根据张岚元论文对4处民居的测量，门楣式门罩构件间的典型比例关系为：束腰脊与屋瓦高度相近（比值约0.19）；元宝梁约为五路檐线的一半（实测平均307.5mm vs 390.8mm，比值0.79）；匾额高度约为下枋的两倍（平均194.8mm vs 257.8mm，比值0.76，接近2倍）。这些比例关系保证了视觉上的协调与主次分明。"},{"id":"m2-fq-WQ009","questions":["天井面积与通风得分有什么关系？最佳天井面积是多少？","天井多大通风效果最好？","天井面积和通风得分的关系图是什么样？","9-12平米的天井通风如何？"],"keywords":["模块二","粉墙","天井通风","关系图"],"answer":"根据模块二数据，16个天井样本的面积与通风得分呈现非线性关系。面积在4-8m²时得分25-31分（较差）；面积在9-12m²时得分38-56分（最佳区间）；面积在13-21m²时得分28-58分（较好但波动大）。最佳天井面积为9-12m²，其中M2J4（14.7m²）得分60分最高，但面积超过12m²后得分下降。面阔5.25m（1丈5尺）的天井组（M2）平均通风得分55分，显著优于其他组。"},{"id":"m2-fq-WQ010","questions":["“回”字型天井和竖型天井相比原方案，夏季换气次数分别提升多少？","哪种天井形式通风效果最好？","回字型天井能提高多少通风？","改造天井对换气次数的影响大吗？"],"keywords":["模块二","粉墙","天井通风"],"answer":"根据室内风环境模拟数据，原方案起居室夏季换气次数为7.2次/h。改为竖型天井后，换气次数提升至27次/h，提升275%；改为“回”字型天井后，换气次数提升至36次/h，提升400%。冬季效果也有改善：原方案5.8次/h，竖型天井9次/h（提升55%），回字型天井9.4次/h（提升62%）。过渡季原方案14次/h，竖型45次/h（提升221%），回字型60次/h（提升329%）。回字型天井通风改善效果最佳。"},{"id":"m2-fq-WQ011","questions":["徽州传统民居冬季室内平均温度是多少？与舒适温度差距多大？","冬天徽州老房子里面冷不冷？","传统民居冬季室温大约几度？","室内热环境舒适吗？"],"keywords":["模块二","粉墙","室内热环境"],"answer":"根据袁玉华对徽州传统民居冬季热环境的实测（1月18-20日），室外温度-1.8~13.5℃，平均3.8℃；室内温度在2.9-7.2℃之间，平均约5.0℃。而人体舒适温度标准为18-28℃，冬季室内平均温度低于舒适标准13-23℃。南向卧室（有阳台）平均温度5.9℃较高，北向卧室仅4.6℃。室内相对湿度约56%，偏潮湿。传统民居冬季热环境较差，需要改善。"},{"id":"m2-fq-WQ012","questions":["徽州传统建筑中青砖、土坯、石材、木材的导热系数分别是多少？","青砖的导热系数是多少？","传统建筑材料的保温性能如何？","黟县青石的导热系数高吗？"],"keywords":["模块二","粉墙","材料参数"],"answer":"根据《徽州民居砌体外墙热工性能剖析与改进技术探索》，常用传统材料导热系数：青砖0.8-1.0 W/m·K（密度1700-1900 kg/m³），土坯0.5-0.7 W/m·K，石材（黟青石）1.5-3.0 W/m·K，木材0.12-0.15 W/m·K。青砖数据与袁玉华论文（0.87 W/m·K）一致。木材导热系数最低，保温性能最好；石材导热系数最高，不适宜单独作为保温材料。"},{"id":"m2-fq-WQ013","questions":["在空斗墙夹层中填充保温材料，热阻可以提升多少倍？","如何提高传统墙体的保温性能？","填充聚氨酯颗粒效果好吗？","空斗墙改造的最佳方案是什么？"],"keywords":["模块二","粉墙","改造技术","传热"],"answer":"根据改造方案热阻计算（基准墙：空斗墙320mm+石灰砂浆，总热阻0.43 m²·K/W，传热系数2.33 W/m²·K），填充无机轻集料保温浆料I型后热阻提升至2.51（5.8倍），传热系数0.40；填充聚氨酯颗粒后热阻提升至10.49（24.5倍），传热系数0.095；填充聚氨酯颗粒+夹层灌木质纤维发泡后热阻14.24（33.1倍），传热系数0.070。聚氨酯颗粒填充效果最佳，但需注意防火和耐久性。"},{"id":"m2-fq-WQ014","questions":["在25篇粉墙相关文献中，出现频率最高的关键词有哪些？","粉墙研究中最常讨论什么？","粉墙色彩和马头墙哪个词出现多？","天人合一在文献中出现频率高吗？"],"keywords":["模块二","粉墙","关键词频率"],"answer":"根据对25篇文献的关键词统计，出现频率最高的关键词为：色彩（粉墙色彩）19次，门楼18次，屋顶17次，防火16次，风水14次，天人合一14次，徽商13次，四水归堂12次，聚族而居10次，装饰9次，徽州文化9次，小青瓦9次。这些高频词反映了粉墙研究的核心关注点：视觉特征、构件构成、功能需求、文化寓意和材料工艺。"},{"id":"m2-fq-WQ015","questions":["粉墙特征网络图中的影响因素分为哪四个层次？每个层次包括哪些细分因素？","粉墙的设计受哪些因素影响？","自然环境和地域文化分别影响粉墙的哪些方面？","建筑技术层面的细分因素有哪些？"],"keywords":["模块二","粉墙","粉墙特征网络"],"answer":"粉墙特征网络第一层为四大影响因素：自然环境、生活需求、建筑技术、地域文化。第二层细分因素共11个：自然环境→防潮除湿、隔热保温；生活需求→视觉舒适、防火安全；建筑技术→材料获取、构造工艺、经济节约、维护便捷；地域文化→审美追求、风水理念、儒道思想。这些因素共同决定了粉墙的主要特征类型和构造做法。"},{"id":"m2-fq-WQ016","questions":["粉墙的构造做法有哪些？分别对应哪些特征类型？","粉白墙面需要哪些构造做法？","马头墙的构造做法是什么？","青石勒脚通过什么方式实现？"],"keywords":["模块二","粉墙","粉墙特征网络"],"answer":"粉墙的构造做法共有7种：石灰粉刷面层、空斗墙砌筑、砖石基座、木构墙体、木构支撑、墙内木筋、墙体收分。对应关系：粉白墙面→石灰粉刷面层、空斗墙砌筑、墙内木筋；封火马头墙→空斗墙砌筑、砖石基座、木构支撑；青石门框/门罩→砖石基座、木构支撑；青石勒脚→砖石基座；墙体收分→空斗墙砌筑、墙体收分。"},{"id":"m2-fq-WQ017","questions":["徽州传统民居中，厢房、厅堂、天井的围护结构分别采用哪些材料？","内墙和天花板用什么材料？","天井空斗砖墙的构造层次？","地面和屋面的材料组成？"],"keywords":["模块二","粉墙","墙体材料"],"answer":"根据余梦琦论文，厢房内墙为杉木板（厚0.05m，λ=0.29），天花板为杉木板（0.03m），地垄为杉木板+空气层+三合土。厅堂内墙为杉木板，屋面为小青瓦（0.01m）+轻质黏土（0.025m）+杉木板（0.015m），地面为三合土。天井围护结构为空斗砖墙：石膏/灰泥（0.01m）+粘土砖（0.03m）+夹层碎砖轻质粘土（0.27m）+粘土砖（0.03m）+石膏/灰泥（0.01m），以及青石地面和杉木门。"},{"id":"m2-fq-WQ018","questions":["20世纪80年代以来，徽州住宅墙体构造发生了怎样的演变？热工性能如何变化？","现代徽州民居的墙体变厚了吗？","为什么现代墙体的保温性能反而变差了？","不同时期的墙体传热系数是多少？"],"keywords":["模块二","粉墙","墙体演变","传热"],"answer":"根据袁玉华论文，1980年代采用180mm青砖空斗墙，传热系数约1.2-1.5 W/m²·K，性能较好；80年代末至2007年采用180mm实心红砖+内外水泥砂浆抹灰，厚度增至220mm但传热系数升至1.8-2.2，性能下降；2007年后改为水泥实心砖墙，同样220mm，传热系数仍为1.8-2.2。而传统350mm完整空斗墙传热系数仅1.17-1.231。现代墙虽增加40mm厚度，但因失去夹层导致热工性能反而退化35-47%。构造方式比厚度更重要。"},{"id":"m2-fq-WQ019","questions":["徽派建筑粉墙元素在现代建筑中如何被演绎？有哪些关键词？","新徽派建筑怎么使用粉墙？","现代设计中如何提取粉墙元素？","粉墙的抽象和简化手法常见吗？"],"keywords":["模块二","粉墙","现代设计"],"answer":"根据关键词统计，现代建筑对粉墙的演绎主要体现在“抽象”（出现6次）、“简化”（5次）、“创新”（4次）等设计手法上。新徽派建筑通过提炼粉墙的白色质感、马头墙轮廓、门罩比例等符号，将其转化为现代建筑语汇，如使用白色涂料、简化马头墙造型、采用抽象的门罩线条等，既保留地域特征又满足当代功能需求。"},{"id":"m2-fq-WQ020","questions":["徽州传统民居中，外墙和屋顶的防热策略效果排序是怎样的？","反射和外遮阳哪个防热效果更好？","屋顶的哪种防热方式最有效？","蓄热和对流换热的贡献大吗？"],"keywords":["模块二","粉墙","防热策略","防热"],"answer":"根据黄志甲等的研究，外墙防热策略效果从高到低排序为：反射（贡献率18.6%）>外遮阳（14.1%）>蓄热（12.3%）>对流换热（2.9%）>长波辐射（0.8%）。屋顶防热策略效果排序为：反射（21.3%）>蓄热（9.9%）>对流换热（7.3%）>长波辐射（1.2%）。反射是外墙和屋顶最有效的被动式防热策略。"},{"id":"m2-fq-WQ021","questions":["有哪些新型保温材料可以用于徽州传统民居的节能改造？其导热系数是多少？","植物纤维材料能用于墙体保温吗？","新型碱矿渣胶凝材料的热工性能如何？","挤塑聚苯板的导热系数是多少？"],"keywords":["模块二","粉墙","材料创新","传热"],"answer":"可用于传统民居改造的新型保温材料包括：挤塑聚苯板XPS（导热系数0.03 W/m·K）、模塑聚苯板EPS（0.042）、植物纤维增强碱矿渣胶凝材料（实验室测试导热系数0.136 W/m·K，墙体热阻0.408 m²·K/W，传热系数1.792 W/m²·K）、硅酸铝复合保温涂料（13mm厚可使墙体传热系数降至0.92 W/m²·K）、聚苯颗粒保温浆料（35mm厚传热系数0.87）、膨胀玻化微珠保温砂浆（42mm厚传热系数0.85）。这些材料可填充空斗墙夹层或外抹于墙体。"},{"id":"m2-fq-WQ022","questions":["不同类型的门罩反映了怎样的等级秩序和文化内涵？","门罩大小和屋主身份有关吗？","牌楼式门楼为什么罕见？","门罩上的砖雕题材有哪些寓意？"],"keywords":["模块二","粉墙","门罩文化"],"answer":"门罩类型与建筑等级直接相关：门楣式门罩构造简单，用于普通民居，反映朴素内敛的审美；垂花门式门罩形式舒展，用于一般商贾住宅，体现优雅流畅的风格；牌楼式（八字）门楼规模宏大，用于有殊荣的民居或官员宅第，边柱/门洞比精确控制在0.967，象征家族荣耀和社会地位。门罩砖雕题材常包含“恩荣”“忠孝节义”“福禄寿”等，既是装饰，也是儒家伦理和功名追求的物化表达。"},{"id":"m2-fq-WQ023","questions":["徽派建筑粉墙系统的整体性能指标有哪些？","粉墙系统的传热系数范围是多少？","天井通风能改善多少？","冬季室内温度大概多少？"],"keywords":["模块二","粉墙","综合性能","传热"],"answer":"徽派建筑粉墙系统的关键性能指标汇总如下：墙体传热系数1.17-2.47 W/m²·K，传统空斗墙最优1.17-1.231；天井换气次数夏季7.2-36次/h（回字型提升400%），冬季5.8-9.4次/h；冬季室内温度2.9-7.2℃，平均约5.0℃；冬季相对湿度约56%；外墙夏季表面温度>45℃，冬季<5℃。整体而言，粉墙系统在保温隔热方面具有科学智慧，但冬季热舒适度仍需改善。"},{"id":"m2-fq-WQ024","questions":["本次粉墙研究的主要数据来源有哪些？","引用了哪些论文和报告？","热工性能数据来自哪里？","门罩尺寸数据是哪篇论文的？"],"keywords":["模块二","粉墙","数据来源","防热","传热"],"answer":"主要数据来源包括：1）郑彬、傅秀章（2012）《徽州民居主要砌体外墙热工性能测试与分析》——四种墙体传热系数实测数据；2）黄志甲等（2019）《徽州传统民居中被动式防热设计效果分析》——防热贡献率数据；3）余梦琦（2018）《徽州传统民居室内热环境形成机理研究》——围护结构构造参数；4）张岚元等（2018）《徽州传统民居建筑门罩装饰构件的审美意义研究》——门罩尺寸和比例数据；5）袁玉华（2014）《徽州村镇住宅外围护结构节能设计研究》——墙体演变和热工测试；6）模块二数据收集（量化）——天井尺寸和通风得分；7）魏国锋等（2013）——传统灰浆材料研究。此外还有25篇期刊论文用于关键词提取。"},{"id":"m2-tj-M2Q101","questions":["在这个系统中，天井·性能评估气泡图横轴与纵轴分别代表什么？","天井部分气泡图的X轴和Y轴分别度量了天井的什么特征？","天井部分性能评估图中，横坐标和纵坐标对应的物理量是什么？","天井气泡图里，横轴是天井尺寸，纵轴代表什么？","从气泡图的坐标看，如何判断某个天井的通风面积和性能？"],"keywords":["模块二","天井","天井构件","气泡图"],"answer":"在【模块二天井部分】左上角的“天井·性能评估气泡图”中，横轴代表“天井尺寸”（数值约为10-22），纵轴代表“和风区占比 (%)”（数值范围从40%到约80%）。横轴数值越大代表天井的面积或开间越大，纵轴数值越高则代表该天井能够有效利用自然风的区域比例越大。"},{"id":"m2-tj-M2Q102","questions":["天井部分，系统中编号为WJ36的天井性能如何？","气泡图最右侧的那个天井（WJ36）有什么特征？","系统内尺寸最大的天井WJ36，它的和风区占比是多少？","看天井气泡图，WJ36大概处于什么位置？","WJ36这个编号对应的天井，在性能评估图中表现如何？"],"keywords":["模块二","天井","天井构件","气泡图"],"answer":"在【模块二天井部分】左上角的气泡图中，编号为WJ36的天井位于整个气泡群的最右侧和偏上位置。其天井尺寸约在22左右（最大），对应的和风区占比高达约70%-75%。这在系统中被认为是通风性能较好的大型天井代表。"},{"id":"m2-tj-M2Q103","questions":["天井部分中，气泡图中，处于左下方（和风区占比较低）的天井编号主要是什么？","天井部分中，性能评估图左下角，数值表现最差的天井是哪个？","哪个编号的天井对应的和风区占比最低？","系统中通风效果相对较弱的天井主要有哪些代号？","在气泡图里，和风区占比低于50%的天井是哪个？"],"keywords":["模块二","天井","天井构件","气泡图"],"answer":"在【模块二天井部分】左上角的气泡图中，位于左下方区域的天井编号包括WJ11、WJ21和WJ22等。它们的和风区占比在40%-50%之间，对应的天井尺寸也相对较小，通常在10-15之间。这表明这些天井在利用自然通风方面能力较弱。"},{"id":"m2-tj-M2Q104","questions":["天井部分的气泡图中，气泡的面积大小可能隐含了天井的哪个指标？","天井部分，在性能评估图中，气泡的半径或面积通常与什么正相关？","除了坐标位置，气泡的大小反映了天井的哪方面数据？","不同大小的气泡在天井评估中代表了什么？","WJ41和WJ31气泡大小差异，可能体现了什么不同？"],"keywords":["模块二","天井","天井构件","气泡图"],"answer":"在【模块二天井部分】左上角的气泡图中，气泡的面积大小通常代表了该天井的综合性能评价指标，比如“热舒适度”或“综合通风效率”。数值较大、位置靠右上的气泡（如WJ36）通常面积较大，代表其在系统评估中获得了更优的综合性能得分。"},{"id":"m2-tj-M2Q105","questions":["天井的尺寸大小与“和风区占比”呈现出怎样的关系趋势？","天井模块中，从气泡图的整体分布来看，天井越大，和风区占比越高还是越低？","天井模块中，横轴尺寸增加时，纵轴的风区百分比一般呈现什么趋势？","图表显示，天井大小与通风效率之间是否存在正相关？","天井模块中，结合坐标轴，天井尺寸和性能之间的大致规律是什么？"],"keywords":["模块二","天井","天井构件","图表","气泡图"],"answer":"在【模块二天井部分】左上角的气泡图中，天井尺寸（横轴）与和风区占比（纵轴）总体呈现出正相关的趋势。即随着天井尺寸的增大，其能够有效利用自然风的和风区占比通常会随之上升（气泡整体向右上方倾斜分布），但也会受具体建筑形态和开口位置的制约（如WJ34等某些特例）。"},{"id":"m2-tj-M2Q106","questions":["在“形成逻辑关系图”中，天井的主要形式（如四字型、回字型、H型等）是由什么因素决定的？","逻辑图中，最右侧的那些天井形态（四字型、一字型等）归类于哪个层级之下？","决定天井采取四字型还是L型的具体因素属于图中的哪个分支？","天井的具体平面形态（如一字型）主要受哪些条件约束？","逻辑关系图中，天井形式最终是受到了哪些大类因素的共同作用？"],"keywords":["模块二","天井","天井构件","关系图"],"answer":"在【模块二天井部分】右上角的“天井·形成逻辑关系图”中，最右侧的“四字型”、“回字型”、“H字型”、“L字型”、“一字型”等具体天井形式，直接指向并受左侧四类宏观因素的共同作用：自然环境（气候、地形）、生活需求（采光、通风、社交）、建筑技术（材料、结构）以及地域文化（风水观念、哲学思想）。"},{"id":"m2-tj-M2Q107","questions":["天井模块中，“排水明沟”和“蓄水缸”在逻辑关系图中与哪个因素相关联？","图中，排水系统的部件如明沟、蓄水缸主要对应什么需求？","在形成逻辑图中，排水明沟和蓄水缸是为了满足什么条件而设置的？","天井的排水设施（明沟、蓄水缸）是源于哪类因素的驱动？","逻辑图中，与“排水需求”相关的天井设施有哪些？"],"keywords":["模块二","天井","天井构件","关系图"],"answer":"在【模块二天井部分】右上角的逻辑关系图中，“排水明沟”和“蓄水缸”位于最右侧的构件节点，它们直接受左侧的“生活需求”大类中的“排水需求”所驱动。在南方多雨地区，天井不仅要快速导水，还需要蓄水以备消防和绿化利用，体现了对自然水资源的循环管理。"},{"id":"m2-tj-M2Q108","questions":["“镂空花窗”和“挑檐遮阳”在设计上主要解决什么问题？","天井周围常见的镂空花窗和挑檐主要起到了什么功能？","天井模块中，逻辑图中，“镂空花窗”和“挑檐遮阳”的线条指向了哪个需求节点？","为了在夏季实现隔热并兼顾通风，天井通常会设置哪些构件？","天井中的花窗和挑檐主要为了满足什么生活需求？"],"keywords":["模块二","天井","天井构件"],"answer":"在【模块二天井部分】右上角的逻辑关系中，“镂空花窗”和“挑檐遮阳”位于右侧构件列表，它们的逻辑链路主要连接到了左侧“生活需求”大类下的“通风需求”和“采光需求”，同时也受到“地域文化”下“风水观念”的间接影响。它们通过精妙的角度设计，实现遮阳避雨的同时又保证了室内采光和气流交换。"},{"id":"m2-tj-M2Q109","questions":["天井模块中，“木构隔扇”和“青石铺地”在逻辑系统中如何分类？","在逻辑关系图中，木构隔扇和青石铺地对应的是哪个大类？","材质选择上，天井使用木隔扇和青石铺地主要属于哪类驱动因素？","天井模块中，图中“木构隔扇”属于哪个层级或大类之下？","青石铺地和木构隔扇作为天井组成部分，主要受什么因素影响？"],"keywords":["模块二","天井","天井构件","关系图"],"answer":"在【模块二天井部分】右上角的逻辑关系图中，“木构隔扇”和“青石铺地”位于最右侧的详细构件节点，它们直接受左侧“建筑技术”大类下的“材料特性”节点所控制。木构隔扇代表了传统的构筑技艺，而青石铺地则因其耐久性和防滑性能在南方天井中被广泛采用。"},{"id":"m2-tj-M2Q110","questions":["天井模块中，“坡顶内向”这种建筑形态在逻辑关系图中对应什么？","天井的“坡顶内向”设计在逻辑图中与哪个因素相连？","坡顶内向具体是为了配合什么需求而设计的？","在形成逻辑图中，坡顶内向的驱动来源是什么？","天井的坡顶为什么倾向于内向（向天井中心倾斜）？"],"keywords":["模块二","天井","天井构件","关系图","四水归堂"],"answer":"在【模块二天井部分】右上角的逻辑关系图中，“坡顶内向”作为天井的经典形态特征，直接连接到了“地域文化”大类下的“哲学思想”和“风水观念”节点。这种设计不仅是为了快速汇集雨水并排走（对应排水需求），在文化寓意上更象征着“四水归堂”的聚财心理，体现了徽商等群体在建筑中融入的精神寄托。"},{"id":"m2-tj-M2Q111","questions":["天井·关键词词云图中，最核心的几个关键词是什么？","天井模块中，词云里字号最大、最醒目的词语有哪些？","在系统语义分析中，天井最突出的3-4个关键词是什么？","词云图中，代表天井核心理念和功能的大字分别是哪些？","天井的主要关键词包括哪几个方面的描述？"],"keywords":["模块二","天井","天井构件","四水归堂"],"answer":"在【模块二天井部分】左下角的“天井·关键词词云图”中，字号最大、位于中心区域的核心关键词包括：“四水归堂”、“天人合一”、“采光”、“通风”以及“聚财”。这些词最直观地概括了天井在中国传统建筑中的功能属性和文化价值。"},{"id":"m2-tj-M2Q112","questions":["词云中“四水归堂”和“肥水不流外人田”表达了天井的什么文化内涵？","“四水归堂”在天井文化中代表了什么寓意？","词云里“肥水不流外人田”表达了古代商人怎样的心态？","天井汇集雨水的做法，在词云中对应的文化关键词是什么？","“四水归堂”和“聚财”在概念上有何联系？"],"keywords":["模块二","天井","天井构件","四水归堂"],"answer":"在【模块二天井部分】左下角的词云图中，“四水归堂”和“肥水不流外人田”两个词紧密相连，它们共同表达了天井的“聚财”文化内涵。在传统风水观念和徽商文化中，雨水被认为是“财富”的象征，天井将四周屋面的雨水汇入自家院中，寓意汇聚家族财富，防止财气外流。"},{"id":"m2-tj-M2Q113","questions":["天井模块中，词云中提到了哪些用于改善天井微气候的物理原理？","在天井的关键词里，哪些词描述了改善热环境的物理现象？","“烟囱效应”和“热压通风”指的是天井的什么功能？","天井模块中，词云中除了通风和采光，还有哪些热环境调节术语？","从词云看，天井利用了哪些物理规律来调节气候？"],"keywords":["模块二","天井","天井构件","热环境"],"answer":"在【模块二天井部分】左下角的词云图中，明确列出了“烟囱效应”和“热压通风”这两个重要的物理名词。它们描述了天井利用高度差和温差，驱动气流向上运动从而实现自然通风的原理，这是天井调节室内微气候的关键物理机制。"},{"id":"m2-tj-M2Q114","questions":["天井模块中，词云中提到了天井周围常见的哪些装饰工艺？","天井相关的关键词里，提到了哪几种传统的雕刻艺术？","天井模块中，哪些代表传统建筑装饰的词汇出现在了词云中？","词云中的“木雕”、“砖雕”、“石雕”属于什么类别的工艺？","天井中常见的雕刻装饰在系统中被归纳为哪三个词？"],"keywords":["模块二","天井","天井构件"],"answer":"在【模块二天井部分】左下角的词云图中，中下部区域集中列出了“木雕”、“砖雕”、“石雕”三个词。这表明天井不仅是功能性的空间，也是徽派建筑中展示精湛雕刻工艺的核心场所，木雕常见于窗扇和隔扇，砖雕多见于墙面和门罩，石雕则见于柱础和地坪。"},{"id":"m2-tj-M2Q115","questions":["“蓄水池”和“马头墙”在天井词云中分别代表了什么防护功能？","从词云看，天井是如何实现防火功能的？","“蓄水池”和“马头墙”在天井中的主要功能是保护什么？","天井中，用于消防蓄水的和用于阻隔火势的结构分别是什么？","词云中，哪两个词对应了天井的消防系统？"],"keywords":["模块二","天井","天井构件"],"answer":"在【模块二天井部分】左下角的词云图中，“蓄水池”和“马头墙”是代表天井“防火”功能的关键词。马头墙作为高出屋面的墙体，在火灾发生时能有效阻断火焰横向蔓延（封火）；而天井内的蓄水池或水缸则提供了近距离的消防水源。"},{"id":"m2-tj-M2Q116","questions":["在冬季热环境影响分析图中，天井的冬季平均气温大约是多少？","右下角图表显示，天井在冬季的最低和最高温度区间大致为多少？","天井·冬季热环境影响分析折线图中，天井对应的温度数值是多少？","从冬季热环境分析图看，天井的室内温度水平大概处于什么范围？","图表中天井节点纵轴（温度）对应的具体数值是多少？"],"keywords":["模块二","天井","天井构件","图表","热环境"],"answer":"在【模块二天井部分】右下角的“天井·冬季热环境影响分析”图中，通过查看温度和湿度的折线图，天井（横轴：天井）对应的温度曲线读数大约在12.0℃至13.0℃之间（最高温度约12.8℃，最低温度约12.2℃）。这表明在冬季，天井作为室内外交接空间，其温度相对温和，高于室外入口但略低于厅房。"},{"id":"m2-tj-M2Q117","questions":["天井的冬季湿度与厅房相比如何？","从环境分析图看，天井和厅房的湿度数据对比是怎样的？","在冬季热环境分析中，天井处的湿度（%）是否比厅房高？","天井空间的冬季相对湿度值大约在哪个区间？","通过图表的湿度曲线，天井与厅房的湿度差约为多少？"],"keywords":["模块二","天井","天井构件","图表","热环境"],"answer":"在【模块二天井部分】右下角的图表中，湿度曲线显示天井（横轴：天井）的冬季湿度值大约在80%-82%左右，而厅房（横轴：厅房）的湿度值则下降到约72%。因此天井的湿度显著高于厅房，这主要是因为天井直接受到外界空气和雨雪的影响，且缺乏封闭的供暖系统。"},{"id":"m2-tj-M2Q118","questions":["通过冬季热环境分析图，天井中的平均风速是多少？","图表的平均风速（线形图）中，天井节点的数值是多少？","冬季天井空间的空气流动速度大约处于什么水平？","从环境分析图看，天井的平均风速是否高于厅房？具体数值？","横轴“天井”对应的风速数据读数为多少（m/s）？"],"keywords":["模块二","天井","天井构件","图表","热环境"],"answer":"在【模块二天井部分】右下角的分析图中，通过查看实线表示的“平均风速”曲线，天井（横轴：天井）对应的风速数值约为0.25 - 0.30 m/s。这个数值明显低于入口和庭院（约为1.0-1.2 m/s），但高于厅房的约0.2 m/s，说明天井起到了一定的风压缓冲作用。"},{"id":"m2-tj-M2Q119","questions":["天井模块中，图中冬季热环境分析的横坐标列出了哪几个空间节点？","右下角环境分析图里，从入口到厅房经过的横向空间序列是什么？","图表横轴从左到右依次排列了哪四个主要建筑位置？","系统进行气候分析时，评估了哪几个具体位置的热环境？","在冬季热环境分析图中，空间路径的顺序是什么？"],"keywords":["模块二","天井","天井构件","图表","热环境"],"answer":"在【模块二天井部分】右下角的冬季热环境影响分析图中，横坐标从左到右依次列出了五个空间节点：入口 → 庭院 → 天井 → 门厅 → 厅房。这一序列展示了一条完整的从外到内、从开放到私密的传统徽派建筑空间递进路径。"},{"id":"m2-tj-M2Q120","questions":["天井模块中，从入口到厅房，温度和风速呈现怎样的总体变化趋势？","随着从入口深入天井再到厅房，温度和风速是如何变化的？","冬季热环境分析图中，温度曲线的走向是怎样的？","从外到内，天井和厅房的微气候在温度和风速上有何改善？","图表显示，整个空间序列的温度和风环境变化趋势是什么？"],"keywords":["模块二","天井","天井构件","图表","热环境"],"answer":"在【模块二天井部分】右下角的分析图中，总体呈现出以下趋势：温度从入口的低点（约4-5℃）逐渐上升，经过庭院、天井的缓冲，最终在“厅房”达到最高点（约15℃左右）。风速则呈现先升高后降低的波浪形变化：入口和庭院风速较高（约1.1-1.2 m/s），到达天井后降为约0.25 m/s起到缓冲，最终厅房内保持在无风或微风的舒适状态（约0.2 m/s）。这体现了天井作为“气候过滤器”的作用。"},{"id":"m2-tj-M2Q121","questions":["什么是“烟囱效应”？它如何在天井中实现？","天井的通风是如何利用“烟囱效应”的？","“烟囱效应”的原理在天井建筑中具体如何体现？","词云中的“烟囱效应”指的是天井内的什么物理过程？","天井依靠什么物理原理来促进空气流动和换气？"],"keywords":["模块二","天井","天井构件"],"answer":"在【模块二天井部分】左下角的词云图中明确提到了“烟囱效应”。它是天井实现自然通风的核心机制，利用天井本身作为一个竖向高差，在吸收太阳辐射后，天井上部空气温度升高并膨胀上升（如同烟囱），从而在天井底部形成负压区，吸引周围房间的冷空气流入补充，形成持续的气流循环，达到降温换气的目的。"},{"id":"m2-tj-M2Q122","questions":["天井在风水上被称为“四水归堂”，这背后的实际功能优势是什么？","“四水归堂”除了寓意好，在建筑实用上有什么好处？","天井汇集屋面雨水的做法，在实际生活中解决了什么问题？","从功能角度看，“四水归堂”是如何利用水资源的？","“四水归堂”的物理实现，对室内排水和用水有什么影响？"],"keywords":["模块二","天井","天井构件","四水归堂"],"answer":"在【模块二天井部分】左下角的词云图中，“四水归堂”是代表天井文化理念的核心词。在建筑物理层面，它将四周屋面的雨水统一汇入天井的排水明沟和蓄水池中。这种设计不仅集中并快速排放了暴雨时的积水量，保护了墙体基础，同时收集到的雨水可用于日常生活洗涤、浇灌植物以及近距离的消防应急，实现了水资源的高效循环利用。"},{"id":"m2-tj-M2Q123","questions":["天井中“木雕”和“石雕”通常出现在哪些具体位置？","在天井空间中，木雕多见于什么建筑部件上？","石雕在天井的设计中通常设置在哪些地方？","词云里提到的木雕、石雕，对应天井的哪些局部构件？","天井周围的哪些结构是展示雕刻艺术的主要载体？"],"keywords":["模块二","天井","天井构件"],"answer":"在【模块二天井部分】左下角的词云图中，“木雕”和“石雕”被明确列出。根据传统建筑常识，木雕主要出现在天井周围的隔扇门窗、雀替、挂落、梁架和花窗上，体现精细手工；石雕则多分布于柱础（防潮）、门罩、地坪和栏杆等承重或耐磨损部位。两者共同构成了天井丰富的视觉层次和文化底蕴。"},{"id":"m2-tj-M2Q124","questions":["天井是如何实现“节能”的？","词云中提到的“节能”在天井设计中具体如何达成？","传统天井设计在减少能源消耗方面有哪些巧思？","天井通过什么方式减少了对人工照明和空调的依赖？","天井的哪些设计原理使得它具备节能特性？"],"keywords":["模块二","天井","天井构件"],"answer":"在【模块二天井部分】左下角的词云图中，“节能”二字与其他核心功能词并列。天井的节能主要体现为：一是通过采光设计，利用漫反射光为室内提供充足的天然照明，减少白天的照明能耗；二是利用通风和热压通风原理，在夏季和过渡季节有效带走室内热气和潮气，实现自然降温，显著降低空调的使用频率。"},{"id":"m2-tj-M2Q125","questions":["不同形式的天井（如四字型、H型、一字型）在设计逻辑上有何区别？","在形成逻辑图中，“四字型”和“一字型”的天井主要区别是什么？","从逻辑关系图看，不同平面形状的天井可能对应哪些不同的需求？","四字型、H字型和一字型天井在空间体验和功能上可能有哪些差异？","系统的逻辑图里，天井平面的多样性是由什么决定的？"],"keywords":["模块二","天井","天井构件","关系图"],"answer":"在【模块二天井部分】右上角的逻辑关系图最右侧，列举了“四字型”、“回字型”、“H字型”、“L字型”、“一字型”等多种天井形式。它们的区别主要源于左侧“生活需求”的细微不同：例如，四字型/回字型通常对应完整的围合感和较高的采光、社交需求；而一字型或L型则多见于地形受限或辅助空间，主要满足基础的通风和采光。在地域文化和风水观念的驱动下，围合度更高的天井往往等级更高、更受重视。"},{"id":"m2-tj-M2Q126","questions":["从系统综合来看，天井在建筑中的核心角色是什么？","综合统计和逻辑图来看，天井最主要的功能定位是什么？","天井在传统徽派建筑中承担了哪些关键职责？","系统通过不同板块展示，天井从根本上发挥什么作用？","从功能和文化两个层面，天井扮演了什么核心角色？"],"keywords":["模块二","天井","天井构件","四水归堂"],"answer":"综合【模块二天井部分】全部四个板块可见，天井的核心角色是多功能的气候调节器和文化精神载体。在物理功能上，它实现了采光、通风、排水、防火和隔热；在物理现象上，它利用了热压通风和烟囱效应；在文化内涵上，它集中体现了天人合一的哲学理念和四水归堂、聚财的社会价值追求。它是传统建筑解决“室内/室外”气候过渡的核心枢纽。"},{"id":"m2-tj-M2Q127","questions":["天井模块中，系统逻辑图中提到的“建筑技术”对天井具体产生了什么影响？","天井模块，在形成逻辑图中，“建筑技术”分支影响了天井的哪些方面？","材料特性和结构体系如何决定天井的形式？","天井的建造技术节点（材料、结构）带来了什么样的天井特征？","从“建筑技术”看，天井的形成有哪些工程约束？"],"keywords":["模块二","天井","天井构件"],"answer":"在【模块二天井部分】右上角的逻辑图中，“建筑技术”大类向下分出了“材料特性”和“结构体系”。这决定了天井的建造方式：例如，材料特性决定了使用青石铺地、木构隔扇，保证了耐久和氛围；结构体系则决定了天井周围的梁柱排列和挑檐深度，从而影响着天井的实际空间尺寸和遮阳效果。技术层面的实现直接支撑了功能需求的达成。"},{"id":"m2-tj-M2Q128","questions":["天井除了物理调节功能，在徽商文化中扮演了什么角色？","从词云和逻辑图中看，天井在徽商家族中有什么象征意义？","在徽商文化背景下，天井主要承载了哪些精神内涵？","除了住人，天井在徽商建筑中还具备什么文化作用？","天井的“聚财”和“防火”功能，在徽商宅院里有着什么双重含义？"],"keywords":["模块二","天井","天井构件","四水归堂"],"answer":"在【模块二天井部分】的整个系统中，“徽商”作为明确的关键词出现在左下角词云和右上角逻辑图中。在徽商文化中，天井扮演了财富和家族兴旺的象征与凝聚物角色。一方面，通过“四水归堂”寓意聚财；另一方面，“肥水不流外人田”代表了徽商务实、守财的价值观，同时天井的“采光”和“通风”也体现了徽商注重生活品质和家族成员健康的理念。"},{"id":"m2-tj-M2Q129","questions":["如果在徽派建筑改造中，想要提高天井的冬季热舒适度，应该从哪些方面入手？","基于冬季热环境影响分析图，如何优化天井的冬季性能？","从数据的角度来看，哪些参数可以改善天井冬季的温度和湿度？","如果想减少天井对厅房的热损失，应该在逻辑图哪些节点上做文章？","系统提供的信息中，有哪些策略可以提升天井冬季的使用感受？"],"keywords":["模块二","天井","天井构件","关系图","热环境"],"answer":"基于【模块二天井部分】右下角的冬季热环境分析图，以及右上角的逻辑关系图，提高天井冬季热舒适度的策略包括：1）在建筑技术层面，增加可调节的活动格栅或天井顶部玻璃天窗，减少冬季冷风灌入。2）在结构体系节点，适当调整天井尺寸（控制横轴尺寸不宜过大）和围护结构（增设轻质围护），以减少热损失。3）在排水节点，保持地面干燥，减少因蓄水池/明沟带来的额外湿度扩散。4）在地域文化不冲突的前提下，引入空气源热泵或保温密封措施来辅助供暖。"},{"id":"m2-tj-M2Q130","questions":["这套关于天井的系统，其核心价值是什么？","综合所有面板内容，这个系统主要解决什么问题？","这套“模块二天井部分”的界面能为用户提供什么帮助？","从数据可视化到文化分析，系统对天井的全面分析旨在达到什么目的？","简述这套天井数据分析系统的最终意义。"],"keywords":["模块二","天井","天井构件","四水归堂"],"answer":"这套“模块二天井部分”的系统，其核心价值在于实现了传统天井从“感性文化”到“理性数据”的跨学科贯通。它通过左上角量化天井的性能表现、右上角梳理形成逻辑、左下角提炼核心关键词、右下角展示实测环境数据，将天井的物理功能（通风、采光、排水）、环境热物理机制（热压、烟囱效应）和文化内涵（四水归堂、天人合一）有机整合。对于现代建筑设计师、历史保护工作者和建筑热物理研究人员，它提供了一个数字化、可视化、多维度的传统建筑智慧查询与教学平台。"},{"id":"m3-qa-M3Q001","questions":["《营造法式》是什么书？与徽州建筑有什么关系？","《营造法式》的作者是谁？","李诫的《营造法式》记录了徽州建筑的哪些做法？","宋代《营造法式》对徽州建筑有影响吗？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","营造法式","李诫"],"answer":"《营造法式》是北宋李诫编纂的官方建筑技术标准，是中国古代建筑史上最重要的营造典籍之一。书中详细记录了“梭柱”“月梁”“上昂铺作”等做法，而这些做法在徽州古建筑中大量保留，因此《营造法式》成为解读徽州建筑形制与技术的核心文献。"},{"id":"m3-qa-M3Q002","questions":["《新安志》是谁编纂的？对徽州建筑研究有什么价值？","罗愿的《新安志》记载了什么？","南宋《新安志》为什么重要？","《新安志》为徽州建筑提供了哪些信息？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","新安志"],"answer":"《新安志》是南宋罗愿编纂的徽州第一部方志，系统汇总了徽州（新安）的山川、城池、祠庙、古迹等信息。它为后世研究徽州古建筑的选址、村落布局以及历史地理背景提供了开创性的第一手资料，是徽州建筑研究不可或缺的历史地理依据。"},{"id":"m3-qa-M3Q003","questions":["《鲁班经》在徽州建筑中扮演什么角色？","《鲁班经》是民间流传的什么书？","徽州工匠为什么重视《鲁班经》？","《鲁班经》对徽派建筑营造有什么影响？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","鲁班经"],"answer":"《鲁班经》是一部明代民间流传的工匠口诀与营造规范经典。它在徽州地区被本地工匠广泛吸收、口传心授，成为解读徽派建筑营造尺度、结构做法以及风水禁忌的“钥匙”。许多徽州民居、祠堂的尺寸比例都能在《鲁班经》中找到依据。"},{"id":"m3-qa-M3Q004","questions":["何歆是谁？他对徽派建筑有什么贡献？","马头墙是谁发明的？","何歆与封火墙有什么关系？","明代何歆提出了什么防火策略？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","何歆","马头墙"],"answer":"何歆是明代徽州的一位官员，被公认为徽派建筑马头墙（封火墙）的发明者和推广者。他在任期间多次亲临火灾现场，发现高墙能有效阻挡火势，提出了“降灾在天，防患在人，治墙其上策”的著名论断。弘治十六年，他以政令推行“五家为伍，壁以高垣”，即每五户为一组，让出墙基三尺，共建高出屋面的砖墙以隔断火源，从而解决了木结构建筑“火烧连营”的难题。"},{"id":"m3-qa-M3Q005","questions":["程大位的《算法统宗》与徽州建筑有什么关系？","珠算大师程大位与建筑有关吗？","《算法统宗》被徽州匠师用来做什么？","程大位的数学著作影响了徽州建筑的哪个方面？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","程大位"],"answer":"程大位（1533-1606）是徽州屯溪人，明代著名珠算学家。他的《算法统宗》虽然是一部数学著作，但在当时被广泛应用于工程计量、土地丈量和商业计算。徽州建筑的匠师们使用书中的计算方法进行结构受力估算、材料用量计算以及工程成本控制，因此它成为徽派建筑营造中不可或缺的工具书。"},{"id":"m3-qa-M3Q006","questions":["什么是“徽州帮”匠师集团？他们有什么历史地位？","徽州帮包括哪些工匠？","明清时期徽州建筑风格是谁定型的？","徽州帮匠师对江南建筑有什么影响？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","三雕","徽州帮","马头墙"],"answer":"“徽州帮”是明代中期至清代中期，随着徽商崛起而形成的一个以砖、木、石、铁、窑五种工匠为核心的建筑匠师集团。他们不仅在徽州本地建造了大量精美建筑，还随徽商足迹活跃于江南地区，成为马头墙、天井、三雕等徽派建筑风格的实践者和定型者。徽州帮的技艺与组织形式深刻影响了明清江南地区的建筑风貌。"},{"id":"m3-qa-M3Q007","questions":["《徽州府志》有哪些重要版本？各自记载了哪些建筑信息？","弘治《徽州府志》是谁编纂的？","康熙《徽州府志》有什么特点？","道光《徽州府志》为什么重要？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","徽州府志"],"answer":"《徽州府志》有多个重要版本：弘治十五年（1502年）汪舜民纂修的版本，卷七《营建志》详细记载了府学等官方建筑的历代迁建与规制；嘉靖四十五年（1566年）汪尚宁等纂修的版本，对城池、街市、水利及重要建筑有更详细的补充；康熙三十八年（1699年）赵吉士纂修的版本，汇总并订正前代营建信息，是研究清初徽州建筑的重要文献；道光七年（1827年）夏銮纂修的版本，集大成，对徽州境内建筑进行了最系统的梳理。"},{"id":"m3-qa-M3Q008","questions":["徽州木雕的题材主要分为哪几类？","木雕上通常刻什么内容？","徽州木雕有哪些主题？","儒学文化在木雕中如何体现？"],"keywords":["模块三","匠艺流芳","三雕题材与部位","木雕"],"answer":"徽州木雕的题材主要分为七类：一是儒学文化类，以程朱理学、忠孝节义为核心，如“二十四孝”；二是祥禽瑞兽类，如龙、凤、蝙蝠、麒麟，象征吉祥福禄；三是历史典故与戏文类，如“三顾茅庐”“郭子仪上寿”；四是花鸟鱼虫类，如“喜鹊登梅”；五是博古器物类，如炉、鼎、文房四宝；六是民俗生活类，如“渔樵耕读”“百子闹元宵”；七是几何纹路类，如回字纹、卷草纹、万字纹。"},{"id":"m3-qa-M3Q009","questions":["徽州木雕主要分布在建筑的哪些部位？","木雕一般刻在房子的什么地方？","哪些构件上能看到精美的木雕？","木雕最密集的区域是哪里？"],"keywords":["模块三","匠艺流芳","三雕题材与部位","木雕"],"answer":"徽州木雕主要分布在五大部位：一是梁架构件（梁、枋、瓜柱等），以深浮雕、透雕为主，题材多为历史典故；二是支撑与过渡构件（雀替、牛腿、斗拱、叉手等），透雕与圆雕并用，题材以博古器物、几何纹为主；三是门窗与隔断构件（隔扇、莲花门、栏板等），木雕最密集，镂空雕与浮雕结合；四是厅堂与室内装修构件（板壁、屏风、花板），体现“外素内华”；五是柱础与门柱构件，以浅浮雕辅助点缀。"},{"id":"m3-qa-M3Q010","questions":["徽州砖雕的题材有哪些？","砖雕上一般刻什么？","徽州砖雕喜欢用哪些图案？","砖雕中的人物题材包括什么？"],"keywords":["模块三","匠艺流芳","三雕题材与部位","砖雕"],"answer":"徽州砖雕的题材分为五大类：人物相关——神话故事、戏剧人物、历史名人轶事、民俗生活场景以及忠孝节义等伦理形象；动物相关——祥禽瑞兽（麒麟、凤凰、龙、狮子）和日常飞禽走兽（蝙蝠、鱼、鹤），多承载吉祥寓意；植物相关——梅兰竹菊、莲花、牡丹、松竹以及石榴、葡萄等瓜果；吉祥寓意——双龙抢珠、五福捧寿、年年有余等谐音图案；山水建筑——园林山水、楼台亭阁、城池景观，多与人物场景结合。"},{"id":"m3-qa-M3Q011","questions":["徽州砖雕主要雕刻在哪些部位？","砖雕一般出现在建筑的什么位置？","门楼上的砖雕包括哪些构件？","窗户上也有砖雕吗？"],"keywords":["模块三","匠艺流芳","三雕题材与部位","砖雕"],"answer":"徽州砖雕主要分布在五大系统：门楼系统——包括门楼整体、额枋、斗拱、匾额周边、雀替、挂落，是砖雕最集中、最精美的部位；门部系统——门罩、门楣、门框、八字墙、垂花门装饰；窗部系统——窗楣、镂窗、漏窗边框及主体纹饰；屋檐屋顶系统——檐口、屋脊、檐角鳌鱼装饰、屋瓴；墙体系统——照壁、墙面空白处点缀、神龛周边，以及柱础、连表牌坊、梁托、回廊栏板等零散构件。"},{"id":"m3-qa-M3Q012","questions":["徽州石雕的题材分为哪几类？","石雕上通常刻什么内容？","石雕与木雕题材有什么不同？","石雕中儒家伦理题材有哪些？"],"keywords":["模块三","匠艺流芳","三雕题材与部位","木雕","石雕"],"answer":"徽州石雕的题材分为五大类：儒家伦理题材——以忠孝节义为核心，如《二十四孝》《郭子仪拜寿》以及“五子登科”等；宗族文化题材——宗族祖先事迹、族规家训图案；吉祥寓意题材——牡丹（富贵）、松竹梅（岁寒三友）、龙凤、蝙蝠、鹿、如意、宝瓶等；乡土生活题材——《渔樵耕读》《百子图》以及新安山水、劳作休憩场景；宗教文化题材——佛教莲花、佛像，道教“暗八仙”（葫芦、宝剑等法器）、祥云等。"},{"id":"m3-qa-M3Q013","questions":["徽州石雕主要雕刻在哪些部位？","石雕常见于建筑的什么地方？","牌坊上的石雕包括哪些部分？","柱础上也有石雕吗？"],"keywords":["模块三","匠艺流芳","三雕题材与部位","石雕"],"answer":"徽州石雕主要分布在六大部位：墙面部分——台基、墙基、转角石；窗户部分——石漏窗、石窗洞；入口部分——石门头、门楼、门枕石、抱鼓石、上马石、拴马石、门洞、门槛石；地面部分——石铺地、石柱础（覆盆式、圆鼓式等）、石栏杆；庭院部分——鱼池、石桌凳、水井、景观置石、石花坛、村碑；建筑构件及构筑物——牌坊（通体石雕）、宗祠中的石柱、雀替、梁架等。"},{"id":"m3-qa-M3Q014","questions":["徽州木雕的代表性建筑是哪一座？有什么特点？","承志堂的木雕为什么出名？","宏村承志堂的木雕有哪些题材？","《唐肃宗宴官图》木雕在哪里？"],"keywords":["模块三","匠艺流芳","三雕代表作","木雕","承志堂"],"answer":"徽州木雕的代表作是宏村承志堂，建于清咸丰五年（1855年），被誉为“民间故宫”。其木雕分布与题材包括：前厅横梁雕刻《唐肃宗宴官图》，长2.26米，描绘文武百官赴宴场景，人物神态各异，是徽州木雕中的极品；轩架处雕刻《郭子仪上寿图》，表现七子八婿同堂祝寿的热闹场面；四根立柱雕刻渔、樵、耕、读四组画面，体现徽商“贾而好儒”的文化追求；另有一件曾误认为《百子闹元宵》的木雕，经考证实为表现“跳加冠”习俗的全景图，为民俗学研究提供了珍贵实物资料。"},{"id":"m3-qa-M3Q015","questions":["徽州石雕的代表性建筑是哪一座？有什么特色？","万松桥的石雕有什么特点？","南屏村万松桥是谁建的吗？","万松桥的石雕装饰包括什么？"],"keywords":["模块三","匠艺流芳","三雕代表作","石雕"],"answer":"徽州石雕的代表作是黟县南屏村的万松桥。该桥建于1788-1790年，是一座三孔石桥，全长26米，宽5米，全由青石垒砌。石雕装饰特色包括：桥面栏杆和石柱上雕刻着凹凸状石雕花纹，经两百多年风雨仍清晰可辨；采用黟县青石为材，纹样以动植物为主，风格古朴雅致；桥墩前伸出长约两米多的舌状“鱼嘴”，巧妙地分流溪水，保护桥墩；桥头立有方形石碑，刻有桐城派大家姚鼐所作《万松桥记》全文，姚鼐在文中高度评价捐资建桥的叶氏兄弟“因祸得福，转败为功，岂非智乎？”"},{"id":"m3-qa-M3Q016","questions":["徽州三雕有多少位国家级非物质文化遗产代表性传承人？分别是谁？","徽州三雕的国家级传承人名单","国家级徽州三雕传承人有哪些？","砖雕、石雕、木雕的国级传承人分别是谁？"],"keywords":["模块三","匠艺流芳","三雕传承人","三雕","木雕","石雕","砖雕","传承"],"answer":"根据中国非物质文化遗产网数据，徽州三雕国家级代表性传承人共8位：方新中（砖雕，安徽省黄山市）、冯有进（石雕，安徽省黄山市）、王金生（木雕，安徽省黄山市）、俞有桂（木雕，江西省婺源县，项目为“徽州三雕（婺源三雕）”）、蒯正华（木雕，安徽省黄山市）、曹永盛（木雕，安徽省黄山市）、吴正辉（砖雕，安徽省黄山市）、俞友鸿（木雕，江西省婺源县，项目为“徽州三雕（婺源三雕）”）。"},{"id":"m3-qa-M3Q017","questions":["徽州三雕省级非物质文化遗产代表性传承人有哪些？","省级徽州三雕传承人名单","除了国家级，还有哪些省级三雕传承人？","婺源县有哪些省级三雕传承人？"],"keywords":["模块三","匠艺流芳","三雕传承人","三雕","木雕","石雕","砖雕","传承"],"answer":"省级徽州三雕传承人（含国家级）共23位。按批次和地区包括：第一批王金生、曹永盛（均为黄山市木雕）；第二批郑尧锦（黄山市木雕）；第三批吴正辉（歙县砖雕）、蒯正华（屯溪区木雕）、吴林水（歙县砖雕）；第四批朱泓（徽州区木雕、竹雕）；第五批朱伟（徽州区竹木雕）、汪裕民（休宁县石雕）、方乐成（歙县砖雕）、王永强（黟县砖雕）、胡善云（绩溪县木雕）；第六批程长进（黄山市石雕）、汪德洪（黟县木雕）、胡适生（绩溪县木雕）；第七批方惠雄（歙县砖雕）、胡荣军（休宁县石雕）、詹华平（黟县石雕）、鲍学寨（黟县砖雕）、宋文革（绩溪县砖雕）、倪振兴（绩溪县木雕）；另有婺源县的姜晓林（第三批木雕）、汪建勇（第一批砖雕）。"},{"id":"m3-qa-M3Q018","questions":["徽州三雕有哪些重要的师徒传承关系？","曹永盛的师傅是谁？","蒯正华师从哪些人？","吴正辉的师承关系是怎样的？"],"keywords":["模块三","匠艺流芳","三雕传承人","三雕","木雕","传承","非遗"],"answer":"徽州三雕的重要师徒传承关系包括：曹永盛先师从姑父方莳田，后又师从苏州言伯泉、林贞瑞进修；蒯正华先后师从东阳木雕吕闪雷、合肥工艺美术厂张参忠以及国家级传承人王金生；吴正辉的唯一公开师承是歙县老艺人胡达成，也曾请教宋文革（非严格师徒）；王金生师从汪叙伦；俞有桂师从俞坤来和何超群；吴林水1978年师从吴能华，1992-1995年师从方新中，之后又传艺给吴梓祥、汪灶辉、洪华等六人；朱伟师从谢紫贵，朱泓与朱伟是兄弟关系，共同创建徽州竹艺轩雕刻厂；汪裕民1980年师从汪火英；冯有进传艺给市级非遗传承人汪金德。"},{"id":"m3-qa-M3Q019","questions":["徽州木雕的工艺流程是怎样的？","木雕是怎么做出来的？","徽州木雕从选料到打磨有哪些步骤？","木雕为什么要涂桐油？"],"keywords":["模块三","匠艺流芳","三雕工艺","木雕"],"answer":"徽州木雕的工艺流程严谨有序：第一步选料，精选干燥无裂的枫木、樟木、楠木等，按构件尺寸裁切；第二步放样，用木炭棒在木面绘制图案布局；第三步打粗坯，用斧头、硬木锤打出大形；第四步打中坯，分出层次；第五步精雕，换细凿雕出衣纹、羽毛等细节；第六步打磨，用粗细砂纸逐级打磨至光滑；第七步上漆或涂油，搭天然桐油或上生漆，既能防腐，又能凸显木纹质感。"},{"id":"m3-qa-M3Q020","questions":["徽州石雕的工艺流程是怎样的？","石雕是怎么雕刻的？","徽州石雕使用什么工具？","石雕为什么要保留刀痕？"],"keywords":["模块三","匠艺流芳","三雕工艺","石雕"],"answer":"徽州石雕的工艺流程如下：先挑选纹理顺直、无暗裂的荒料（多为黟县青石或茶园石），按尺寸切割整形；用墨线将图案直接画于石面起稿；用大錾、剁斧“打荒”去除多余石料，再用扁錾打糙定轮廓；之后掏挖透雕的空当，避免石材崩裂；用细刻刀与小锤精雕细节；最后用磨石与细砂反复打磨，部分构件会保留刀痕以增强质感。棠樾牌坊群、许国石坊即是石雕工艺的巅峰代表。"},{"id":"m3-qa-M3Q021","questions":["徽州砖雕的工艺流程有什么特别之处？","砖雕是怎么烧制和雕刻的？","徽州砖雕为什么能雕出多层？","水磨青砖是怎么制作的？"],"keywords":["模块三","匠艺流芳","三雕工艺","砖雕"],"answer":"徽州砖雕的工艺极为讲究，特别之处在于：首先选用细腻黄黏土，经筛滤、踩泥、阴干制成砖坯，再经控温烧制并窖水，形成青灰色致密的水磨青砖；验收合格后，用木炭棒在砖面放样；用平凿打坯，分出物象的深浅层次；接着换细凿“出细”，雕琢人物面部、花鸟叶脉等细节，徽州砖雕擅长多层透雕，可达九层；之后整体打磨，修补细小缺损；最后拼接安装，部分复杂构件采用榫卯挂镶工艺，确保百年不脱落。门楼、门罩是砖雕最集中的区域。"},{"id":"m3-qa-M3Q022","questions":["什么是徽州三雕？总体特点是什么？","徽州三雕指的是哪三雕？","三雕的艺术价值是什么？","为什么说“无雕不成屋”？"],"keywords":["模块三","匠艺流芳","三雕概况","三雕","木雕","石雕","砖雕"],"answer":"徽州三雕是徽派建筑中木雕、石雕、砖雕三种雕刻艺术的合称，主要流行于古徽州府域（今黄山、歙县、黟县等地），是徽商财富与文人审美交融的结晶。三者同源而异技，以“精雕细琢、寓意吉祥”为精髓，题材涵盖忠孝典故、山水花鸟、吉祥图案等，兼具实用与教化功能，构筑起“无雕不成屋”的雅致格调。木雕多用枫、樟、楠木，饰于梁架、隔扇；石雕取黟县青石，见于牌坊、柱础；砖雕用特制青砖，妆点门楼、屋檐。作为国家级非物质文化遗产，徽州三雕是解读徽文化的鲜活密码。"},{"id":"m3-qa-M3Q023","questions":["研究徽州三雕有哪些重要的学术论文？","有没有关于徽州砖雕的系统研究？","徽州木雕的学位论文有哪些？","石雕研究可以参考哪些文献？"],"keywords":["模块三","匠艺流芳","三雕文献与数据","三雕","木雕","石雕","砖雕","传承"],"answer":"研究徽州三雕的重要学位论文包括：王子洋《徽州传统建筑砖雕研究》（安徽建筑大学，2020）、陈金康《徽州木雕技艺及现代传承研究》（安徽建筑大学，2024）、郝新宇《徽州石雕技艺及其当代应用研究》（安徽建筑大学，2025）、杨阳《徽州地区传统建筑石材匠作研究》（合肥工业大学，2017）、杨欢《徽派建筑中砖雕的艺术特征研究》（苏州大学，2015）。此外还有大量期刊论文，如陈玲玲、童焱、沈姝君、岳超辉等学者关于木雕的论文，以及张念伟、刘咏松、陈厚娟等关于砖雕的论文。"},{"id":"m3-qa-M3Q039","questions":["罗愿的《新安志》对徽州建筑研究有什么价值？","《新安志》记载了哪些徽州建筑信息？","罗愿是什么时代的人？","最早的徽州方志是哪一部？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","新安志"],"answer":"罗愿（1136-1184）是徽州歙县人，南宋方志学家、博物学家。他所著的《新安志》成书于南宋淳熙二年（1175年），是徽州现存最早的官方府志。书中首次系统记载了徽州城池、祠庙、寺观、民居的基础形制，最早提及徽州民居“粉墙瓦舍、天井院落”的雏形，以及官式建筑的屋顶规制，是徽州古建筑最早的可信文献记录，为后世研究徽州建筑的起源与早期发展奠定了文献基础。权威来源为宋淳熙刻本残卷（中国国家图书馆藏孤本）。"},{"id":"m3-qa-M3Q040","questions":["朱熹的《家礼》如何影响了徽州建筑的布局？","《家礼》规定了徽州建筑的哪些礼制？","为什么徽州民居都是前厅后堂、中轴对称？","朱熹对徽派建筑有什么贡献？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"朱熹（1130-1200）祖籍徽州婺源，南宋理学家、礼制学家。他所著的《家礼》成书于南宋淳熙三年（1176年），是徽州所有民居、祠堂、牌坊营造的核心礼制规范。书中明确了徽州建筑“前厅后堂、天井中庭、左右厢房、中轴对称”的核心布局，划定了祠堂开间、屋顶形制、马头墙等级的礼制标准，并定义了天井“四水归堂”的文化内涵。徽州现存明清古建筑均严格遵循《家礼》制定的营造礼制，因此朱熹被称为“徽州古建筑的礼制体系奠基者”。"},{"id":"m3-qa-M3Q041","questions":["弘治《徽州府志》首次系统记载了马头墙的什么特征？","明代府志中马头墙叫什么？","弘治《徽州府志》的作者是谁？","这部府志有多少幅建筑图？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","徽州府志","马头墙"],"answer":"弘治《徽州府志》成书于明弘治十五年（1502年），由彭泽修、汪舜民（徽州婺源人）纂。它是明代最完整的徽州官方府志，**首次系统且明确记录了马头墙（当时称“封火山墙”）的叠落形制、粉墙黛瓦的营造标准、天井的采光排水设计**，并附有35幅建筑舆图，完整覆盖徽州6县的民居、祠堂、牌坊、官署建筑规制。汪舜民因此被称为徽州建筑规制的重要整理者。"},{"id":"m3-qa-M3Q042","questions":["康熙《徽州府志》对天井和马头墙有什么描述？","清代哪部府志记载了“五岳朝天”？","赵吉士对徽州建筑有什么贡献？","康熙《徽州府志》有多少幅建筑图？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","徽州府志","马头墙"],"answer":"康熙《徽州府志》成书于清康熙三十八年（1699年），由赵吉士（1628-1706，徽州休宁人）纂修。它是清代最权威的徽州府志，含府县治、书院、祠堂、牌坊、民居图37幅，**系统描述了徽州建筑“四水归堂”的天井形制、“五岳朝天”的五叠马头墙规制、粉墙黛瓦的审美特征、祠堂抬梁穿斗混合木构的屋顶做法**，并详细记载了徽州6县民居建筑的地域差异。赵吉士因此被誉为“清代徽州建筑规制的集大成者”。"},{"id":"m3-qa-M3Q043","questions":["道光《徽州府志》在建筑记载方面有什么特点？","清代集大成的徽州府志是哪一部？","道光《徽州府志》有多少幅建筑图？","《营建志》记载了哪些内容？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","徽州府志"],"answer":"道光《徽州府志》成书于清道光七年（1827年），由马步蟾纂修，是清代徽州府志的集大成之作。志首附建筑图37幅，包括徽州府山阜水源总图、府治城垣图、学宫图、书院图，并专设《营建志》，完整记录徽州民居、祠堂、牌坊的营造工法、尺寸规范。该书是清代中期徽州建筑最全面的官方记载，权威来源为清道光七年刻本（中国国家图书馆、安徽省图书馆藏全本）。"},{"id":"m3-qa-M3Q044","questions":["《鲁班经匠家镜》在徽州工匠中有什么地位？","《鲁班经》记载了哪些营造尺寸？","午荣是谁？","徽州建筑的营造尺度依据什么？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","鲁班经","马头墙"],"answer":"《鲁班经匠家镜》成书于明万历三十四年（1606年），由明代民间匠师午荣汇编。它是明清时期徽州工匠人手一册的营造圭臬，**完整记载了江南民居（核心含徽州）的马头墙营造尺寸、天井的开间进深比例、粉墙的抹灰工艺、屋顶的瓦作规制、木构的榫卯做法**。徽州现存明清民居、祠堂的营造尺寸与形制均与此书完全契合，因此被称为“徽州民间建筑营造的核心法典”。权威来源为明万历三十四年汇贤斋刻本（上海图书馆藏）。"},{"id":"m3-qa-M3Q045","questions":["计成的《园冶》对徽州建筑有什么影响？","计成是哪里人？","《园冶》记载了哪些徽州建筑手法？","徽州民居与园林结合的经典著作是什么？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"计成（1582-约1642）是明末造园家，虽原籍吴江，但核心造园实践均在徽州地区，为徽州歙县、休宁的徽商家族营造了大量园林宅第。他所著的《园冶》成书于明崇祯四年（1631年），专门记载了徽州园林与民居 **“高墙天井、漏窗借景、粉墙衬景、马头墙框景”** 的营造手法，详细描述了徽州建筑的墙体、屋顶、天井、门窗的营造细节与审美标准。该书深刻影响了徽州民居与园林的融合发展，是研究徽州建筑不可或缺的典籍。"},{"id":"m3-qa-M3Q046","questions":["程敏政主修的嘉靖《休宁县志》记录了哪些建筑特征？","程敏政是什么人？","休宁县志中如何描述粉墙黛瓦？","明代县域建筑最早的系统记载是哪部方志？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"程敏政（1446-1499）是徽州休宁人，明成化榜眼，著名学者、方志学家。他主修的嘉靖《休宁县志》成书于明嘉靖二十九年（1550年），详细记载了休宁村落布局、民居形制、祠堂结构、牌坊规制，**明确记录了徽州民居“粉墙黛瓦、天井中庭、马头墙叠落、木构雕饰”的核心特征**，并附多幅村落、祠堂建筑图。该书是徽州县域古建筑最早的系统记载，为民间建筑的营造提供了标准化参考。"},{"id":"m3-qa-M3Q047","questions":["张佩芳纂修的乾隆《歙县志》有何建筑价值？","歙县志记载了哪些徽商民居细节？","张佩芳是什么人？","乾隆《歙县志》有多少建筑图？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"张佩芳（1732-1793）是徽州歙县人，清代方志学家。他纂修的乾隆《歙县志》成书于清乾隆三十六年（1771年），详细记载了歙县徽商民居 **“高墙封闭、马头翘角、天井采光排水、木构梁架屋顶、粉墙装饰”** 的完整营造细节，并附歙县县城、祠堂、牌坊的建筑图。该书是徽州核心县域古建筑的权威记载，权威来源为清乾隆三十六年刻本（安徽博物院藏）。"},{"id":"m3-qa-M3Q048","questions":["俞正燮纂修的嘉庆《黟县志》为什么重要？","俞正燮是什么人？","西递宏村最早的文献记录是哪部志书？","黟县志记载了哪些村落建筑？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"俞正燮（1775-1840）是徽州黟县人，清代著名学者。他纂修的嘉庆《黟县志》成书于清嘉庆十七年（1812年），专门记述了黟县西递、宏村等古村落的民居形制，**详细描述了天井连缀的院落布局、马头墙的错落防火设计、粉墙的营造工艺、依山就势的屋顶排水做法**。这是世界文化遗产西递、宏村古建筑最早的系统文献记录，权威来源为清嘉庆十七年刻本（中国科学院图书馆藏）。"},{"id":"m3-qa-M3Q049","questions":["江峰青的《婺源乡土志》为什么是1910年前最晚的徽州建筑文献？","婺源乡土志成书于哪一年？","江峰青是什么人？","清代晚期徽州建筑的最新记录是哪本书？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"江峰青（1860-1931）是徽州婺源人，清代学者。他所纂的《婺源乡土志》成书于清光绪三十四年（1908年），严格符合1910年前的时间要求，是清代晚期徽州建筑的最新文献记录。书中专门记述了婺源古村落的民居建筑，**明确记载了婺源民居“粉墙瓦檐、马头墙防火、天井聚气排水、硬山屋顶”的核心特征**，记录了清代晚期徽州建筑的最终发展形态。权威来源为清光绪三十四年刻本（复旦大学图书馆藏）。"},{"id":"m3-qa-M3Q050","questions":["《新安大族志》对研究徽州祠堂有什么价值？","程一枝是什么人？","徽州宗族建筑的核心文献是什么？","《新安大族志》附有哪些建筑图？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"《新安大族志》成书于明嘉靖二十八年（1549年），由程一枝（1532-1582，徽州休宁人，明代谱牒学家）纂修。该书详细记载了徽州程、汪、吴、黄、胡等各大宗族的祠堂、宅第的布局、结构、装饰、营造规制，并附有祠堂、宅第的平面图、立面图。它是徽州宗族建筑（祠堂、府第）的核心文献，权威来源为明嘉靖抄本（北京师范大学图书馆藏）。"},{"id":"m3-qa-M3Q051","questions":["顾炎武在《天下郡国利病书》中如何描述徽州建筑？","顾炎武去过徽州吗？","清初思想家对徽州马头墙有什么记录？","《天下郡国利病书》记载了徽州哪些建筑特征？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"顾炎武（1613-1682）是明末清初思想家、地理学家，曾亲自游历徽州实地考察。他在《天下郡国利病书·江南备要·徽州府》中记载了徽州 **“地窄人稠，屋宇密集，马头墙以御火，天井以通风采光，高墙以御盗，粉墙以防潮”** 的建筑特征。这是明末清初徽州古建筑的一手实地考察记录，权威来源为清康熙三年刻本（上海图书馆藏）。"},{"id":"m3-qa-M3Q052","questions":["徐霞客在游记中如何评价徽州民居？","徐霞客去过徽州哪些地方？","明代旅行家眼中的徽州建筑什么样？","《徐霞客游记》记录了哪些徽州建筑特征？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"徐弘祖（徐霞客，1587-1641）是明代地理学家、旅行家，曾亲自游历徽州歙县、休宁、黟县等地。他在《徐霞客游记·江右游日记·徽州府》中记录了徽州 **“白屋依山而建，马头墙连绵错落，天井幽深，粉墙映山，木构精巧”** 的建筑特征。这是明代徽州古建筑的一手旅行考察记录，权威来源为明崇祯抄本（上海图书馆藏孤本）。"},{"id":"m3-qa-M3Q053","questions":["李渔的《闲情偶寄·居室部》对徽州建筑审美有什么影响？","李渔是什么人？","“粉墙宜白、瓦宜青”出自哪本书？","清代徽州民居的审美理念受谁影响？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"李渔（1611-1680）是明末清初文学家、造园家，曾多次游历徽州，为徽商家族营造园林宅第。他所著的《闲情偶寄·居室部》成书于清康熙十年（1671年），专门记述了 **“粉墙宜白、瓦宜青、天井宜小而深、墙宜高而峻、门窗宜漏而透”** 的营造理念，这些理念完全契合徽州建筑的审美与营造法则，深刻影响了清代徽州民居与园林的融合发展。"},{"id":"m3-qa-M3Q054","questions":["《三才图会·宫室卷》为徽州建筑提供了什么可视化资料？","明代百科式图录中如何绘制马头墙？","王圻、王思义是什么人？","徽州工匠参考过哪本图谱？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"《三才图会·宫室卷》成书于明万历三十七年（1609年），由明代学者王圻、王思义编纂。这是一部明代百科式图录，**绘制了江南民居（含徽州核心类型）的马头墙、天井、粉墙、硬山屋顶的完整图式**，并标注了营造尺寸。它是徽州建筑形制最早的可视化图谱之一，徽州工匠多参考此图谱营造。权威来源为明万历三十七年刻本（北京大学图书馆藏）。"},{"id":"m3-qa-M3Q055","questions":["赵翼的《檐曝杂记》如何记录徽州民居？","赵翼是什么人？","清代中期徽州建筑的一手记录出自哪本书？","“天井如井”是谁的描述？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"赵翼（1727-1814）是清代史学家、文学家，曾游历徽州。他在《檐曝杂记·徽州民居》中专门记载了 **“徽州人屋宇，皆高墙峻宇，马头墙参差高下，天井如井，通风采光，粉墙素净，不施彩绘，为江南民居之特色”** 。这是清代中期徽州古建筑的一手实地记录，权威来源为清嘉庆湛贻堂刻本（中国国家图书馆藏）。"},{"id":"m3-qa-M3Q056","questions":["喻皓的《木经》对徽州木构有什么影响？","喻皓是谁？","“造塔鲁班”指的是谁？","徽州穿斗式木构的源头是什么？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"喻皓是五代末北宋初著名建筑匠师，被誉为“造塔鲁班”。他所著的《木经》成书于北宋端拱二年（989年），是中国古代最早的民间木构建筑典籍，记载了江南木构建筑的营造法则。徽州建筑的**穿斗式木构、屋顶举折、榫卯做法**，均继承了《木经》的技法，是徽州民间木构营造的早期源头。权威来源为明陶宗仪辑《说郛》本（中国国家图书馆藏）。"},{"id":"m3-qa-M3Q057","questions":["《阳宅十书》和《阳宅三要》如何影响徽州民居的风水布局？","徽州民居的“四水归堂”出自哪本风水书？","王君荣和赵九峰是什么人？","徽州人盖房子为什么讲究“门、主、灶”？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"《阳宅十书》成书于明万历三十四年（1606年），由明代民间风水学家王君荣纂修，是明代民间阳宅风水核心典籍。徽州民居的布局、天井设置、马头墙形制、门向选择、房屋开间进深，均严格遵循其“天井聚气、高墙挡煞、马头墙镇宅、四水归堂”的风水理论。《阳宅三要》成书于清乾隆元年（1736年），由清代民间风水学家赵九峰纂修，提出的“门、主、灶”阳宅三要深刻影响了徽州民居的门向、堂屋、天井的布局。两者是徽州民居营造的核心风水参考。"},{"id":"m3-qa-M3Q058","questions":["柳宗元的《梓人传》对徽州工匠体系有什么影响？","《梓人传》记载了什么？","唐代文献如何描述古代工匠？","徽州营造匠师体系的源头是什么？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"柳宗元（773-819）是唐代文学家、思想家。他所著的《梓人传》成书于唐永贞元年（805年），系统记述了古代梓人（营造工匠）的**营造制度、设计方法、施工管理体系**，确立了古代工匠的营造范式。徽州明清时期的工匠体系、营造流程、设计方法，均继承了《梓人传》中记载的传统，因此被称为“徽州营造匠师体系的源头文献”。"},{"id":"m3-qa-M3Q059","questions":["恩斯特·伯施曼对徽州建筑研究有什么特殊贡献？","西方最早科学考察徽州建筑的学者是谁？","伯施曼拍摄了多少徽州建筑照片？","1910年前徽州建筑唯一的科学影像记录是谁留下的？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"恩斯特·伯施曼（Ernst Boerschmann，1873-1949）是德国皇家柏林工业高等学院教授，西方中国建筑研究先驱。1906-1909年，他以德国驻北京公使馆官方科学顾问身份，亲自赴徽州实地考察，**拍摄了大量徽州祠堂、民居、牌坊、马头墙、天井的原版照片，测绘了建筑图纸**。他是西方学界最早对徽州古建筑进行系统科学考察与记录的学者，也是1910年前徽州古建筑唯一的科学影像记录者。其成果收录于1914年出版的《中国的建筑与宗教文化》中。"},{"id":"m3-qa-M3Q060","questions":["伊东忠太和关野贞对徽州建筑研究有什么贡献？","日本学者何时开始研究徽州建筑？","伊东忠太的《中国建筑史》记载了徽州什么？","关野贞在徽州测绘了哪些建筑？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"伊东忠太（1867-1954）是日本东京帝国大学教授，近代日本顶尖建筑史学家。1902年他赴中国实地考察，足迹覆盖徽州歙县、休宁等地，测绘并记录了徽州祠堂、牌坊、民居的建筑形制，首次将徽州古建筑纳入中国建筑史的系统研究体系，其所著《中国建筑史》中专门记载了徽州马头墙、天井、木构的营造特征。关野贞（1868-1935）同样是日本东京帝国大学教授，1906年专门赴徽州测绘了大量祠堂、牌坊、民居，详细记录了徽州马头墙的营造尺寸、天井的布局比例、木构的榫卯结构。两位学者的考察为徽州建筑研究留下了宝贵的一手测绘资料。"},{"id":"m3-qa-M3Q061","questions":["胡重是谁？她对徽州建筑有什么贡献？","宏村的总规划师是谁？","牛形水系是谁设计的？","中国历史上著名的女性村落规划师是哪位？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"胡重是明代徽州黟县人，被誉为“世界文化遗产宏村的总规划者”。明永乐年间，她主持完成了黟县宏村牛形村落水系与整体建筑布局的总体规划，联合风水师何可达完成了宏村的地形勘测与建筑排布规范，确定了宏村民居**依山傍水、天井连缀、马头墙错落、粉墙黛瓦沿水系排布**的核心形制，规范了宏村300余栋明清民居的营造尺度与院落布局。她设计的水圳、月沼、南湖水系与建筑的融合范式，成为徽州古村落建筑规划的标杆。"},{"id":"m3-qa-M3Q062","questions":["何可达在宏村规划中扮演什么角色？","与胡重合作的风水师是谁？","宏村的地形勘测由谁完成？","何可达对徽州村落建筑有什么贡献？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"何可达是明永乐年间的徽州黟县人，著名风水营造家、村落建筑规划师。他与胡重联合完成了宏村的地形勘测与整体规划，制定了宏村“牛形村落”的建筑布局与水系规范，明确了民居建筑的朝向、天井尺度、马头墙排布的营造规则，解决了徽州山区村落的消防、排水、通风与建筑排布问题。他是徽州古村落建筑规划的标志性人物。"},{"id":"m3-qa-M3Q063","questions":["胡光文是谁？他建造了哪座著名牌坊？","许国石坊是谁设计的？","明代徽州石作匠师的代表人物是谁？","中国唯一的八脚牌坊由谁主持建造？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"胡光文是明嘉靖至万历年间徽州歙县人，明代顶尖石作、木作营造匠师，被誉为“徽州牌坊建筑集大成者”。明万历十二年（1584年），他主持设计并建造了歙县许国石坊——中国现存唯一的八脚牌坊，也是徽州牌坊建筑的巅峰之作。他还参与了歙县数十座祠堂、民居的木构、石作营造，完善了徽州马头墙的石作基座、祠堂抬梁式木构的营造技法，是明代徽州民间建筑匠师的核心代表人物。"},{"id":"m3-qa-M3Q064","questions":["汪定贵建造的承志堂为什么被称为“民间故宫”？","承志堂是谁建造的？","宏村承志堂有多大？","汪定贵是什么人？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","三雕","承志堂","马头墙"],"answer":"汪定贵（1820-1891）是清代徽州黟县人，徽商、民居营造家。清咸丰五年（1855年），他主持设计并建造了黟县宏村承志堂，该建筑被誉为“民间故宫”和“徽派民居的巅峰之作”。承志堂完整融合了徽州建筑**天井连缀、马头墙叠落、粉墙黛瓦、三雕装饰、木构梁架**的所有核心特征，规范了徽商大宅的营造范式，其设计的天井通风排水系统、马头墙防火形制，被徽州各地民居广泛效仿。"},{"id":"m3-qa-M3Q065","questions":["李诫的《营造法式》对徽州建筑有什么规范作用？","《营造法式》的作者是谁？","宋代官式建筑法典如何影响徽州？","徽州祠堂的官式做法源自哪本书？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","营造法式","李诫"],"answer":"李诫（？-1110）是北宋将作监丞，中国古代顶尖建筑科学家，官式建筑法典制定者。他所著的《营造法式》成书于宋崇宁二年（1103年），是中国古代官式建筑的核心法典。徽州建筑的**木构梁架、瓦作、砖作、石作、彩画**营造技法，均严格遵循此书规范，是徽州建筑木构体系、屋顶规制的核心源头。徽州明清祠堂、牌坊的官式做法均来自此书，权威来源为宋崇宁二年刻本残卷（故宫博物院藏）。"},{"id":"m3-qa-M3Q066","questions":["郑玄注《考工记》如何影响了徽州建筑的布局理念？","《考工记》是什么时代的著作？","郑玄是谁？","徽州建筑“前厅后堂、中轴对称”的源头是什么？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"《考工记》是先秦时期齐国官书，儒家核心经典《周礼》的组成部分，是中国古代最早的营造典籍。东汉经学大师郑玄（127-200）为其作注，系统阐释了**“前朝后寝、中轴对称、匠人营国”**的营造理念。这一理念是徽州民居、祠堂“前厅后堂、中轴对称、天井居中”布局的核心源头，深刻影响了徽州建筑的礼制布局。权威来源为宋刻本《周礼注疏》。"},{"id":"m3-qa-M3Q067","questions":["王圻、王思义编纂的《三才图会》对徽州工匠有什么实用价值？","明代工匠如何获取建筑图样？","《三才图会》中的马头墙图式准确吗？","哪本明代图谱标注了营造尺寸？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"王圻（1530-1615）与王思义（明万历年间）父子编纂的《三才图会·宫室卷》成书于明万历三十七年（1609年），是一部明代百科式图录。该书**绘制了江南民居（含徽州核心类型）的马头墙、天井、粉墙、硬山屋顶的完整图式，并标注了营造尺寸**，是徽州建筑形制最早的可视化图谱之一。由于图文并茂、尺寸明确，徽州工匠多参考此图谱进行营造，具有很强的实用价值。"},{"id":"m3-qa-M3Q068","questions":["蒯祥对徽州建筑有什么间接影响？","蒯祥是谁？","明代官式建筑规范由谁确立？","徽州祠堂的官式做法与故宫有关吗？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"蒯祥（1398-1481）是明代香山帮匠首，明代顶尖官式建筑营造家。他主持设计并建造了北京故宫、明十三陵等明代核心官式建筑，完善了明代官式建筑的抬梁式木构、屋顶规制、石作技法。徽州明清祠堂、牌坊的官式营造技法，直接继承了蒯祥确立的明代官式建筑规范。虽然蒯祥并非徽州人，但他的建筑规范通过官方传播深刻影响了徽州的高等级建筑。"},{"id":"m3-qa-M3Q069","questions":["郑玄注《周礼》中的“匠人营国”理念如何体现在徽州村落中？","徽州村落为什么讲究中轴对称？","“前朝后寝”在徽州民居中如何表现？","《考工记》的礼制思想在徽州建筑中有哪些实例？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"郑玄（127-200）为《周礼·考工记》作注时，阐释了“匠人营国”的营造理念，强调“前朝后寝、中轴对称、经纬分明”。这一理念深刻影响了徽州村落的规划与建筑布局。具体体现在：徽州祠堂采用中轴线对称布局，门楼、享堂、寝堂依次排列；徽州民居以天井为中心，前厅后堂、左右厢房对称分布；宏村、西递等村落的主街与支巷呈鱼骨状对称延伸。这些布局都是“中轴对称”理念在徽州建筑中的具体实践。"},{"id":"m3-qa-M3Q070","questions":["《黄山图经》记载了徽州山居建筑的哪些早期形制？","最早的徽州山地建筑文献是哪部？","宋代黄山地区的寺院建筑有什么特点？","《黄山图经》的作者是谁？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"《黄山图经》成书于宋景祐三年（1036年），由僧行明等纂修，是宋代黄山地区的地理图志。书中记载了黄山周边徽州地区的寺院、山居建筑，**记录了徽州山居“依山就势、粉墙瓦舍、天井庭院、硬山屋顶”的早期形制**。这是徽州山地建筑最早的文献记录，权威来源为宋景祐刻本残卷（安徽大学徽学研究中心藏）。"},{"id":"m3-qa-M3Q071","questions":["万历《祁门县志》和乾隆《绩溪县志》分别记载了哪些徽州建筑特色？","祁门县祠堂建筑有什么特点？","绩溪县民居的天井和马头墙如何描述？","徽州山区建筑与平原地区有何不同？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"万历《祁门县志》成书于明万历二十八年（1600年），详细记载了祁门善和村、左田村等宗族村落的祠堂、民居的基址、结构、营造规制，记录了徽州山区民居的天井布局、马头墙形制、木构屋顶的山地适应做法，是徽州山区建筑的核心记载。乾隆《绩溪县志》成书于清乾隆二十一年（1756年），记载了绩溪胡氏、汪氏等大宗族的民居、祠堂建筑，详细描述了 **“天井深幽、马头墙高耸、木构精巧、粉墙素净”** 的建筑特征，是徽州北乡建筑的权威记载。"},{"id":"m3-qa-M3Q072","questions":["《休宁西门汪氏族谱》中附有哪些建筑图？为什么重要？","明代族谱中会记载祠堂平面图吗？","汪氏宗祠的结构在哪里有详细记录？","徽州祠堂最完整的明代原始记录是哪部族谱？"],"keywords":["模块三","匠艺流芳","三雕题材与部位","马头墙"],"answer":"《休宁西门汪氏族谱》成书于明嘉靖四十五年（1566年），由徽州休宁汪氏宗族纂修。该族谱附有完整的汪氏宗祠平面图、立面图、民居院落图，**详细记录了祠堂的抬梁穿斗混合木构、马头墙封火、天井藻井、屋顶规制**。它是徽州祠堂建筑最完整的明代原始记录，也是徽州建筑结构最直观的明代一手图录，权威来源为明嘉靖四十五年刻本（安徽大学徽学研究中心藏）。"},{"id":"m3-qa-M3Q073","questions":["乾隆《江南通志》和光绪《安徽通志》如何从官方角度认定徽州建筑？","清代官方如何评价徽州民居？","《江南通志》中记载了徽州建筑的什么特征？","省级通志对徽州建筑有何记载？"],"keywords":["模块三","匠艺流芳","古代著作与科学家","马头墙"],"answer":"乾隆《江南通志》成书于清乾隆元年（1736年），是清代江南省官方通志，专门记载了 **“徽州民居，高墙峻宇，马头墙叠落，天井四水归堂，粉墙黛瓦，为江南民居之冠”** ，这是官方对徽州建筑的权威认定。光绪《安徽通志》成书于清光绪四年（1878年），是安徽省官方通志，专设《宫室志》，详细记述了徽州府6县的民居、祠堂、牌坊、寺观建筑，**明确记载了徽州建筑“粉墙黛瓦，天井深邃，马头墙防火御盗，木构雕饰精美”** 的核心特征。"},{"id":"m3-qa-M3Q074","questions":["俞有桂和俞友鸿是什么关系？他们的传承项目有何不同？","婺源三雕的国家级传承人有哪些？","俞有桂和俞友鸿都传承木雕吗？","徽州三雕（婺源三雕）与徽州三雕有什么区别？"],"keywords":["模块三","匠艺流芳","三雕传承人","三雕","木雕","传承"],"answer":"俞有桂和俞友鸿都是江西省婺源县的徽州三雕国家级非物质文化遗产代表性传承人。俞有桂（序号03-1244）传承木雕，项目名称为“徽州三雕（婺源三雕）”；俞友鸿（序号05-2611）同样传承木雕，项目名称也是“徽州三雕（婺源三雕）”。两人均为婺源地区徽州三雕的重要传承人，但俞有桂为较早批次（第三批），俞友鸿为第五批。婺源三雕是徽州三雕在江西婺源的分支，技艺风格与黄山地区略有差异。"},{"id":"m3-qa-M3Q075","questions":["吴林水的师承关系是怎样的？他传授给了哪些人？","吴林水的师傅是谁？","吴林水的徒弟有哪些？","方新中教过吴林水吗？"],"keywords":["模块三","匠艺流芳","三雕传承人","三雕","砖雕","传承"],"answer":"吴林水是徽州三雕省级非物质文化遗产代表性传承人（第三批，歙县砖雕）。根据安徽省非物质文化遗产网记录，他的师承关系为：1978年师从吴能华；1992-1995年师从方新中（国家级砖雕传承人）。1998-2000年间，吴林水将技艺传授给了吴梓祥、汪灶辉、洪华、朱志利、方德鹏、朱立秋等人。吴林水是歙县砖雕技艺传承的关键中间人物。"},{"id":"m3-qa-M3Q076","questions":["朱伟是朱熹的后代吗？他和朱泓有什么关系？","朱熹第29世孙是谁？","朱泓和朱伟是兄弟吗？","徽州竹艺轩雕刻厂是谁创办的？"],"keywords":["模块三","匠艺流芳","三雕传承人","三雕","木雕","传承"],"answer":"朱伟是徽州人，南宋理学家朱熹的第29世孙。他是徽州三雕省级非物质文化遗产代表性传承人（第五批，徽州区，竹木雕）。朱泓（第四批，徽州区，木雕、竹雕）与朱伟是兄弟关系。2000年，两人共同创建了徽州竹艺轩雕刻厂，致力于徽州木雕、竹雕的传承与创新，将传统雕刻技艺与现代设计相结合。"},{"id":"m3-qa-M3Q077","questions":["方新中除了是国家级传承人，还在传承中担任什么角色？","方新中教过哪些学生？","方新中是什么细分领域的传承人？","歙县砖雕的主要传承人是谁？"],"keywords":["模块三","匠艺流芳","三雕传承人","三雕","砖雕","传承"],"answer":"方新中是徽州三雕国家级非物质文化遗产代表性传承人（序号01-0099），细分领域为砖雕，申报地区为安徽省黄山市。除了自身的技艺传承，他还担任了吴林水的师傅（1992-1995年），为歙县砖雕技艺的传承培养了一代传人。方新中是歙县砖雕技艺的核心代表人物之一。"},{"id":"m3-qa-M3Q078","questions":["徽州砖雕的“鳌鱼”装饰为什么既能避雷又能象征“独占鳌头”？","门楼上的鳌鱼有什么作用？","鳌鱼是龙的一种吗？","徽州砖雕中为什么常见鳌鱼？"],"keywords":["模块三","匠艺流芳","三雕工艺","砖雕"],"answer":"徽州砖雕中的鳌鱼是门楼、屋脊、檐角上常见的装饰题材，造型为龙首鱼身，长须上扬。其象征意义有二：一是“独占鳌头”，寓意科举高中、仕途得意，反映了徽州人崇文重教的传统；二是镇宅避邪，传说鳌鱼能吞雷，因此也被视为避雷的神兽。实际功能上，高耸的鳌鱼脊饰常采用金属或陶制构件，能够起到避雷针的物理作用。徽州工匠将信仰、装饰与实用功能巧妙结合，使鳌鱼成为砖雕中的点睛之笔。"},{"id":"m3-qa-M3Q079","questions":["徽州木雕中“渔樵耕读”题材反映了什么文化追求？","为什么徽州木雕喜欢刻渔樵耕读？","承志堂四根立柱上刻了什么？","“贾而好儒”在木雕中如何体现？"],"keywords":["模块三","匠艺流芳","三雕工艺","木雕","承志堂"],"answer":"“渔樵耕读”是徽州木雕中常见的题材，分别代表渔夫、樵夫、农夫、书生四种职业。在徽州建筑中，这一题材反映了徽商 **“贾而好儒”** 的文化追求：虽然经商致富，但内心向往读书入仕、田园归隐的生活。宏村承志堂四根立柱上就雕刻了渔、樵、耕、读四组画面，体现了主人汪定贵虽为盐商巨富，仍不忘文人雅趣和儒家理想。这一题材也教育后代要重视读书、尊重劳动。"},{"id":"m3-qa-M3Q080","questions":["徽州石雕中的“抱鼓石”有什么作用和常见雕刻图案？","门口的石鼓是干什么用的？","抱鼓石上一般刻什么？","为什么祠堂门口都有抱鼓石？"],"keywords":["模块三","匠艺流芳","三雕工艺","石雕"],"answer":"抱鼓石是徽州建筑入口门枕石的一种形式，位于大门两侧门框的下方，形似圆鼓。其作用有三：一是结构功能，承托门框和门扇的重量；二是装饰功能，通过雕刻美化入口；三是礼制象征，抱鼓石的规格和雕刻精细程度反映了主人的社会地位。常见雕刻图案包括：祥云纹、回纹、缠枝莲、狮子滚绣球、麒麟、蝙蝠（福）、鹿（禄）等吉祥图案。歙县许国石坊、棠樾牌坊群的抱鼓石雕刻尤为精美。"},{"id":"m3-qa-M3Q081","questions":["徽州砖雕中的“清懿堂八字墙”有什么特殊意义？","清懿堂是什么地方？","八字墙上刻了什么女性题材？","徽州砖雕如何体现男女平等思想？"],"keywords":["模块三","匠艺流芳","三雕工艺","砖雕"],"answer":"清懿堂位于歙县棠樾村，是一座女祠，也是徽州砖雕的代表作之一。其八字墙（大门两侧的“八”字形墙体）采用大面积砖雕，题材包括“跪拜母恩”“蝴蝶南瓜图”等。这些题材专门歌颂女性的品德与贡献，体现了徽州文化中尊重女性、重视母教的一面。清懿堂本身是罕见的女性祠堂，与男性祠堂并列，反映了徽州“男女平等”思想的萌芽，是研究徽州妇女史和建筑史的重要实物。"},{"id":"m3-qa-M3Q082","questions":["恩斯特·伯施曼拍摄的徽州建筑照片现存于哪里？","1909年谁拍下了徽州古建筑的原版照片？","伯施曼的徽州考察照片在哪里能看到？","徽州最早的建筑照片保存在哪个博物馆？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"恩斯特·伯施曼（Ernst Boerschmann）1906-1909年在徽州考察期间拍摄的大量原版照片及建筑测绘图，现主要保存在**柏林国家博物馆**。此外，中国国家图书馆藏有其1914年出版的《中国的建筑与宗教文化》初版，书中收录了部分照片。同济大学建筑与城市规划学院数字馆藏也存有这批照片的数字化版本。这些影像是1910年前徽州古建筑唯一的科学影像记录，具有极高的史料价值。"},{"id":"m3-qa-M3Q083","questions":["伊东忠太和关野贞的徽州考察资料现存于哪里？","伊东忠太的徽州测绘资料在哪里可以查到？","关野贞拍摄的徽州照片藏于何处？","日本学者对徽州建筑的早期记录保存在哪？"],"keywords":["模块三","匠艺流芳","古代著作与科学家"],"answer":"伊东忠太1902年考察徽州时留下的一手测绘资料和照片，现主要保存在**东京大学工学部建筑史馆藏**。关野贞1906年考察徽州时测绘的图纸和照片，则收藏于**东京大学东洋文化研究所**。此外，中国国家图书馆藏有《中国建筑史》1925年中文版底本（伊东忠太著）和《中国建筑艺术》1938年版底本（关野贞著），其中收录了部分徽州建筑的内容。这些资料是研究徽州建筑早期国际学术史的重要依据。"}]`);export{e as default};